  const updateSalesOrder = (orderId: string, updates: Partial<SalesOrder>) => {
    setSalesOrders((prev) =>
      prev.map((so) => (so.id === orderId || so.orderNumber === orderId ? { ...so, ...updates } : so))
    );
  };

  const createSalesOrder = (order: Omit<SalesOrder, 'id' | 'orderNumber' | 'status'>): string => {
    const id = `so-${Date.now().toString().slice(-6)}`;
    const randomSuffix = Math.floor(10 + Math.random() * 90).toString();
    const orderNumber = (order as any).orderNumber || `SO-DHK-2026-${Math.floor(100 + Math.random() * 900)}`;

    // Auto-generate official Challan and document numbers matching sample
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const autoChallanNo = (order as any).challanNumber || `BD-ES-${year}-${month}-${randomSuffix}`;
    const autoBillNo = (order as any).billNumber || `${year}${month}${day}-${randomSuffix}`;
    const autoDoNo = (order as any).doNumber || `012/${year}-${randomSuffix}`;
    const autoPoNo = (order as any).poNumber || randomSuffix;

    // Ensure serial numbers are populated for items
    const itemsWithSerials = (order.items || []).map((item, itIdx) => {
      if (item.serialNumbers && item.serialNumbers.length > 0) {
        return item;
      }
      const count = item.quantity || 1;
      const base = itIdx === 0 ? 17158202615 : 171772026316;
      return {
        ...item,
        serialNumbers: Array.from({ length: count }, (_, i) => String(base + i * 5)),
      };
    });

    const newOrder: SalesOrder = {
      ...order,
      id,
      orderNumber,
      userId: order.userId || currentUser?.id,
      employeeId: order.employeeId || currentEmployeeProfile?.employeeId || order.salespersonId,
      employeeCode: order.employeeCode || currentEmployeeProfile?.employeeCode,
      status: 'Submitted',
      challanNumber: undefined,
      billNumber: autoBillNo,
      doNumber: undefined,
      poNumber: autoPoNo,
      deliveryStatus: 'Pending Dispatch',
      items: itemsWithSerials,
      doAccepted: false,
      serialsUpdated: false,
    };
    setSalesOrders((prev) => [newOrder, ...prev]);
    addAuditLog('SALES_ORDER_PLACED', 'Sales & Distribution', `Sales Order ${orderNumber} created for ${newOrder.customerName}. Pending Accounts Rate Verification & Approval. Net: BDT ${newOrder.netAmountBDT.toLocaleString()}`);

    // Persist to Supabase database
    const sb = getSupabase();
    if (sb) {
      // Find numeric IDs if available
      let custIdNum: number | null = null;
      if (order.customerId && /^\d+$/.test(String(order.customerId))) {
        custIdNum = Number(order.customerId);
      } else {
        const matchedCust = customers.find((c) => c.id === order.customerId || c.name === order.customerName);
        if (matchedCust && /^\d+$/.test(String(matchedCust.id))) {
          custIdNum = Number(matchedCust.id);
        }
      }

      let whIdNum: number | null = null;
      if (order.warehouseId && /^\d+$/.test(String(order.warehouseId))) {
        whIdNum = Number(order.warehouseId);
      } else {
        const matchedWh = warehouses.find((w) => w.id === order.warehouseId || w.name === order.warehouseName);
        if (matchedWh && /^\d+$/.test(String(matchedWh.id))) {
          whIdNum = Number(matchedWh.id);
        }
      }

      const payload = {
        order_number: orderNumber,
        customer_id: custIdNum,
        customer_name: order.customerName || 'Direct Customer',
        salesperson_id: order.salespersonId ? String(order.salespersonId) : 'u-1',
        salesperson_name: order.salespersonName || 'Direct Sales',
        warehouse_id: whIdNum,
        warehouse_name: order.warehouseName || 'Main Warehouse',
        order_date: order.date || new Date().toISOString().slice(0, 10),
        gross_amount_bdt: Number(order.subTotalBDT) || 0,
        discount_amount_bdt: Number(order.discountBDT ?? (order as any).discountAmount ?? 0) || 0,
        tax_vat_bdt: Number(order.taxVatBDT) || 0,
        net_amount_bdt: Number(order.netAmountBDT) || 0,
        paid_amount_bdt: Number(order.paidAmountBDT) || 0,
        due_amount_bdt: Number(order.dueAmountBDT ?? (order.netAmountBDT - (order.paidAmountBDT || 0))) || 0,
        status: 'Submitted',
        items_json: itemsWithSerials,
        applied_offer_code: order.appliedOfferCode || null,
        notes: order.notes || null,
      };

      sb.from('sales_orders')
        .insert(payload)
        .select()
        .then(
          ({ data, error }: any) => {
            if (error) {
              console.error('Failed to save sales order to Supabase:', error);
            } else if (data && data[0]) {
              const confirmedId = String(data[0].id);
              setSalesOrders((prev) =>
                prev.map((so) => (so.id === id || so.orderNumber === orderNumber ? { ...so, id: confirmedId } : so))
              );
            }
          },
          (err: any) => {
            console.error('Error inserting sales order into Supabase:', err);
          }
        );
    }

    return id;
  };

  const approveSalesOrder = (orderId: string, updatedOrderData?: Partial<SalesOrder>) => {
    const targetSo = salesOrders.find((so) => so.id === orderId || so.orderNumber === orderId);
    const suffix = (targetSo?.orderNumber || orderId).replace(/\D/g, '').slice(-2) || '88';
    const autoDo = targetSo?.doNumber || `012/2026-${suffix}`;

    setSalesOrders((prev) =>
      prev.map((so) => {
        if (so.id === orderId || so.orderNumber === orderId) {
          return {
            ...so,
            doNumber: so.doNumber || autoDo,
            doGeneratedAt: so.doGeneratedAt || new Date().toISOString(),
            doAccepted: false,
            // CRITICAL: At this stage, NO Challan should be generated
            challanNumber: undefined,
            deliveryStatus: 'Pending Dispatch',
            ...(updatedOrderData || {}),
            status: 'DO Generated',
          };
        }
        return so;
      })
    );

    const logDesc = updatedOrderData?.items
      ? `Order ${targetSo?.orderNumber || orderId} reviewed and approved by Accounts. Factory Delivery Order (D.O. #${autoDo}) generated. Pending Factory DO Review & Acceptance.`
      : `Order ${targetSo?.orderNumber || orderId} approved by Accounts. Factory Delivery Order (D.O. #${autoDo}) generated. Pending Factory DO Review & Acceptance.`;
    addAuditLog('ORDER_APPROVED', 'Accounts & Commercial', logDesc);

    const sb = getSupabase();
    if (sb) {
      const isNumeric = /^\d+$/.test(orderId);
      const updatePayload: any = {
        status: 'DO Generated',
      };
      if (updatedOrderData?.items) {
        updatePayload.items_json = updatedOrderData.items;
      }
      if (updatedOrderData?.subTotalBDT !== undefined) {
        updatePayload.gross_amount_bdt = updatedOrderData.subTotalBDT;
      }
      if (updatedOrderData?.discountBDT !== undefined) {
        updatePayload.discount_amount_bdt = updatedOrderData.discountBDT;
      }
      if (updatedOrderData?.taxVatBDT !== undefined) {
        updatePayload.tax_vat_bdt = updatedOrderData.taxVatBDT;
      }
      if (updatedOrderData?.netAmountBDT !== undefined) {
        updatePayload.net_amount_bdt = updatedOrderData.netAmountBDT;
      }
      if (updatedOrderData?.dueAmountBDT !== undefined) {
        updatePayload.due_amount_bdt = updatedOrderData.dueAmountBDT;
      }
      if (updatedOrderData?.warehouseId !== undefined || updatedOrderData?.warehouseName !== undefined) {
        let whIdNum: number | null = null;
        if (updatedOrderData.warehouseId && /^\d+$/.test(String(updatedOrderData.warehouseId))) {
          whIdNum = Number(updatedOrderData.warehouseId);
        } else {
          const matchedWh = warehouses.find(
            (w) =>
              w.id === updatedOrderData.warehouseId ||
              w.name === updatedOrderData.warehouseName
          );
          if (matchedWh && /^\d+$/.test(String(matchedWh.id))) {
            whIdNum = Number(matchedWh.id);
          }
        }
        if (whIdNum !== null) {
          updatePayload.warehouse_id = whIdNum;
        }
        if (updatedOrderData.warehouseName !== undefined) {
          updatePayload.warehouse_name = updatedOrderData.warehouseName;
        }
      }
      if (updatedOrderData?.notes !== undefined) {
        updatePayload.notes = updatedOrderData.notes;
      }

      const query = isNumeric
        ? sb.from('sales_orders').update(updatePayload).eq('id', Number(orderId))
        : sb.from('sales_orders').update(updatePayload).eq('order_number', targetSo?.orderNumber || orderId);
      query.then(({ error }: any) => {
        if (error) console.error('Failed to update sales order approval in Supabase:', error);
      });
    }
  };

  const acceptDeliveryOrder = (
    orderId: string,
    acceptanceDetails?: { acceptedBy?: string; notes?: string; acceptanceNotes?: string }
  ) => {
    const targetSo = salesOrders.find((so) => so.id === orderId || so.orderNumber === orderId);
    const acceptedBy = acceptanceDetails?.acceptedBy || 'Engr. Abu Jubair Khan (Factory In-Charge)';
    const acceptedAt = new Date().toISOString();
    const notes = acceptanceDetails?.notes || acceptanceDetails?.acceptanceNotes || '';

    setSalesOrders((prev) =>
      prev.map((so) => {
        if (so.id === orderId || so.orderNumber === orderId) {
          return {
            ...so,
            doAccepted: true,
            doAcceptedBy: acceptedBy,
            doAcceptedAt: acceptedAt,
            doAcceptedNotes: notes,
            status: 'DO Accepted',
          };
        }
        return so;
      })
    );

    addAuditLog(
      'DO_ACCEPTED',
      'Factory Production & Dispatch',
      `Delivery Order #${targetSo?.doNumber || 'D.O.'} for order ${targetSo?.orderNumber || orderId} reviewed and accepted by factory (${acceptedBy}). Awaiting battery serial verification.`
    );

    const sb = getSupabase();
    if (sb) {
      const isNumeric = /^\d+$/.test(orderId);
      const query = isNumeric
        ? sb.from('sales_orders').update({ status: 'DO Accepted' }).eq('id', Number(orderId))
        : sb.from('sales_orders').update({ status: 'DO Accepted' }).eq('order_number', targetSo?.orderNumber || orderId);
      query.then(({ error }: any) => {
        if (error) console.error('Failed to update DO acceptance in Supabase:', error);
      });
    }
  };

  const generateChallanWithSerials = (
    orderId: string,
    updatedItems: SalesOrderItem[],
    details?: { updatedBy?: string; verifierName?: string; challanNumber?: string }
  ): string => {
    const targetSo = salesOrders.find((so) => so.id === orderId || so.orderNumber === orderId);
    const suffix = (targetSo?.orderNumber || orderId).replace(/\D/g, '').slice(-2) || '88';
    const autoChallan = details?.challanNumber || targetSo?.challanNumber || `BD-ES-2026-12-${suffix}`;
    const autoBill = targetSo?.billNumber || `20260012-${suffix}`;
    const updatedBy = details?.verifierName || details?.updatedBy || 'Engr. Abu Jubair Khan (Factory In-Charge)';

    setSalesOrders((prev) =>
      prev.map((so) => {
        if (so.id === orderId || so.orderNumber === orderId) {
          return {
            ...so,
            items: updatedItems,
            serialsUpdated: true,
            serialsUpdatedAt: new Date().toISOString(),
            serialsUpdatedBy: updatedBy,
            challanNumber: autoChallan,
            billNumber: so.billNumber || autoBill,
            challanGeneratedAt: new Date().toISOString(),
            status: 'Challan Generated',
          };
        }
        return so;
      })
    );

    addAuditLog(
      'CHALLAN_GENERATED',
      'Factory Dispatch',
      `Battery serial numbers verified for order ${targetSo?.orderNumber || orderId}. Official Factory Challan #${autoChallan} generated automatically. Ready for Dispatch & Invoice.`
    );

    const sb = getSupabase();
    if (sb) {
      const isNumeric = /^\d+$/.test(orderId);
      const query = isNumeric
        ? sb.from('sales_orders').update({
            status: 'Challan Generated',
            items_json: updatedItems,
          }).eq('id', Number(orderId))
        : sb.from('sales_orders').update({
            status: 'Challan Generated',
            items_json: updatedItems,
          }).eq('order_number', targetSo?.orderNumber || orderId);
      query.then(({ error }: any) => {
        if (error) console.error('Failed to update Challan generation in Supabase:', error);
      });
    }

    return autoChallan;
  };

  const dispatchAndInvoiceSalesOrder = (orderId: string) => {
    setSalesOrders((prev) =>
      prev.map((so) => {
        if (
          (so.id === orderId || so.orderNumber === orderId) &&
          so.status !== 'Invoiced' &&
          so.status !== 'Dispatched & Invoiced' &&
          so.status !== 'Delivered'
        ) {
          // 1. Deduct stock from selected warehouse
          const totalQty = so.items.reduce((sum, item) => sum + item.quantity, 0);
          setWarehouses((whs) =>
            whs.map((w) => {
              const isMatch =
                w.id === so.warehouseId ||
                (so.warehouseId && w.id.replace('wh-', '') === so.warehouseId.replace('wh-', '')) ||
                (w.name && so.warehouseName && w.name.toLowerCase() === so.warehouseName.toLowerCase()) ||
                whs.length === 1;
              return isMatch
                ? { ...w, currentStockUnits: Math.max(0, (w.currentStockUnits || 0) - totalQty) }
                : w;
            })
          );

          // 2. Post stock ledger entries
          so.items.forEach((item) => {
            const newLedger: StockLedgerEntry = {
              id: `sl-${Date.now()}-${item.productId}`,
              date: new Date().toISOString().substring(0, 10),
              warehouseId: so.warehouseId,
              warehouseName: so.warehouseName,
              productId: item.productId,
              productName: item.productName,
              batchNumber: item.batchNumber || 'BATCH-DISPATCH',
              transactionType: 'Sales Invoice',
              referenceNo: so.orderNumber,
              qtyIn: 0,
              qtyOut: item.quantity,
              balanceQty: 0,
              unitCostBDT: item.unitPriceBDT * 0.7,
              totalCostBDT: item.quantity * item.unitPriceBDT * 0.7,
            };
            setStockLedger((sl) => [newLedger, ...sl]);
          });

          // 3. Update customer / distributor receivables
          if (so.channel === 'Distributor Sales' && so.distributorId) {
            setDistributors((dists) =>
              dists.map((d) => (d.id === so.distributorId ? { ...d, currentOutstandingBDT: d.currentOutstandingBDT + so.dueAmountBDT } : d))
            );
          } else {
            setCustomers((custs) =>
              custs.map((c) => (c.id === so.customerId ? { ...c, outstandingBalanceBDT: c.outstandingBalanceBDT + so.dueAmountBDT } : c))
            );
          }

          // 4. If paid upfront, record cash book entry
          if (so.paidAmountBDT > 0) {
            const lastCash = cashBook[cashBook.length - 1];
            const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
            const cashEntry: CashBookEntry = {
              id: `cb-${Date.now()}`,
              date: new Date().toISOString().substring(0, 10),
              voucherNo: `CB-REC-${Date.now().toString().slice(-4)}`,
              accountType: 'Head Office Cash',
              transactionCategory: so.channel === 'Distributor Sales' ? 'Distributor Payment' : 'Customer Payment',
              description: `Payment received against invoice ${so.orderNumber} (${so.customerName})`,
              reference: so.orderNumber,
              cashInBDT: so.paidAmountBDT,
              cashOutBDT: 0,
              runningBalanceBDT: prevBal + so.paidAmountBDT,
            };
            setCashBook((prev) => [...prev, cashEntry]);
          }

          const challanLabel = so.challanNumber || `BD-ES-2026-12-${so.orderNumber.slice(-2)}`;
          addAuditLog(
            'INVOICE_POSTED',
            'Factory & Commercial',
            `Factory dispatched & invoiced order ${so.orderNumber} with Challan #${challanLabel}. Inventory deducted by ${totalQty} units. Awaiting Salesman customer delivery handover.`
          );

          const sb = getSupabase();
          if (sb) {
            const isNumeric = /^\d+$/.test(orderId);
            const query = isNumeric
              ? sb.from('sales_orders').update({ status: 'Dispatched & Invoiced' }).eq('id', Number(orderId))
              : sb.from('sales_orders').update({ status: 'Dispatched & Invoiced' }).eq('order_number', so.orderNumber || orderId);
            query.then(({ error }) => {
              if (error) console.error('Failed to sync invoice status to Supabase:', error);
            });
          }

          return {
            ...so,
            status: 'Dispatched & Invoiced',
            deliveryStatus: 'In Transit',
            challanNumber: so.challanNumber || challanLabel,
          };
        }
        return so;
      })
    );
  };

  const confirmCustomerReceipt = (
    orderId: string,
    details: {
      receiverName: string;
      receiverPhone: string;
      receivedDate: string;
      receiverDesignation?: string;
      handoverNotes: string;
      deliveryStatus: 'Full' | 'Partial';
      signatureConfirmed: boolean;
      salespersonName: string;
    }
  ) => {
    setSalesOrders((prev) =>
      prev.map((so) => {
        if (so.id === orderId || so.orderNumber === orderId) {
          const updated: SalesOrder = {
            ...so,
            status: 'Delivered',
            receivedByCustomer: true,
            customerReceivedAt: details.receivedDate,
            customerReceiverName: details.receiverName,
            customerReceiverPhone: details.receiverPhone,
            customerReceiverNotes: details.handoverNotes,
            customerReceiptSignature: details.signatureConfirmed
              ? 'Customer Seal & Signature Verified on Physical Challan'
              : 'Verbal / Digital Acknowledged',
            deliveryStatus: 'Received by Customer',
            deliveryHandoverBy: details.salespersonName || so.salespersonName,
          };
          return updated;
        }
        return so;
      })
    );

    addAuditLog(
      'ORDER_DELIVERED',
      'Field Force & Sales',
      `Salesman (${details.salespersonName}) confirmed customer receipt for Order ${orderId}. Received by ${details.receiverName} (${details.receiverPhone}). Status: Delivered.`
    );

    const sb = getSupabase();
    if (sb) {
      const isNumeric = /^\d+$/.test(orderId);
      const query = isNumeric
        ? sb.from('sales_orders').update({ status: 'Delivered' }).eq('id', Number(orderId))
        : sb.from('sales_orders').update({ status: 'Delivered' }).eq('order_number', orderId);
      query.then(({ error }) => {
        if (error) console.error('Failed to sync delivery confirmation to Supabase:', error);
      });
    }
  };

  const recordOrderPayment = (
    orderId: string,
    paidAmount: number,
    accountType: CashBookEntry['accountType'],
    reference: string
  ) => {
    let updatedPaid = 0;
    let updatedDue = 0;
    let targetOrderNumber = '';

    setSalesOrders((prev) =>
      prev.map((so) => {
        if (so.id === orderId) {
          updatedPaid = so.paidAmountBDT + paidAmount;
          updatedDue = Math.max(0, so.netAmountBDT - updatedPaid);
          targetOrderNumber = so.orderNumber;

          // Update distributor / customer outstanding
          if (so.channel === 'Distributor Sales' && so.distributorId) {
            setDistributors((dists) =>
              dists.map((d) => (d.id === so.distributorId ? { ...d, currentOutstandingBDT: Math.max(0, d.currentOutstandingBDT - paidAmount) } : d))
            );
          } else {
            setCustomers((custs) =>
              custs.map((c) => (c.id === so.customerId ? { ...c, outstandingBalanceBDT: Math.max(0, c.outstandingBalanceBDT - paidAmount) } : c))
            );
          }

          // Post to Cash Book
          const lastCash = cashBook[cashBook.length - 1];
          const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
          const cashEntry: CashBookEntry = {
            id: `cb-${Date.now()}`,
            date: new Date().toISOString().substring(0, 10),
            voucherNo: `CB-RCT-${Date.now().toString().slice(-4)}`,
            accountType,
            transactionCategory: so.channel === 'Distributor Sales' ? 'Distributor Payment' : 'Customer Payment',
            description: `Collection against ${so.orderNumber} (${so.customerName}) - Ref: ${reference}`,
            reference,
            cashInBDT: paidAmount,
            cashOutBDT: 0,
            runningBalanceBDT: prevBal + paidAmount,
          };
          setCashBook((cb) => [...cb, cashEntry]);

          addAuditLog('PAYMENT_COLLECTED', 'Finance & Cash Book', `Collected BDT ${paidAmount.toLocaleString()} against order ${so.orderNumber} via ${accountType}`);

          const sb = getSupabase();
          if (sb) {
            const isNumeric = /^\d+$/.test(orderId);
            const query = isNumeric
              ? sb.from('sales_orders').update({ paid_amount_bdt: updatedPaid, due_amount_bdt: updatedDue }).eq('id', Number(orderId))
              : sb.from('sales_orders').update({ paid_amount_bdt: updatedPaid, due_amount_bdt: updatedDue }).eq('order_number', targetOrderNumber || orderId);
            query.then(({ error }) => {
              if (error) console.error('Failed to sync payment to Supabase:', error);
            });
          }

          return { ...so, paidAmountBDT: updatedPaid, dueAmountBDT: updatedDue };
        }
        return so;
      })
    );
  };

  // Requisitions & Factory Indent Workflow
  const addRequisition = (reqData: Omit<Requisition, 'id' | 'requisitionNo' | 'createdAt'>): string => {
    const id = `req-${Date.now().toString().slice(-4)}`;
    const randomSuffix = Math.floor(100000 + Math.random() * 900000);
    const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
    const codePrefix = reqData.distributorName ? 'REQ-DB' : 'REQ-CUST';
    const requisitionNo = `${codePrefix}${Math.floor(100 + Math.random() * 900)}-${dateStr}${randomSuffix}`;
    const newReq: Requisition = {
      ...reqData,
      id,
      requisitionNo,
      createdAt: new Date().toISOString(),
    };
    setRequisitions((prev) => [newReq, ...prev]);
    addAuditLog(
      'REQUISITION_CREATED',
      'Requisition & Indent',
      `Field force created requisition ${newReq.requisitionNo} for ${newReq.distributorName || newReq.customerName} (Net: BDT ${newReq.netTotal.toLocaleString()})`
    );
    return id;
  };

  const updateRequisition = (reqId: string, updates: Partial<Requisition>) => {
    setRequisitions((prev) =>
      prev.map((r) => (r.id === reqId || r.requisitionNo === reqId ? { ...r, ...updates } : r))
    );
    addAuditLog('REQUISITION_UPDATED', 'Requisition & Indent', `Updated requisition ${reqId}`);
  };

  const deleteRequisition = (reqId: string) => {
    const target = requisitions.find((r) => r.id === reqId || r.requisitionNo === reqId);
    setRequisitions((prev) => prev.filter((r) => r.id !== reqId && r.requisitionNo !== reqId));
    addAuditLog('REQUISITION_DELETED', 'Requisition & Indent', `Deleted requisition ${target?.requisitionNo || reqId}`);
  };

  const approveRequisitionByFactory = (reqId: string, factoryNotes?: string, adjustedItems?: RequisitionItem[]) => {
    setRequisitions((prev) =>
      prev.map((r) => {
        if (r.id === reqId || r.requisitionNo === reqId) {
          const items = adjustedItems || r.items;
          const subtotal = items.reduce((sum, item) => sum + (item.approvedPcs ?? item.requestedPcs) * item.price, 0);
          const netTotal = subtotal;
          return {
            ...r,
            status: 'Approved',
            items,
            subtotal,
            netTotal,
            factoryNotes: factoryNotes || r.factoryNotes || 'Approved by Kushtia Plant Planning Operations',
            factoryReviewedBy: currentUser.name || 'Factory Head',
            factoryReviewedAt: new Date().toISOString().replace('T', ' ').slice(0, 16),
          };
        }
        return r;
      })
    );
    addAuditLog('REQUISITION_APPROVED', 'Manufacturing Plant', `Factory approved indent requisition ${reqId}`);
  };

  const rejectRequisitionByFactory = (reqId: string, reason?: string) => {
    setRequisitions((prev) =>
      prev.map((r) => {
        if (r.id === reqId || r.requisitionNo === reqId) {
          return {
            ...r,
            status: 'Rejected',
            factoryNotes: reason || 'Rejected by Factory due to stock/capacity limitations',
            factoryReviewedBy: currentUser.name || 'Factory Head',
            factoryReviewedAt: new Date().toISOString().replace('T', ' ').slice(0, 16),
          };
        }
        return r;
      })
    );
    addAuditLog('REQUISITION_REJECTED', 'Manufacturing Plant', `Factory rejected requisition ${reqId}`);
  };

  const issueRequisitionByAccounts = (reqId: string, challanNo?: string, issueNotes?: string) => {
    const generatedChallan = challanNo || `CH-KUS-${Date.now().toString().slice(-6)}`;
    setRequisitions((prev) =>
      prev.map((r) => {
        if (r.id === reqId || r.requisitionNo === reqId) {
          return {
            ...r,
            status: 'Issued',
            challanNo: generatedChallan,
            issueNotes: issueNotes || 'Issued and dispatched from central depot / Kushtia warehouse.',
            issuedBy: currentUser.name || 'Accounts & Dispatch Officer',
            issuedAt: new Date().toISOString().replace('T', ' ').slice(0, 16),
          };
        }
        return r;
      })
    );
    addAuditLog('REQUISITION_ISSUED', 'Finance & Dispatch', `Issued delivery challan ${generatedChallan} for requisition ${reqId}`);
  };

  const markRequisitionReceived = (reqId: string, receivedNotes?: string) => {
    setRequisitions((prev) =>
      prev.map((r) => {
        if (r.id === reqId || r.requisitionNo === reqId) {
          return {
            ...r,
            status: 'Received',
            receivedNotes: receivedNotes || 'Physical goods received in sound condition.',
            receivedBy: currentUser.name || 'Distributor / Customer Authorized Person',
            receivedAt: new Date().toISOString().replace('T', ' ').slice(0, 16),
          };
        }
        return r;
      })
    );
    addAuditLog('REQUISITION_RECEIVED', 'Logistics & Receiving', `Confirmed goods delivery receipt for requisition ${reqId}`);
  };

  // Payments Collection Master
  const addPayment = (
    paymentData: Omit<Payment, 'id' | 'tranNo' | 'creationDate' | 'createdAt' | 'approvedAmount' | 'status'>
  ): string => {
    const id = `pay-${Date.now().toString().slice(-6)}`;
    const tranNo = `TRN-${Date.now()}`;
    const now = new Date();
    const creationDate = now.toLocaleString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
    const newPayment: Payment = {
      ...paymentData,
      id,
      tranNo,
      creationDate,
      approvedAmount: 0,
      status: 'Created',
      createdAt: now.toISOString(),
    };
    setPayments((prev) => [newPayment, ...prev]);
    addAuditLog(
      'PAYMENT_CREATED',
      'Payments Collection',
      `Payment created ${tranNo} for ${newPayment.outAccountName} amount BDT ${newPayment.paymentAmount.toLocaleString()}`
    );
    return id;
  };

  const updatePayment = (paymentId: string, updates: Partial<Payment>) => {
    setPayments((prev) =>
      prev.map((p) => (p.id === paymentId || p.tranNo === paymentId ? { ...p, ...updates } : p))
    );
    addAuditLog('PAYMENT_UPDATED', 'Payments Collection', `Updated payment entry ${paymentId}`);
  };

  const approvePayment = (paymentId: string, approvedAmount?: number, approvedNotes?: string) => {
    let targetPayment: Payment | null = null;
    let finalAmount = 0;

    setPayments((prev) =>
      prev.map((p) => {
        if (p.id === paymentId || p.tranNo === paymentId) {
          finalAmount = approvedAmount !== undefined ? approvedAmount : p.paymentAmount;
          targetPayment = {
            ...p,
            status: 'Approved',
            approvedAmount: finalAmount,
            approvedBy: currentUser.name || 'Accounts Head',
            approvedDate: new Date().toISOString().replace('T', ' ').slice(0, 16),
            description: approvedNotes ? `${p.description || ''} | Note: ${approvedNotes}` : p.description,
          };
          return targetPayment;
        }
        return p;
      })
    );

    if (targetPayment) {
      const p: Payment = targetPayment;
      // 1. Update matching sales order / invoice if specified
      if (p.invoiceNo) {
        setSalesOrders((prev) =>
          prev.map((so) => {
            if (so.orderNumber === p.invoiceNo || (so as any).invoiceNo === p.invoiceNo || so.id === p.invoiceNo) {
              const newPaid = so.paidAmountBDT + finalAmount;
              const newDue = Math.max(0, so.netAmountBDT - newPaid);
              return {
                ...so,
                paidAmountBDT: newPaid,
                dueAmountBDT: newDue,
              };
            }
            return so;
          })
        );
      }

      // 2. Update distributor outstanding balance
      if (p.distributorId || p.outAccountName) {
        setDistributors((prev) =>
          prev.map((d) => {
            if (d.id === p.distributorId || d.name === p.outAccountName) {
              return {
                ...d,
                currentOutstandingBDT: Math.max(0, d.currentOutstandingBDT - finalAmount),
              };
            }
            return d;
          })
        );
      }

      // 3. Post Cash Book receipt voucher
      const voucherNo = `CB-PAY-${Date.now().toString().slice(-6)}`;
      const lastCash = cashBook[cashBook.length - 1];
      const prevBal = lastCash ? lastCash.runningBalanceBDT : 0;
      const newEntry: CashBookEntry = {
        id: `cb-${Date.now()}`,
        date: new Date().toISOString().slice(0, 10),
        voucherNo,
        accountType: (p.bankName as any) || 'Head Office Cash',
        transactionCategory: 'Distributor Payment',
        description: `Collection voucher ${p.tranNo} received against Invoice ${p.invoiceNo || 'On Account'} from ${p.outAccountName}`,
        reference: p.chequeNoReceiptNo || p.tranNo,
        cashInBDT: finalAmount,
        cashOutBDT: 0,
        runningBalanceBDT: prevBal + finalAmount,
      };
      setCashBook((prev) => [...prev, newEntry]);

      addAuditLog(
        'PAYMENT_APPROVED',
        'Payments Collection',
        `Approved payment ${p.tranNo} for ৳ ${finalAmount.toLocaleString()} from ${p.outAccountName} against Invoice ${p.invoiceNo || 'N/A'}`
      );
    }
  };

  const rejectPayment = (paymentId: string, reason?: string) => {
    setPayments((prev) =>
      prev.map((p) => {
        if (p.id === paymentId || p.tranNo === paymentId) {
          return {
            ...p,
            status: 'Rejected',
            rejectionReason: reason || 'Rejected by Accounts',
          };
        }
        return p;
      })
    );
    addAuditLog('PAYMENT_REJECTED', 'Payments Collection', `Rejected payment entry ${paymentId} (${reason || 'No reason provided'})`);
  };

  const deletePayment = (paymentId: string) => {
    const target = payments.find((p) => p.id === paymentId || p.tranNo === paymentId);
    setPayments((prev) => prev.filter((p) => p.id !== paymentId && p.tranNo !== paymentId));
    addAuditLog('PAYMENT_DELETED', 'Payments Collection', `Deleted payment record ${target?.tranNo || paymentId}`);
  };

  const clearPaymentsCache = () => {
    setPayments([]);
    if (typeof window !== 'undefined') {
      try {
        localStorage.removeItem('ensec_payments');
        sessionStorage.removeItem('ensec_payments');
        localStorage.removeItem('ensec_payments_sample');
        sessionStorage.removeItem('ensec_payments_sample');
      } catch (e) {}
    }
    addAuditLog('PAYMENTS_CLEARED', 'Payments Collection', 'Cleared payment records and local session memory.');
  };

  // Stage: TADA Management
  const addTADA = (entryData: Omit<TADAEntry, 'id' | 'createdAt' | 'lastModified'>): string => {
    const id = `tada-${Date.now().toString().slice(-6)}`;
    const now = new Date();
    const lastModified = now.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
    const newEntry: TADAEntry = {
      ...entryData,
      id,
      userId: entryData.userId || currentUser?.id,
      employeeId: entryData.employeeId || currentEmployeeProfile?.employeeId || entryData.repId,
      employeeCode: entryData.employeeCode || currentEmployeeProfile?.employeeCode || entryData.ffCode,
      lastModified,
      createdAt: now.toISOString(),
    };
    setTadaList((prev) => [newEntry, ...prev]);
    addAuditLog('TADA_CLAIM_SUBMITTED', 'TADA Management', `Submitted TADA claim for ${newEntry.ffName} amount BDT ${newEntry.amount}`);
    return id;
  };

  const updateTADA = (id: string, updates: Partial<TADAEntry>) => {
    const now = new Date();
    const lastModified = now.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
    setTadaList((prev) =>
      prev.map((t) => (t.id === id ? { ...t, ...updates, lastModified } : t))
    );
    addAuditLog('TADA_CLAIM_UPDATED', 'TADA Management', `Updated TADA claim ${id}`);
  };

  const approveTADA = (id: string, approverName?: string) => {
    const now = new Date();
    const approvedAt = now.toISOString().replace('T', ' ').slice(0, 16);
    const lastModified = now.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
    const finalApprover = approverName || currentUser.name || 'Management Approver';

    setTadaList((prev) =>
      prev.map((t) =>
        t.id === id
          ? {
              ...t,
              status: 'Approved',
              approverName: finalApprover,
              approvedAt,
              lastModified,
            }
          : t
      )
    );
    addAuditLog('TADA_APPROVED', 'TADA Management', `Approved TADA claim ${id} by ${finalApprover}`);
  };

  const batchApproveTADA = (ids: string[], approverName?: string) => {
    const now = new Date();
    const approvedAt = now.toISOString().replace('T', ' ').slice(0, 16);
    const lastModified = now.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
    const finalApprover = approverName || currentUser.name || 'Management Approver';

    setTadaList((prev) =>
      prev.map((t) =>
        ids.includes(t.id)
          ? {
              ...t,
              status: 'Approved',
              approverName: finalApprover,
              approvedAt,
              lastModified,
            }
          : t
      )
    );
    addAuditLog('TADA_BATCH_APPROVED', 'TADA Management', `Batch approved ${ids.length} TADA claims by ${finalApprover}`);
  };

  const rejectTADA = (id: string, reason?: string) => {
    const now = new Date();
    const lastModified = now.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
    setTadaList((prev) =>
      prev.map((t) =>
        t.id === id
          ? {
              ...t,
              status: 'Rejected',
              remarks: reason ? `${t.remarks || ''} (Rejected: ${reason})` : t.remarks,
              lastModified,
            }
          : t
      )
    );
    addAuditLog('TADA_REJECTED', 'TADA Management', `Rejected TADA claim ${id} (${reason || 'No reason provided'})`);
  };

  const deleteTADA = (id: string) => {
    setTadaList((prev) => prev.filter((t) => t.id !== id));
    addAuditLog('TADA_DELETED', 'TADA Management', `Deleted TADA claim ${id}`);
  };

  const updateFieldForceTADAApprover = (repId: string, approverId: string, approverName: string) => {
    setFieldForceReps((prev) =>
      prev.map((r) =>
        r.id === repId || r.code === repId
          ? { ...r, tadaApproverId: approverId, tadaApproverName: approverName }
          : r
      )
    );
    addAuditLog('TADA_APPROVER_TAGGED', 'Field Force Management', `Super Admin tagged ${approverName} as TADA Approver for ${repId}`);
  };

  // Stage 11: Finance & Cash Book
  const addCashBookEntry = (entry: Omit<CashBookEntry, 'id' | 'runningBalanceBDT'>) => {
    const lastCash = cashBook[cashBook.length - 1];
    const prevBal = lastCash ? lastCash.runningBalanceBDT : 0;
    const netDelta = entry.cashInBDT - entry.cashOutBDT;
    const newEntry: CashBookEntry = {
      ...entry,
      id: `cb-${Date.now()}`,
      runningBalanceBDT: prevBal + netDelta,
    };
    setCashBook((prev) => [...prev, newEntry]);
    addAuditLog('CASH_VOUCHER_POSTED', 'Finance & Cash Book', `Voucher ${newEntry.voucherNo} posted to ${newEntry.accountType} (In: ${newEntry.cashInBDT}, Out: ${newEntry.cashOutBDT})`);
  };

  // Stage 12: Payroll & Salary Automation
  const generateMonthlyPayroll = (monthYear: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to generate monthly payroll.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to generate monthly payroll (${monthYear}) without create_payroll permission`);
      return;
    }
    const newRecords: PayrollRecord[] = fieldForceReps.map((rep) => {
      const basic = rep.basicSalaryBDT;
      const houseRent = basic * 0.5;
      const medical = basic * 0.1;
      const conveyance = rep.conveyanceBDT;
      const mobile = rep.mobileAllowanceBDT;
      const tada = rep.taDaBDT;

      // Incentive tied to target achievement
      const achPercent = rep.monthlyTargetBDT > 0 ? (rep.monthlyAchievedBDT / rep.monthlyTargetBDT) * 100 : 0;
      let incentive = 0;
      if (achPercent >= 100) incentive = basic * 0.4;
      else if (achPercent >= 85) incentive = basic * 0.25;
      else if (achPercent >= 70) incentive = basic * 0.1;

      // Automated Tax deduction (progressive slab estimation)
      const gross = basic + houseRent + medical + conveyance + mobile + tada + incentive;
      let tax = 0;
      if (gross > 60000) tax = gross * 0.05;
      const pf = basic * 0.1;
      const net = gross - tax - pf;

      return {
        id: `pay-${monthYear}-${rep.id}`,
        monthYear,
        employeeId: rep.id,
        employeeName: rep.name,
        designation: rep.designation,
        basicSalaryBDT: basic,
        houseRentBDT: houseRent,
        medicalAllowanceBDT: medical,
        conveyanceAllowanceBDT: conveyance,
        mobileAllowanceBDT: mobile,
        taDaBDT: tada,
        targetBDT: rep.monthlyTargetBDT,
        achievementBDT: rep.monthlyAchievedBDT,
        achievementPercent: Number(achPercent.toFixed(1)),
        salesIncentiveBDT: Math.round(incentive),
        taxDeductionBDT: Math.round(tax),
        providentFundBDT: Math.round(pf),
        netPayableBDT: Math.round(net),
        status: 'Draft',
      };
    });

    setPayrollRecords((prev) => {
      const filtered = prev.filter((p) => p.monthYear !== monthYear);
      return [...newRecords, ...filtered];
    });

    addAuditLog('PAYROLL_GENERATED', 'HR & Payroll', `Generated automated payroll calculations for ${monthYear} (${newRecords.length} staff)`);
  };

  const disbursePayroll = (payrollId: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'disburse')) {
      console.warn('Permission denied: disburse required to disburse salary payments.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to disburse payroll (${payrollId}) without disburse permission`);
      return;
    }
    setPayrollRecords((prev) =>
      prev.map((p) => {
        if (p.id === payrollId && p.status !== 'Paid') {
          // Deduct from City Bank PLC in Cash Book
          const lastCash = cashBook[cashBook.length - 1];
          const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
          const cashEntry: CashBookEntry = {
            id: `cb-${Date.now()}`,
            date: new Date().toISOString().substring(0, 10),
            voucherNo: `CB-SAL-${Date.now().toString().slice(-4)}`,
            accountType: 'City Bank PLC',
            transactionCategory: 'Salary Payment',
            description: `Salary & Incentive disbursement to ${p.employeeName} (${p.designation}) for ${p.monthYear}`,
            reference: `PAY-${p.monthYear}-${p.employeeId}`,
            cashInBDT: 0,
            cashOutBDT: p.netPayableBDT,
            runningBalanceBDT: prevBal - p.netPayableBDT,
          };
          setCashBook((cb) => [...cb, cashEntry]);
          addAuditLog('PAYROLL_DISBURSED', 'HR & Payroll', `Disbursed net salary BDT ${p.netPayableBDT.toLocaleString()} to ${p.employeeName}`);
          return { ...p, status: 'Paid', paymentDate: new Date().toISOString().substring(0, 10) };
        }
        return p;
      })
    );
  };

  // User Management & Permissions (RBAC)
  const addUser = (userData: Omit<User, 'id'>): string => {
    const id = `u-${Date.now().toString().slice(-5)}`;
    const permissions = userData.permissions || getDefaultPermissionsForRole(userData.role);
    const newUser: User = {
      ...userData,
      id,
      permissions,
      status: userData.status || 'Active',
    };
    setUsers((prev) => [...prev, newUser]);

    // If salesman, automatically add to fieldForceReps if not already there
    if (newUser.isSalesman || newUser.role === 'Field Force' || newUser.role === 'Territory Sales Officer') {
      const code = newUser.salesmanCode || `REP-${Math.floor(100 + Math.random() * 900)}`;
      const repExists = fieldForceReps.some((r) => r.id === id || r.name.toLowerCase() === newUser.name.toLowerCase());
      if (!repExists) {
        const newRep: FieldForceRep = {
          id,
          userId: id,
          code,
          name: newUser.name,
          phone: newUser.phone,
          email: newUser.email,
          department: newUser.department,
          designation: newUser.designation,
          region: newUser.region || 'Dhaka Division',
          area: newUser.area || 'Dhaka North',
          territory: newUser.territory || 'Assigned Territory',
          monthlyTargetBDT: newUser.monthlySalesTargetBDT || 2000000,
          monthlyAchievedBDT: 0,
          currentLocation: {
            latitude: 23.7925 + (Math.random() - 0.5) * 0.05,
            longitude: 90.4078 + (Math.random() - 0.5) * 0.05,
            address: `${newUser.territory || 'Dhaka'} Market Territory`,
            lastUpdated: 'Just now',
            speedKmH: 0,
            batteryLevel: 95,
            isOnline: true,
          },
          todayVisitsCount: 0,
          productiveVisitsCount: 0,
          basicSalaryBDT: 28000,
          conveyanceBDT: 5000,
          taDaBDT: 6500,
          mobileAllowanceBDT: 2500,
        };
        setFieldForceReps((prev) => [...prev, newRep]);
      }
    }

    addAuditLog('USER_CREATED', 'User Management', `Created new user ${newUser.name} with role ${newUser.role}`);

    // Sync newly created user to Supabase if configured
    const sb = getSupabase();
    if (sb) {
      const geoSnapshot = {
        assignedOfficeId: newUser.assignedOfficeId || null,
        assignedOfficeName: newUser.assignedOfficeName || null,
        officeLatitude: newUser.officeLatitude ?? null,
        officeLongitude: newUser.officeLongitude ?? null,
        allowedRadiusMeters: newUser.allowedRadiusMeters ?? null,
        officeAddress: newUser.officeAddress || null,
        locationStatus: newUser.locationStatus || 'Active',
        shiftStartTime: newUser.shiftStartTime || null,
        shiftEndTime: newUser.shiftEndTime || null,
        gracePeriodMinutes: newUser.gracePeriodMinutes ?? null,
      };
      const geofenceDedicatedCols = new Set([
        'assigned_office_id',
        'assigned_office_name',
        'office_latitude',
        'office_longitude',
        'allowed_radius_meters',
        'office_address',
        'location_status',
        'shift_start_time',
        'shift_end_time',
        'grace_period_minutes',
      ]);
      const userPayload: any = {
        name: newUser.name,
        email: newUser.email,
        password: newUser.password || 'ensec2026',
        phone: newUser.phone || null,
        role: newUser.role,
        designation: newUser.designation || null,
        department: newUser.department || 'Operations',
        region: newUser.region || null,
        area: newUser.area || null,
        territory: newUser.territory || null,
        status: newUser.status || 'Active',
        uid: newUser.userId || id,
        user_id: newUser.userId || id,
        is_salesman: Boolean(newUser.isSalesman),
        salesman_code: newUser.salesmanCode || null,
        monthly_sales_target_bdt: newUser.monthlySalesTargetBDT ?? null,
        assigned_office_id: geoSnapshot.assignedOfficeId,
        assigned_office_name: geoSnapshot.assignedOfficeName,
        office_latitude: geoSnapshot.officeLatitude,
        office_longitude: geoSnapshot.officeLongitude,
        allowed_radius_meters: geoSnapshot.allowedRadiusMeters,
        office_address: geoSnapshot.officeAddress,
        location_status: geoSnapshot.locationStatus,
        shift_start_time: geoSnapshot.shiftStartTime,
        shift_end_time: geoSnapshot.shiftEndTime,
        grace_period_minutes: geoSnapshot.gracePeriodMinutes,
        permissions: newUser.permissions || {},
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };
      (async () => {
        try {
          for (let attempt = 0; attempt < 20; attempt++) {
            const { error: insErr } = await sb
              .from('users')
              .upsert(userPayload, { onConflict: 'email' });
            if (!insErr) break;
            const colMatch =
              insErr.message.match(/column ["']?([a-zA-Z0-9_]+)["']? of relation ["']?users["']? does not exist/i) ||
              insErr.message.match(/Could not find the ['"]?([a-zA-Z0-9_]+)['"]? column/i);
            if (colMatch && colMatch[1] && colMatch[1] !== 'email') {
              if (geofenceDedicatedCols.has(colMatch[1])) {
                userPayload.permissions = {
                  ...(typeof userPayload.permissions === 'object' && userPayload.permissions ? userPayload.permissions : {}),
                  geofence: geoSnapshot,
                };
              }
              delete userPayload[colMatch[1]];
              continue;
            }
            break;
          }
        } catch (e) {
          console.warn('Supabase addUser sync notice:', e);
        }
      })();
    }

    return id;
  };

  const updateUser = (userId: string, updates: Partial<User>) => {
    const target = users.find((u) => u.id === userId);
    const mergedTarget: User | undefined = target ? { ...target, ...updates } : undefined;
    setUsers((prev) =>
      prev.map((u) => {
        if (u.id === userId) {
          const updated = { ...u, ...updates };
          if (currentUser.id === userId) {
            const safeSessionUser = { ...updated, password: '' };
            setCurrentUser(safeSessionUser);
            if (typeof window !== 'undefined') {
              localStorage.setItem('ensec_erp_session_user', JSON.stringify(safeSessionUser));
              localStorage.setItem('ensec_erp_user', JSON.stringify(safeSessionUser));
            }
          }
          return updated;
        }
        return u;
      })
    );
    addAuditLog('USER_UPDATED', 'User Management', `Updated profile details for user ID ${userId}`);

    // Sync profile updates to Supabase if configured
    const sb = getSupabase();
    if (sb) {
      const email = target?.email || (updates as any).email;
      const uid = target?.userId || target?.id || userId;
      if (email || uid) {
        const geoSnapshot = {
          assignedOfficeId: mergedTarget?.assignedOfficeId ?? updates.assignedOfficeId ?? null,
          assignedOfficeName: mergedTarget?.assignedOfficeName ?? updates.assignedOfficeName ?? null,
          officeLatitude: mergedTarget?.officeLatitude ?? updates.officeLatitude ?? null,
          officeLongitude: mergedTarget?.officeLongitude ?? updates.officeLongitude ?? null,
          allowedRadiusMeters: mergedTarget?.allowedRadiusMeters ?? updates.allowedRadiusMeters ?? null,
          officeAddress: mergedTarget?.officeAddress ?? updates.officeAddress ?? null,
          locationStatus: mergedTarget?.locationStatus ?? updates.locationStatus ?? 'Active',
          shiftStartTime: mergedTarget?.shiftStartTime ?? updates.shiftStartTime ?? null,
          shiftEndTime: mergedTarget?.shiftEndTime ?? updates.shiftEndTime ?? null,
          gracePeriodMinutes: mergedTarget?.gracePeriodMinutes ?? updates.gracePeriodMinutes ?? null,
        };
        const geofenceDedicatedCols = new Set([
          'assigned_office_id',
          'assigned_office_name',
          'office_latitude',
          'office_longitude',
          'allowed_radius_meters',
          'office_address',
          'location_status',
          'shift_start_time',
          'shift_end_time',
          'grace_period_minutes',
        ]);
        const hasGeoUpdate =
          updates.assignedOfficeId !== undefined ||
          updates.assignedOfficeName !== undefined ||
          updates.officeLatitude !== undefined ||
          updates.officeLongitude !== undefined ||
          updates.allowedRadiusMeters !== undefined ||
          updates.officeAddress !== undefined ||
          updates.locationStatus !== undefined ||
          updates.shiftStartTime !== undefined ||
          updates.shiftEndTime !== undefined ||
          updates.gracePeriodMinutes !== undefined;

        const supaUpdates: any = {
          updated_at: new Date().toISOString(),
        };
        if (updates.name) supaUpdates.name = updates.name;
        if (updates.email) supaUpdates.email = updates.email;
        if (updates.userId !== undefined) supaUpdates.user_id = updates.userId;
        if (updates.phone !== undefined) supaUpdates.phone = updates.phone;
        if (updates.role) supaUpdates.role = updates.role;
        if (updates.designation !== undefined) supaUpdates.designation = updates.designation;
        if (updates.department !== undefined) supaUpdates.department = updates.department;
        if (updates.region !== undefined) supaUpdates.region = updates.region;
        if (updates.area !== undefined) supaUpdates.area = updates.area;
        if (updates.territory !== undefined) supaUpdates.territory = updates.territory;
        if (updates.status) supaUpdates.status = updates.status;
        if (updates.isSalesman !== undefined) supaUpdates.is_salesman = updates.isSalesman;
        if (updates.salesmanCode !== undefined) supaUpdates.salesman_code = updates.salesmanCode;
        if (updates.monthlySalesTargetBDT !== undefined) supaUpdates.monthly_sales_target_bdt = updates.monthlySalesTargetBDT;
        if (updates.permissions) supaUpdates.permissions = updates.permissions;
        if (updates.password) supaUpdates.password = updates.password;
        if (updates.assignedOfficeId !== undefined) supaUpdates.assigned_office_id = updates.assignedOfficeId || null;
        if (updates.assignedOfficeName !== undefined) supaUpdates.assigned_office_name = updates.assignedOfficeName || null;
        if (updates.officeLatitude !== undefined) supaUpdates.office_latitude = updates.officeLatitude ?? null;
        if (updates.officeLongitude !== undefined) supaUpdates.office_longitude = updates.officeLongitude ?? null;
        if (updates.allowedRadiusMeters !== undefined) supaUpdates.allowed_radius_meters = updates.allowedRadiusMeters ?? null;
        if (updates.officeAddress !== undefined) supaUpdates.office_address = updates.officeAddress || null;
        if (updates.locationStatus !== undefined) supaUpdates.location_status = updates.locationStatus || 'Active';
        if (updates.shiftStartTime !== undefined) supaUpdates.shift_start_time = updates.shiftStartTime || null;
        if (updates.shiftEndTime !== undefined) supaUpdates.shift_end_time = updates.shiftEndTime || null;
        if (updates.gracePeriodMinutes !== undefined) supaUpdates.grace_period_minutes = updates.gracePeriodMinutes ?? null;

        (async () => {
          try {
            const matchEmail = target?.email || email;
            for (let attempt = 0; attempt < 20; attempt++) {
              const query = matchEmail
                ? sb.from('users').update(supaUpdates).ilike('email', matchEmail)
                : sb.from('users').update(supaUpdates).eq('uid', uid);
              const { error: updErr } = await query;
              if (!updErr) break;
              const colMatch =
                updErr.message.match(/column ["']?([a-zA-Z0-9_]+)["']? of relation ["']?users["']? does not exist/i) ||
                updErr.message.match(/Could not find the ['"]?([a-zA-Z0-9_]+)['"]? column/i);
              if (colMatch && colMatch[1]) {
                if (hasGeoUpdate && geofenceDedicatedCols.has(colMatch[1])) {
                  const basePerms =
                    supaUpdates.permissions ||
                    mergedTarget?.permissions ||
                    target?.permissions ||
                    {};
                  supaUpdates.permissions = {
                    ...(typeof basePerms === 'object' && basePerms ? basePerms : {}),
                    geofence: geoSnapshot,
                  };
                }
                delete supaUpdates[colMatch[1]];
                continue;
              }
              break;
            }
          } catch (e) {
            console.warn('Supabase updateUser sync notice:', e);
          }
        })();
      }
    }
  };

  const updateUserPassword = async (
    userId: string,
    newPassword: string
  ): Promise<{ success: boolean; error?: string; sqlFix?: string; warning?: string }> => {
    const cleanPassword = newPassword?.trim();
    if (!cleanPassword || cleanPassword.length < 4) {
      return { success: false, error: 'Password must be at least 4 characters long.' };
    }

    // 1. Locate the target user synchronously
    const targetUser = users.find(
      (u) =>
        u.id === userId ||
        u.userId === userId ||
        (u.email && u.email.toLowerCase() === userId.toLowerCase())
    );

    const userName = targetUser?.name || userId;
    const userEmail = targetUser?.email?.trim().toLowerCase();

    // 2. Update local state immediately
    setUsers((prev) =>
      prev.map((u) => {
        if (
          u.id === userId ||
          u.userId === userId ||
          (userEmail && u.email?.toLowerCase() === userEmail)
        ) {
          const updated = { ...u, password: cleanPassword };
          if (currentUser.id === u.id || (userEmail && currentUser.email?.toLowerCase() === userEmail)) {
            setCurrentUser(updated);
          }
          return updated;
        }
        return u;
      })
    );

    addAuditLog(
      'PASSWORD_CHANGED',
      'Security & Access Control',
      `Password successfully changed for user ${userName} (${targetUser?.userId || userEmail || userId})`
    );

    // 3. Supabase Database Persistence
    const sb = getSupabase();
    if (!sb) {
      return {
        success: true,
        warning: 'Supabase credentials are not configured. Saved in local storage.',
      };
    }

    try {
      // Step A: Locate existing row in public.users table by email or uid
      let existingSbUser: any = null;
      if (userEmail) {
        const { data: foundByEmail, error: findEmailErr } = await sb
          .from('users')
          .select('id, email, name')
          .ilike('email', userEmail)
          .limit(1);

        if (findEmailErr) {
          const findMsg = (findEmailErr.message || '').toLowerCase();
          if (findEmailErr.code === '42P01' || findMsg.includes('does not exist') || findMsg.includes('relation')) {
            return {
              success: false,
              error: 'Table "users" does not exist in your Supabase project. Please execute the SQL schema in Supabase SQL Editor.',
              sqlFix: 'CREATE TABLE IF NOT EXISTS public.users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT DEFAULT \'ensec2026\', role TEXT DEFAULT \'Field Force\', status TEXT DEFAULT \'Active\');',
            };
          }
          if (findEmailErr.code === '42501' || findMsg.includes('policy') || findMsg.includes('security')) {
            return {
              success: false,
              error: `Supabase RLS is blocking access to table "users" (${findEmailErr.message}). Run: CREATE POLICY "Allow public access" ON public.users FOR ALL USING (true) WITH CHECK (true);`,
              sqlFix: 'CREATE POLICY "Allow public access" ON public.users FOR ALL USING (true) WITH CHECK (true);',
            };
          }
        } else if (foundByEmail && foundByEmail.length > 0) {
          existingSbUser = foundByEmail[0];
        }
      }

      if (!existingSbUser && (targetUser?.userId || targetUser?.id)) {
        const { data: foundByUid } = await sb
          .from('users')
          .select('id, email, name')
          .eq('uid', targetUser?.userId || targetUser?.id)
          .limit(1);
        if (foundByUid && foundByUid.length > 0) {
          existingSbUser = foundByUid[0];
        }
      }

      // Step B: If row already exists in public.users, UPDATE it
      if (existingSbUser) {
        let updatePayload: any = {
          password: cleanPassword,
          updated_at: new Date().toISOString(),
        };

        let updateSuccess = false;
        let lastUpdateErr: any = null;

        for (let attempt = 0; attempt < 5; attempt++) {
          const query = existingSbUser.id
            ? sb.from('users').update(updatePayload).eq('id', existingSbUser.id)
            : sb.from('users').update(updatePayload).ilike('email', userEmail!);

          const { data: updData, error: updErr } = await query.select();

          if (!updErr) {
            updateSuccess = true;
            break;
          }

          lastUpdateErr = updErr;
          const errMsg = (updErr.message || '').toLowerCase();

          // Column password missing
          if (updErr.code === '42703' && errMsg.includes('password')) {
            return {
              success: false,
              error: `Supabase table "users" is missing the "password" column. Please run this in your Supabase SQL Editor: ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password TEXT DEFAULT 'ensec2026';`,
              sqlFix: 'ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password TEXT DEFAULT \'ensec2026\';',
            };
          }

          // Strip updated_at if not present
          if (updErr.code === '42703' && errMsg.includes('updated_at')) {
            delete updatePayload.updated_at;
            continue;
          }

          // RLS error
          if (updErr.code === '42501' || errMsg.includes('policy')) {
            return {
              success: false,
              error: `Supabase RLS is blocking updates to table "users" (${updErr.message}). Add a permissive RLS policy.`,
              sqlFix: 'CREATE POLICY "Allow public access" ON public.users FOR ALL USING (true) WITH CHECK (true);',
            };
          }

          break;
        }

        if (!updateSuccess && lastUpdateErr) {
          return {
            success: false,
            error: `Failed to update password in Supabase: ${lastUpdateErr.message}`,
          };
        }

        await refreshUsers();
        return { success: true };
      }

      // Step C: If user row does NOT exist yet in public.users, INSERT / UPSERT them with password!
      const insertPayload: any = {
        name: targetUser?.name || userName || 'Ensec Staff',
        email: userEmail || `${(targetUser?.userId || userId).toLowerCase()}@ensecbd.com`,
        password: cleanPassword,
        phone: targetUser?.phone || null,
        role: targetUser?.role || 'Field Force',
        designation: targetUser?.designation || null,
        department: targetUser?.department || 'Operations',
        status: targetUser?.status || 'Active',
        uid: targetUser?.userId || targetUser?.id || userId,
        permissions: targetUser?.permissions || {},
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      let insertSuccess = false;
      let lastInsertErr: any = null;

      for (let attempt = 0; attempt < 8; attempt++) {
        const { data: insData, error: insErr } = await sb
          .from('users')
          .upsert(insertPayload, { onConflict: 'email' })
          .select();

        if (!insErr) {
          insertSuccess = true;
          break;
        }

        lastInsertErr = insErr;
        const msg = (insErr.message || '').toLowerCase();

        // If password column missing:
        if (insErr.code === '42703' && msg.includes('password')) {
          return {
            success: false,
            error: `Supabase table "users" is missing the "password" column. Please run this in your Supabase SQL Editor: ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password TEXT DEFAULT 'ensec2026';`,
            sqlFix: 'ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password TEXT DEFAULT \'ensec2026\';',
          };
        }

        // If other optional column missing, strip and retry
        const colMatch =
          insErr.message.match(/column ["']?([a-zA-Z0-9_]+)["']? of relation ["']?users["']? does not exist/i) ||
          insErr.message.match(/Could not find the ['"]?([a-zA-Z0-9_]+)['"]? column/i);
        if (colMatch && colMatch[1] && colMatch[1] !== 'password' && colMatch[1] !== 'email') {
          delete insertPayload[colMatch[1]];
          continue;
        }

        // RLS error
        if (insErr.code === '42501' || msg.includes('policy')) {
          return {
            success: false,
            error: `Supabase RLS is blocking inserts to table "users" (${insErr.message}). Add a permissive RLS policy.`,
            sqlFix: 'CREATE POLICY "Allow public access" ON public.users FOR ALL USING (true) WITH CHECK (true);',
          };
        }

        break;
      }

      if (!insertSuccess && lastInsertErr) {
        return {
          success: false,
          error: `Supabase failed to save user into users table: ${lastInsertErr.message}`,
        };
      }

      await refreshUsers();
      return { success: true };
    } catch (err: any) {
      console.error('Exception updating user password in Supabase:', err);
      return {
        success: false,
        error: err.message || 'Unexpected exception updating password in Supabase.',
      };
    }
  };

  const syncAllUsersToSupabase = async (): Promise<{ success: boolean; count: number; error?: string; sqlFix?: string }> => {
    const sb = getSupabase();
    if (!sb) {
      return { success: false, count: 0, error: 'Supabase credentials are not connected.' };
    }
    let successCount = 0;
    for (const u of users) {
      const res = await updateUserPassword(u.id, u.password || 'ensec2026');
      if (res.success) {
        successCount++;
      } else if (res.sqlFix) {
        return { success: false, count: successCount, error: res.error, sqlFix: res.sqlFix };
      }
    }
    await refreshUsers();
    return { success: true, count: successCount };
  };

  const updateUserPermissions = async (
    userId: string,
    permissions: UserPermissions
  ): Promise<{ success: boolean; isRemoteSynced: boolean; message?: string; error?: string }> => {
    const targetUser = users.find(
      (u) =>
        u.id === userId ||
        u.userId === userId ||
        (u.email && u.email.toLowerCase() === userId.toLowerCase())
    );

    let updatedUserObj: User | null = null;
    const updatedUsers = users.map((u) => {
      const isMatch =
        u.id === userId ||
        u.userId === userId ||
        (targetUser?.email && u.email && u.email.toLowerCase() === targetUser.email.toLowerCase()) ||
        (targetUser?.id && u.id === targetUser.id);

      if (isMatch) {
        const updated = { ...u, permissions };
        updatedUserObj = updated;
        if (currentUser.id === u.id || (targetUser?.email && currentUser.email?.toLowerCase() === targetUser.email.toLowerCase())) {
          const safeSessionUser = { ...updated, password: '' };
          setCurrentUser(safeSessionUser);
          if (typeof window !== 'undefined') {
            localStorage.setItem('ensec_erp_session_user', JSON.stringify(safeSessionUser));
            localStorage.setItem('ensec_erp_user', JSON.stringify(safeSessionUser));
          }
        }
        return updated;
      }
      return u;
    });

    setUsers(updatedUsers);
    if (typeof window !== 'undefined') {
      localStorage.setItem('ensec_erp_users', JSON.stringify(updatedUsers));
      fetch('/api/manufacturing/sync-state', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          users: updatedUsers.map((u) => ({
            id: u.id,
            userId: u.userId,
            name: u.name,
            email: u.email,
            role: u.role,
            department: u.department,
            status: u.status,
            permissions: u.permissions,
          })),
        }),
      }).catch(() => {});
    }

    addAuditLog(
      'PERMISSIONS_UPDATED',
      'User Management',
      `Super Admin updated page and feature permissions for ${targetUser?.name || updatedUserObj?.name || userId}`
    );

    let isRemoteSynced = false;
    let syncError: string | undefined;

    const sb = getSupabase();
    if (sb) {
      try {
        const email = targetUser?.email || updatedUserObj?.email;
        const uid = targetUser?.userId || updatedUserObj?.userId || targetUser?.id || updatedUserObj?.id || userId;

        // Locate existing user in Supabase by email, uid, or id
        let existingSbUser: any = null;
        if (email) {
          const { data: foundByEmail } = await sb
            .from('users')
            .select('id, email, uid, permissions')
            .ilike('email', email)
            .limit(1);
          if (foundByEmail && foundByEmail.length > 0) {
            existingSbUser = foundByEmail[0];
          }
        }
        if (!existingSbUser && uid) {
          const { data: foundByUid } = await sb
            .from('users')
            .select('id, email, uid, permissions')
            .eq('uid', uid)
            .limit(1);
          if (foundByUid && foundByUid.length > 0) {
            existingSbUser = foundByUid[0];
          }
        }
        if (!existingSbUser) {
          const rawId = String(targetUser?.id || updatedUserObj?.id || userId || '');
          const sbIdMatch = rawId.match(/^u-sb-(\d+)$/) || rawId.match(/^(\d+)$/);
          if (sbIdMatch?.[1]) {
            const { data: foundById } = await sb
              .from('users')
              .select('id, email, uid, permissions')
              .eq('id', Number(sbIdMatch[1]))
              .limit(1);
            if (foundById && foundById.length > 0) {
              existingSbUser = foundById[0];
            }
          }
        }

        if (existingSbUser) {
          const existingRawPerms =
            typeof existingSbUser.permissions === 'string'
              ? (() => {
                  try {
                    return JSON.parse(existingSbUser.permissions);
                  } catch {
                    return null;
                  }
                })()
              : existingSbUser.permissions;
          const preservedPermissionsPayload =
            existingRawPerms && typeof existingRawPerms === 'object' && existingRawPerms.geofence
              ? { ...permissions, geofence: existingRawPerms.geofence }
              : permissions;
          // UPDATE existing row
          let updatePayload: any = {
            permissions: preservedPermissionsPayload,
            updated_at: new Date().toISOString(),
          };

          for (let attempt = 0; attempt < 5; attempt++) {
            const query = existingSbUser.id
              ? sb.from('users').update(updatePayload).eq('id', existingSbUser.id)
              : sb.from('users').update(updatePayload).ilike('email', email!);

            const { error: updErr } = await query;
            if (!updErr) {
              isRemoteSynced = true;
              break;
            }

            const errMsg = (updErr.message || '').toLowerCase();
            // If updated_at column does not exist, strip and retry
            if (updErr.code === '42703' && errMsg.includes('updated_at')) {
              delete updatePayload.updated_at;
              continue;
            }
            // If permissions needs to be serialized as string for TEXT column
            if (errMsg.includes('text') || errMsg.includes('string') || errMsg.includes('malformed')) {
              updatePayload.permissions = JSON.stringify(preservedPermissionsPayload);
              continue;
            }
            syncError = updErr.message;
            break;
          }
        } else {
          // INSERT or UPSERT user with permissions
          const insertPayload: any = {
            name: targetUser?.name || updatedUserObj?.name || 'Ensec Staff',
            email: email || `${String(uid).toLowerCase()}@ensecbd.com`,
            password: targetUser?.password || updatedUserObj?.password || 'ensec2026',
            phone: targetUser?.phone || updatedUserObj?.phone || null,
            role: targetUser?.role || updatedUserObj?.role || 'Field Force',
            designation: targetUser?.designation || updatedUserObj?.designation || null,
            department: targetUser?.department || updatedUserObj?.department || 'Operations',
            status: targetUser?.status || updatedUserObj?.status || 'Active',
            uid: uid,
            permissions: permissions,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          };

          for (let attempt = 0; attempt < 5; attempt++) {
            const { error: insErr } = await sb
              .from('users')
              .upsert(insertPayload, { onConflict: 'email' });

            if (!insErr) {
              isRemoteSynced = true;
              break;
            }

            const colMatch =
              insErr.message.match(/column ["']?([a-zA-Z0-9_]+)["']? of relation ["']?users["']? does not exist/i) ||
              insErr.message.match(/Could not find the ['"]?([a-zA-Z0-9_]+)['"]? column/i);
            if (colMatch && colMatch[1] && colMatch[1] !== 'email') {
              delete insertPayload[colMatch[1]];
              continue;
            }
            syncError = insErr.message;
            break;
          }
        }
      } catch (err: any) {
        console.warn('Supabase updateUserPermissions sync error:', err);
        syncError = err?.message;
      }
    }

    return {
      success: true,
      isRemoteSynced,
      message: isRemoteSynced
        ? 'Permissions updated and synced with cloud database.'
        : 'Permissions saved to persistent system storage.',
      error: syncError,
    };
  };

  const updateUserPagePermissions = async (
    userId: string,
    pagePermissions: UserPagePermissionsMap
  ): Promise<{ success: boolean; isRemoteSynced: boolean; message: string; error?: string }> => {
    const targetUser = users.find(
      (u) =>
        u.id === userId ||
        u.userId === userId ||
        (u.email && u.email.toLowerCase() === userId.toLowerCase())
    );
    const basePerms = targetUser?.permissions || getDefaultPermissionsForRole(targetUser?.role || 'Field Force');
    
    // Accurate allowedModules: only pages that explicitly have view: true
    const allowedPages = Object.keys(pagePermissions).filter((p) => pagePermissions[p]?.view);

    const updatedPermissions: UserPermissions = {
      ...basePerms,
      allowedModules: allowedPages as PageModuleId[],
      pagePermissions,
    };

    const result = await updateUserPermissions(userId, updatedPermissions);
    return {
      ...result,
      message: result.message || 'Page permissions updated successfully.',
    };
  };

  const hasPageActionHook = (pageId: string, actionKey: string = 'view'): boolean => {
    return hasPageAction(currentUser, pageId, actionKey);
  };

  const hasPageAccessHook = (pageId: string): boolean => {
    return hasPageAccess(currentUser, pageId);
  };

  const canApproveTransactionHook = (pageId: string, creatorIdentifier?: string) => {
    return canApproveTransaction(currentUser, pageId, creatorIdentifier);
  };

  const deleteUser = (userId: string) => {
    setUsers((prev) => prev.filter((u) => u.id !== userId));
    addAuditLog('USER_DELETED', 'User Management', `Removed user account ID ${userId}`);
  };

  const currentUserHasPermission = (moduleId: string): boolean => {
    if (currentUser.role === 'Super Admin') return true;
    if (moduleId === 'manufacturing-costing') return hasAnyManufacturingCostingAccess(currentUser);
    return hasPageAccess(currentUser, moduleId);
  };

  const currentUserHasFeature = (featureKey: keyof FeaturePermissions): boolean => {
    return hasFeaturePermission(currentUser, featureKey);
  };

  // --- WARRANTY & SERVICE MANAGEMENT METHODS ---
  const addWarrantyTicket = (ticketData: Omit<WarrantyTicket, 'id' | 'createdAt' | 'updatedAt'>): string => {
    const id = `ticket-${Date.now().toString().slice(-6)}`;
    const ticketSeq = (warrantyTickets.length + 1).toString().padStart(5, '0');
    const ticketNumber = ticketData.ticketNumber || `ENS-WAR-2026-${ticketSeq}`;
    const now = new Date().toISOString();
    const newTicket: WarrantyTicket = {
      ...ticketData,
      id,
      ticketNumber,
      userId: ticketData.userId || currentUser?.id,
      employeeId: ticketData.employeeId || currentEmployeeProfile?.employeeId,
      employeeCode: ticketData.employeeCode || currentEmployeeProfile?.employeeCode,
      createdAt: now,
      updatedAt: now,
    };
    setWarrantyTickets((prev) => [newTicket, ...prev]);
    addAuditLog(
      'WARRANTY_TICKET_CREATED',
      'Warranty & Service',
      `Registered complaint #${ticketNumber} for customer ${newTicket.customerName} (${newTicket.ownershipType} - ${newTicket.batteryBrand} ${newTicket.serialNumber})`
    );
    return id;
  };

  const updateWarrantyTicket = (ticketId: string, updates: Partial<WarrantyTicket>) => {
    const now = new Date().toISOString();
    setWarrantyTickets((prev) =>
      prev.map((t) => (t.id === ticketId ? { ...t, ...updates, updatedAt: now } : t))
    );
    addAuditLog(
      'WARRANTY_TICKET_UPDATED',
      'Warranty & Service',
      `Updated service ticket ID ${ticketId} details & workflow stage`
    );
  };

  const deleteWarrantyTicket = (ticketId: string) => {
    setWarrantyTickets((prev) => prev.filter((t) => t.id !== ticketId));
    addAuditLog('WARRANTY_TICKET_DELETED', 'Warranty & Service', `Removed ticket ID ${ticketId}`);
  };

  const addBatteryReceiving = (record: Omit<BatteryReceivingRecord, 'id'>): string => {
    const id = `rec-${Date.now().toString().slice(-6)}`;
    const newRecord: BatteryReceivingRecord = { ...record, id };
    setBatteryReceivings((prev) => [newRecord, ...prev]);
    if (record.ticketId) {
      updateWarrantyTicket(record.ticketId, {
        isReceivedAtFactory: true,
        receivingId: id,
        receivedDate: record.receivingDate,
        receivingReceiptNumber: record.receivingReceiptNumber,
        status: 'Battery Received',
      });
    }
    addAuditLog(
      'BATTERY_RECEIVED_FACTORY',
      'Warranty & Service',
      `Factory received battery ${record.batteryBrand} (${record.serialNumber}) via ${record.deliveryMethod}. Receipt: ${record.receivingReceiptNumber}`
    );
    return id;
  };

  const addTechnicalInspection = (inspection: Omit<TechnicalInspection, 'id'>): string => {
    const id = `insp-${Date.now().toString().slice(-6)}`;
    const newInsp: TechnicalInspection = { ...inspection, id };
    setTechnicalInspections((prev) => [newInsp, ...prev]);
    if (inspection.ticketId) {
      updateWarrantyTicket(inspection.ticketId, {
        inspectionId: id,
        inspectedBy: inspection.technicianName,
        inspectionDate: inspection.inspectionDate,
        isSafetyHold: inspection.isSafetyHold,
        safetyHoldReason: inspection.safetyHoldReason,
        status: inspection.isSafetyHold ? 'Safety Hold' : 'Technical Inspection',
      });
    }
    addAuditLog(
      'TECHNICAL_INSPECTION_LOGGED',
      'Warranty & Service',
      `Logged technical inspection for ${inspection.ticketNumber} (${inspection.serialNumber}). Safety hold: ${inspection.isSafetyHold ? 'YES' : 'NO'}`
    );
    return id;
  };

  const updateTechnicalInspection = (id: string, updates: Partial<TechnicalInspection>) => {
    setTechnicalInspections((prev) =>
      prev.map((i) => (i.id === id ? { ...i, ...updates } : i))
    );
  };

  const addServiceJobCard = (jobCard: Omit<ServiceJobCard, 'id' | 'creationDate'>): string => {
    const id = `jc-${Date.now().toString().slice(-6)}`;
    const creationDate = new Date().toISOString().slice(0, 10);
    const newJobCard: ServiceJobCard = { ...jobCard, id, creationDate };
    setServiceJobCards((prev) => [newJobCard, ...prev]);
    if (jobCard.ticketId) {
      updateWarrantyTicket(jobCard.ticketId, {
        jobCardId: id,
        jobCardNumber: jobCard.jobCardNumber,
        status: 'In Repair',
        warrantyDecision: jobCard.warrantyDecision,
      });
    }
    addAuditLog(
      'JOB_CARD_CREATED',
      'Warranty & Service',
      `Created Job Card ${jobCard.jobCardNumber} assigned to ${jobCard.assignedTechnician} (Priority: ${jobCard.repairPriority})`
    );
    return id;
  };

  const updateServiceJobCard = (jobCardId: string, updates: Partial<ServiceJobCard>) => {
    setServiceJobCards((prev) =>
      prev.map((jc) => (jc.id === jobCardId ? { ...jc, ...updates } : jc))
    );
    if (updates.status) {
      const card = serviceJobCards.find((j) => j.id === jobCardId);
      if (card && card.ticketId) {
        if (updates.status === 'Repair Completed') {
          updateWarrantyTicket(card.ticketId, { status: 'Quality Control Pending' });
        } else if (updates.status === 'Quality Control Passed') {
          updateWarrantyTicket(card.ticketId, { status: 'Ready for Dispatch' });
        } else if (updates.status === 'Delivered') {
          updateWarrantyTicket(card.ticketId, { status: 'Delivered' });
        }
      }
    }
    addAuditLog(
      'JOB_CARD_UPDATED',
      'Warranty & Service',
      `Updated Job Card ID ${jobCardId} status to ${updates.status || 'modified'}`
    );
  };

  const addSparePartsConsumption = (part: Omit<SparePartReplacement, 'id'>): string => {
    const id = `part-${Date.now().toString().slice(-6)}`;
    const newPart: SparePartReplacement = { ...part, id };
    setSparePartsConsumptions((prev) => [newPart, ...prev]);

    setRawMaterials((prev) =>
      prev.map((rm) => {
        if (rm.code === part.partCode || rm.name === part.partName) {
          const updatedStock = Math.max(0, rm.stockKushtia - part.replacementQty);
          return { ...rm, stockKushtia: updatedStock };
        }
        return rm;
      })
    );

    addAuditLog(
      'SPARE_PART_CONSUMED',
      'Warranty & Service',
      `Issued ${part.replacementQty} ${part.unit} of ${part.partName} (${part.partCode}) for ${part.jobCardNumber}. Coverage: ${part.warrantyCoverageStatus}`
    );
    return id;
  };

  const addServiceEstimation = (est: Omit<RepairEstimation, 'id'>): string => {
    const id = `est-${Date.now().toString().slice(-6)}`;
    const newEst: RepairEstimation = { ...est, id };
    setServiceEstimations((prev) => [newEst, ...prev]);
    if (est.ticketId) {
      updateWarrantyTicket(est.ticketId, {
        estimatedCostBDT: est.totalEstimatedAmountBDT,
        status: 'Quotation Pending Approval',
      });
    }
    addAuditLog(
      'REPAIR_ESTIMATION_CREATED',
      'Warranty & Service',
      `Prepared Quotation ${est.estimationNumber} for ${est.customerName} - Total: BDT ${est.totalEstimatedAmountBDT}`
    );
    return id;
  };

  const updateServiceEstimation = (id: string, updates: Partial<RepairEstimation>) => {
    setServiceEstimations((prev) =>
      prev.map((e) => (e.id === id ? { ...e, ...updates } : e))
    );
    if (updates.customerApprovalStatus === 'Approved by Customer') {
      const est = serviceEstimations.find((e) => e.id === id);
      if (est && est.ticketId) {
        updateWarrantyTicket(est.ticketId, { status: 'Paid Repair Approved' });
      }
    }
  };

  const addServiceInvoice = (inv: Omit<ServiceInvoice, 'id'>): string => {
    const id = `inv-${Date.now().toString().slice(-6)}`;
    const newInv: ServiceInvoice = { ...inv, id };
    setServiceInvoices((prev) => [newInv, ...prev]);
    if (inv.ticketId) {
      updateWarrantyTicket(inv.ticketId, {
        invoiceId: id,
        invoiceNumber: inv.invoiceNumber,
        invoiceTotalBDT: inv.totalInvoiceAmountBDT,
        amountPaidBDT: inv.amountPaidBDT,
        paymentStatus: inv.paymentStatus,
      });
    }
    addAuditLog(
      'SERVICE_INVOICE_GENERATED',
      'Warranty & Service',
      `Generated Service Invoice ${inv.invoiceNumber} for ${inv.customerName}. Customer payable: BDT ${inv.totalInvoiceAmountBDT}, Warranty absorbed: BDT ${inv.warrantyCoveredCostBDT}`
    );
    return id;
  };

  const updateServiceInvoice = (id: string, updates: Partial<ServiceInvoice>) => {
    setServiceInvoices((prev) =>
      prev.map((i) => (i.id === id ? { ...i, ...updates } : i))
    );
  };

  const addServicePayment = (payment: Omit<ServicePayment, 'id'>): string => {
    const id = `pay-${Date.now().toString().slice(-6)}`;
    const newPayment: ServicePayment = { ...payment, id };
    setServicePayments((prev) => [newPayment, ...prev]);

    setServiceInvoices((prev) =>
      prev.map((inv) => {
        if (inv.id === payment.invoiceId || inv.invoiceNumber === payment.invoiceNumber) {
          const newPaid = inv.amountPaidBDT + payment.amountBDT;
          const newOutstanding = Math.max(0, inv.totalInvoiceAmountBDT - newPaid);
          const newStatus = newOutstanding <= 0 ? 'Paid' : newPaid > 0 ? 'Partially Paid' : 'Unpaid';
          return {
            ...inv,
            amountPaidBDT: newPaid,
            outstandingAmountBDT: newOutstanding,
            paymentStatus: newStatus,
          };
        }
        return inv;
      })
    );

    addCashBookEntry({
      date: payment.paymentDate.slice(0, 10),
      voucherNo: payment.receiptNumber,
      accountType: payment.paymentMethod === 'Cash' ? 'Factory Cash' : 'Eastern Bank PLC',
      transactionCategory: 'Customer Payment',
      description: `Service receipt from ${payment.customerName} for ${payment.ticketNumber} via ${payment.paymentMethod}`,
      reference: payment.receiptNumber,
      cashInBDT: payment.amountBDT,
      cashOutBDT: 0,
    });

    addAuditLog(
      'SERVICE_PAYMENT_COLLECTED',
      'Warranty & Service',
      `Collected payment BDT ${payment.amountBDT} for ${payment.ticketNumber} via ${payment.paymentMethod}. Receipt: ${payment.receiptNumber}`
    );
    return id;
  };

  const addQualityControlRecord = (qc: Omit<QualityControlRecord, 'id'>): string => {
    const id = `qc-${Date.now().toString().slice(-6)}`;
    const newQC: QualityControlRecord = { ...qc, id };
    setQualityControlRecords((prev) => [newQC, ...prev]);
    if (qc.result === 'QC Passed') {
      if (qc.jobCardId) {
        updateServiceJobCard(qc.jobCardId, { status: 'Quality Control Passed' });
      }
      const ticket = warrantyTickets.find((t) => t.ticketNumber === qc.ticketNumber);
      if (ticket) {
        updateWarrantyTicket(ticket.id, { qcStatus: 'Passed', status: 'Ready for Dispatch' });
      }
    } else if (qc.result === 'QC Failed') {
      if (qc.jobCardId) {
        updateServiceJobCard(qc.jobCardId, { status: 'Quality Control Failed' });
      }
      const ticket = warrantyTickets.find((t) => t.ticketNumber === qc.ticketNumber);
      if (ticket) {
        updateWarrantyTicket(ticket.id, { qcStatus: 'Failed', status: 'In Repair' });
      }
    }
    addAuditLog(
      'QUALITY_CONTROL_RECORDED',
      'Warranty & Service',
      `Recorded QC inspection #${qc.qcNumber} by ${qc.qcInspector}. Result: ${qc.result}`
    );
    return id;
  };

  const addBatteryDispatch = (dsp: Omit<BatteryDeliveryDispatch, 'id'>): string => {
    const id = `dsp-${Date.now().toString().slice(-6)}`;
    const newDsp: BatteryDeliveryDispatch = { ...dsp, id };
    setBatteryDispatches((prev) => [newDsp, ...prev]);
    if (dsp.ticketId) {
      updateWarrantyTicket(dsp.ticketId, {
        status: 'Delivered',
        dispatchId: id,
        dispatchDate: dsp.deliveryDate,
        deliveredBy: dsp.deliveredBy,
      });
    }
    if (dsp.jobCardId) {
      updateServiceJobCard(dsp.jobCardId, { status: 'Delivered' });
    }
    addAuditLog(
      'BATTERY_DISPATCHED',
      'Warranty & Service',
      `Battery ${dsp.batteryBrand} (${dsp.serialNumber}) dispatched to ${dsp.customerName} via ${dsp.deliveryMethod}. Gate pass: ${dsp.gatePassNumber}`
    );
    return id;
  };

  const addWarrantyPolicy = (policy: Omit<WarrantyPolicy, 'id'>): string => {
    const id = `pol-${Date.now().toString().slice(-6)}`;
    const newPol: WarrantyPolicy = { ...policy, id };
    setWarrantyPolicies((prev) => [...prev, newPol]);
    addAuditLog(
      'WARRANTY_POLICY_CREATED',
      'Warranty & Service',
      `Configured new warranty policy ${newPol.policyName} (${newPol.durationMonths} months)`
    );
    return id;
  };

  const updateWarrantyPolicy = (id: string, updates: Partial<WarrantyPolicy>) => {
    setWarrantyPolicies((prev) =>
      prev.map((p) => (p.id === id ? { ...p, ...updates } : p))
    );
    addAuditLog('WARRANTY_POLICY_UPDATED', 'Warranty & Service', `Updated policy ID ${id}`);
  };

  const updateServiceSettings = (settings: Partial<ServiceSettings>) => {
    setServiceSettings((prev) => ({ ...prev, ...settings }));
    addAuditLog('SERVICE_SETTINGS_UPDATED', 'Warranty & Service', `Updated after-sales service configurations`);
  };

  // ============================================================================
  // --- INSTALLMENT & RECEIVABLES MANAGEMENT METHODS ---
  // ============================================================================

  const findLinkedSalesOrderForPlan = (plan: Pick<InstallmentPlan, 'salesOrderId' | 'invoiceReference'>) => {
    const invRefLower = String(plan.invoiceReference || '').trim().toLowerCase();
    return salesOrders.find(
      (so) =>
        (plan.salesOrderId && String(so.id) === String(plan.salesOrderId)) ||
        (invRefLower &&
          ((so.orderNumber && so.orderNumber.trim().toLowerCase() === invRefLower) ||
            (so.invoiceNumber && so.invoiceNumber.trim().toLowerCase() === invRefLower) ||
            (so.invoiceNo && so.invoiceNo.trim().toLowerCase() === invRefLower)))
    );
  };

  const syncInstallmentPaymentToSalesOrder = async (
    plan: Pick<InstallmentPlan, 'salesOrderId' | 'invoiceReference'>,
    paidAmountBDT: number,
    options?: { markFullySettled?: boolean }
  ) => {
    const amount = Math.max(0, Number(paidAmountBDT) || 0);
    if (amount <= 0 && !options?.markFullySettled) return;

    const matchedOrder = findLinkedSalesOrderForPlan(plan);
    if (!matchedOrder) return;

    const currentPaid = Number(matchedOrder.paidAmountBDT) || 0;
    const netAmount = Number(matchedOrder.netAmountBDT) || 0;
    const currentDue =
      matchedOrder.dueAmountBDT !== undefined
        ? Number(matchedOrder.dueAmountBDT) || 0
        : Math.max(0, netAmount - currentPaid);

    const effectiveReduction = options?.markFullySettled
      ? currentDue
      : Math.min(currentDue, amount);

    const updatedPaid = options?.markFullySettled
      ? netAmount
      : Math.min(netAmount, currentPaid + amount);
    const updatedDue = options?.markFullySettled
      ? 0
      : Math.max(0, netAmount - updatedPaid);
    const updatedPaymentStatus =
      updatedDue <= 0 ? 'Paid' : updatedPaid > 0 ? 'Partially Paid' : 'Unpaid';

    setSalesOrders((prev) =>
      prev.map((so) =>
        so.id === matchedOrder.id
          ? {
              ...so,
              paidAmountBDT: updatedPaid,
              dueAmountBDT: updatedDue,
              paymentStatus: updatedPaymentStatus,
            }
          : so
      )
    );

    if (effectiveReduction > 0) {
      if (matchedOrder.channel === 'Distributor Sales' && matchedOrder.distributorId) {
        setDistributors((dists) =>
          dists.map((d) =>
            d.id === matchedOrder.distributorId
              ? { ...d, currentOutstandingBDT: Math.max(0, d.currentOutstandingBDT - effectiveReduction) }
              : d
          )
        );
      } else if (matchedOrder.customerId) {
        setCustomers((custs) =>
          custs.map((c) =>
            c.id === matchedOrder.customerId
              ? { ...c, outstandingBalanceBDT: Math.max(0, c.outstandingBalanceBDT - effectiveReduction) }
              : c
          )
        );
      }
    }

    const sb = getSupabase();
    if (sb) {
      try {
        const orderIdStr = String(matchedOrder.id || '');
        const isNumeric = /^\d+$/.test(orderIdStr);
        const query = isNumeric
          ? sb
              .from('sales_orders')
              .update({ paid_amount_bdt: updatedPaid, due_amount_bdt: updatedDue })
              .eq('id', Number(orderIdStr))
          : sb
              .from('sales_orders')
              .update({ paid_amount_bdt: updatedPaid, due_amount_bdt: updatedDue })
              .eq('order_number', matchedOrder.orderNumber || orderIdStr);
        const { error } = await query;
        if (error) {
          console.error('Failed to sync installment payment to Supabase sales_orders:', error);
        }
      } catch (err) {
        console.warn('Supabase sales_orders installment sync notice:', err);
      }
    }
  };

  const createInstallmentPlan = async (
    planData: Omit<InstallmentPlan, 'id' | 'createdAt' | 'updatedAt'>,
    customSchedules?: InstallmentSchedule[]
  ): Promise<{ success: boolean; id: string; error?: string }> => {
    try {
      const sb = getSupabase();
      const year = new Date().getFullYear();
      const today = new Date().toISOString().slice(0, 10);

      // Collect existing IDs & agreement numbers from both local state and live Supabase DB
      const existingPlanIds = new Set<string>(installmentPlans.map((p) => String(p.id)));
      const existingAgreementNos = new Set<string>(installmentPlans.map((p) => String(p.agreementNo)));
      let maxSeq = 0;

      const extractSeq = (val?: string | null) => {
        if (!val) return 0;
        const m = String(val).match(/(\d+)\s*$/);
        return m ? parseInt(m[1], 10) : 0;
      };

      installmentPlans.forEach((p) => {
        maxSeq = Math.max(maxSeq, extractSeq(p.id), extractSeq(p.agreementNo));
      });

      if (sb) {
        const { data: dbExistingPlans, error: lookupErr } = await sb
          .from('installment_plans')
          .select('id, agreement_no');
        if (!lookupErr && Array.isArray(dbExistingPlans)) {
          dbExistingPlans.forEach((row: any) => {
            if (row.id) existingPlanIds.add(String(row.id));
            if (row.agreement_no) existingAgreementNos.add(String(row.agreement_no));
            maxSeq = Math.max(maxSeq, extractSeq(row.id), extractSeq(row.agreement_no));
          });
        }
      }

      let nextSeq = maxSeq + 1;
      let planSeq = nextSeq.toString().padStart(4, '0');
      let planId = `INS-${year}-${planSeq}`;
      let agreementNo = planData.agreementNo?.trim() || `ENS-AGR-${planSeq}`;

      while (
        existingPlanIds.has(planId) ||
        (!planData.agreementNo?.trim() && existingAgreementNos.has(agreementNo))
      ) {
        nextSeq += 1;
        planSeq = nextSeq.toString().padStart(4, '0');
        planId = `INS-${year}-${planSeq}`;
        agreementNo = planData.agreementNo?.trim() || `ENS-AGR-${planSeq}`;
      }

      const buildSchedulesForPlan = (targetPlanId: string, targetAgreementNo: string, seqToken: string): InstallmentSchedule[] => {
        if (customSchedules && customSchedules.length > 0) {
          return customSchedules.map((s, idx) => ({
            ...s,
            id: `SCH-${seqToken}-${(idx + 1).toString().padStart(2, '0')}`,
            planId: targetPlanId,
            agreementNo: targetAgreementNo,
          }));
        }

        const count = Number(planData.durationMonths) || 12;
        const monthlyAmt = planData.monthlyInstallmentBDT || Math.round(planData.financedAmountBDT / count);
        const monthlyInterest = planData.totalInterestBDT > 0 ? Math.round(planData.totalInterestBDT / count) : 0;
        const monthlyPrincipal = monthlyAmt - monthlyInterest;
        const firstDue = new Date(planData.firstDueDate || today);

        const list: InstallmentSchedule[] = [];
        for (let i = 1; i <= count; i++) {
          const dueDateObj = new Date(firstDue);
          dueDateObj.setMonth(dueDateObj.getMonth() + (i - 1));
          const dueDateStr = dueDateObj.toISOString().slice(0, 10);

          list.push({
            id: `SCH-${seqToken}-${i.toString().padStart(2, '0')}`,
            planId: targetPlanId,
            agreementNo: targetAgreementNo,
            installmentNumber: i,
            dueDate: dueDateStr,
            dueAmountBDT: monthlyAmt,
            principalAmountBDT: monthlyPrincipal,
            interestAmountBDT: monthlyInterest,
            paidAmountBDT: 0,
            remainingAmountBDT: monthlyAmt,
            status: 'Upcoming',
            overdueDays: 0,
            lateFeeBDT: 0,
          });
        }
        return list;
      };

      let generatedSchedules = buildSchedulesForPlan(planId, agreementNo, planSeq);

      let newPlan: InstallmentPlan = {
        ...planData,
        id: planId,
        agreementNo,
        customerPhone: planData.customerPhone?.trim() || 'N/A',
        totalPaidBDT: 0,
        totalOutstandingBDT: planData.financedAmountBDT,
        paidInstallmentsCount: 0,
        remainingInstallmentsCount: generatedSchedules.length,
        overdueInstallmentsCount: 0,
        overdueAmountBDT: 0,
        status: 'Active',
        createdAt: today,
        updatedAt: today,
      };

      // Supabase remote sync FIRST so DB failures are caught and never faked as success
      if (sb) {
        const buildPlanPayload = (p: InstallmentPlan) => ({
          id: p.id,
          agreement_no: p.agreementNo,
          customer_id: p.customerId || null,
          customer_name: p.customerName,
          customer_phone: p.customerPhone || 'N/A',
          customer_district: p.customerDistrict || 'Dhaka',
          distributor_id: p.distributorId || null,
          distributor_name: p.distributorName || null,
          sales_order_id: p.salesOrderId || null,
          invoice_reference: p.invoiceReference || null,
          product_id: p.productId || null,
          product_name: p.productName,
          product_model: p.productModel || null,
          quantity: Number(p.quantity) || 1,
          total_product_price_bdt: Number(p.totalProductPriceBDT) || 0,
          down_payment_bdt: Number(p.downPaymentBDT) || 0,
          financed_amount_bdt: Number(p.financedAmountBDT) || 0,
          duration_months: Number(p.durationMonths) || 12,
          interest_rate_percent: Number(p.interestRatePercent) || 0,
          total_interest_bdt: Number(p.totalInterestBDT) || 0,
          total_payable_bdt: Number(p.totalPayableBDT) || 0,
          monthly_installment_bdt: Number(p.monthlyInstallmentBDT) || 0,
          start_date: p.startDate || today,
          first_due_date: p.firstDueDate || today,
          payment_frequency: p.paymentFrequency || 'Monthly',
          status: p.status || 'Active',
          total_paid_bdt: Number(p.totalPaidBDT) || 0,
          total_outstanding_bdt: Number(p.totalOutstandingBDT) || 0,
          paid_installments_count: Number(p.paidInstallmentsCount) || 0,
          remaining_installments_count: Number(p.remainingInstallmentsCount) || generatedSchedules.length,
          overdue_installments_count: Number(p.overdueInstallmentsCount) || 0,
          overdue_amount_bdt: Number(p.overdueAmountBDT) || 0,
          guarantor_name: p.guarantorName || null,
          guarantor_phone: p.guarantorPhone || null,
          guarantor_nid: p.guarantorNID || null,
          guarantor_address: p.guarantorAddress || null,
          remarks: p.remarks || null,
          assigned_officer_id: p.assignedOfficerId || null,
          assigned_officer_name: p.assignedOfficerName || null,
        });

        let { error: planError } = await sb
          .from('installment_plans')
          .insert(buildPlanPayload(newPlan))
          .select()
          .single();

        // Retry once with unique suffix on race-condition duplicate key
        if (planError && planError.code === '23505') {
          const uniqueSeq = `${planSeq}-${Date.now().toString().slice(-4)}`;
          planId = `INS-${year}-${uniqueSeq}`;
          agreementNo = planData.agreementNo?.trim()
            ? `${planData.agreementNo.trim()}-${Date.now().toString().slice(-3)}`
            : `ENS-AGR-${uniqueSeq}`;
          generatedSchedules = buildSchedulesForPlan(planId, agreementNo, uniqueSeq);
          newPlan = {
            ...newPlan,
            id: planId,
            agreementNo,
          };
          const retryRes = await sb
            .from('installment_plans')
            .insert(buildPlanPayload(newPlan))
            .select()
            .single();
          planError = retryRes.error;
        }

        if (planError) {
          console.error('Supabase installment_plans insert failed:', planError);
          return {
            success: false,
            id: '',
            error: `Failed to save installment plan to database: ${planError.message}`,
          };
        }

        const buildSchedulesPayload = (scheds: InstallmentSchedule[]) =>
          scheds.map((s) => ({
            id: s.id,
            plan_id: s.planId,
            agreement_no: s.agreementNo,
            installment_number: s.installmentNumber,
            due_date: s.dueDate,
            due_amount_bdt: s.dueAmountBDT,
            principal_amount_bdt: s.principalAmountBDT,
            interest_amount_bdt: s.interestAmountBDT,
            paid_amount_bdt: s.paidAmountBDT,
            remaining_amount_bdt: s.remainingAmountBDT,
            status: s.status,
            overdue_days: s.overdueDays,
            late_fee_bdt: s.lateFeeBDT || 0,
          }));

        let { error: schedError } = await sb
          .from('installment_schedules')
          .insert(buildSchedulesPayload(generatedSchedules));

        // If schedule ID collided with an orphan/legacy schedule ID, retry with unique token
        if (schedError && schedError.code === '23505') {
          const uniqueSchedToken = `${planSeq}-${Date.now().toString().slice(-5)}`;
          generatedSchedules = buildSchedulesForPlan(planId, agreementNo, uniqueSchedToken);
          const schedRetry = await sb
            .from('installment_schedules')
            .insert(buildSchedulesPayload(generatedSchedules));
          schedError = schedRetry.error;
        }

        if (schedError) {
          console.error('Supabase installment_schedules insert failed:', schedError);
          // Roll back plan row so we do not leave an agreement without its schedule rows
          await sb.from('installment_plans').delete().eq('id', planId);
          return {
            success: false,
            id: '',
            error: `Failed to save installment schedule to database: ${schedError.message}`,
          };
        }
      }

      // Update local React state and persistent storage once DB save succeeds
      setInstallmentPlans((prev) => [newPlan, ...prev]);
      setInstallmentSchedules((prev) => [...generatedSchedules, ...prev]);
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem('ensec_installment_test_purged_v2', 'true');
        } catch {}
      }

      // If down payment was received, record in Cash Book and reflect on linked Sales Order
      if (newPlan.downPaymentBDT > 0) {
        const lastCash = cashBook[cashBook.length - 1];
        const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
        const downPaymentVoucher: CashBookEntry = {
          id: `cash-dp-${Date.now()}`,
          date: today,
          voucherNo: `VOUCH-DP-${planSeq}`,
          accountType: 'Eastern Bank PLC (Current A/C)',
          transactionCategory: 'Installment Down Payment',
          description: `Down payment received for Agreement ${agreementNo} (${newPlan.customerName} - ${newPlan.productName})`,
          reference: agreementNo,
          cashInBDT: newPlan.downPaymentBDT,
          cashOutBDT: 0,
          runningBalanceBDT: prevBal + newPlan.downPaymentBDT,
        };
        setCashBook((prev) => [...prev, downPaymentVoucher]);

        const linkedOrder = findLinkedSalesOrderForPlan(newPlan);
        if (linkedOrder) {
          const alreadyPaidOnOrder = Number(linkedOrder.paidAmountBDT) || 0;
          const downPaymentDelta = Math.max(0, Number(newPlan.downPaymentBDT) - alreadyPaidOnOrder);
          if (downPaymentDelta > 0) {
            await syncInstallmentPaymentToSalesOrder(newPlan, downPaymentDelta);
          }
        }
      }

      // Add Audit Log
      addAuditLog(
        'INSTALLMENT_PLAN_CREATED',
        'Installment & Receivables',
        `Created agreement ${agreementNo} for customer ${newPlan.customerName}. Financed: ৳${newPlan.financedAmountBDT.toLocaleString()}, Duration: ${newPlan.durationMonths} months.`
      );

      // Create Initial Notification
      const initialNotif: InstallmentNotification = {
        id: `notif-${Date.now()}`,
        title: `New Agreement Activated: ${agreementNo}`,
        message: `${newPlan.customerName} - ${newPlan.productName} (৳${newPlan.financedAmountBDT.toLocaleString()} financed for ${newPlan.durationMonths}m)`,
        type: 'upcoming_due',
        priority: 'low',
        referenceId: planId,
        isRead: false,
        createdAt: `${today} ${new Date().toTimeString().slice(0, 8)}`,
      };
      setInstallmentNotifications((prev) => [initialNotif, ...prev]);

      if (sb) {
        sb.from('installment_notifications')
          .insert({
            id: initialNotif.id,
            title: initialNotif.title,
            message: initialNotif.message,
            type: initialNotif.type,
            priority: initialNotif.priority,
            reference_id: initialNotif.referenceId,
            is_read: initialNotif.isRead,
          })
          .then(({ error }) => {
            if (error) console.warn('Supabase notification insert notice:', error.message);
          });
      }

      return { success: true, id: planId };
    } catch (err: any) {
      return { success: false, id: '', error: err?.message || 'Failed to create plan' };
    }
  };

  const recordInstallmentPayment = async (
    paymentData: Omit<InstallmentPayment, 'id' | 'createdAt' | 'allocations' | 'paymentReceiptNo'> & { paymentReceiptNo?: string }
  ): Promise<{ success: boolean; id: string; error?: string; receiptNo: string }> => {
    try {
      const plan = installmentPlans.find((p) => p.id === paymentData.planId);
      if (!plan) {
        return { success: false, id: '', receiptNo: '', error: 'Installment plan not found' };
      }

      // Check duplicate payment reference
      const isDuplicate = installmentPayments.some(
        (p) =>
          p.planId === paymentData.planId &&
          p.transactionReference.trim().toLowerCase() === paymentData.transactionReference.trim().toLowerCase() &&
          p.amountBDT === paymentData.amountBDT
      );
      if (isDuplicate) {
        return {
          success: false,
          id: '',
          receiptNo: '',
          error: `Payment entry rejected: Duplicate transaction reference "${paymentData.transactionReference}" already exists.`,
        };
      }

      const today = new Date().toISOString().slice(0, 10);
      const year = new Date().getFullYear();
      const paymentId = `PAY-INS-${Date.now().toString().slice(-6)}`;

      const sb = getSupabase();
      let maxReceiptNum = 100;
      const extractReceiptSeq = (val?: string | null) => {
        if (!val) return 0;
        const m = String(val).match(/(\d+)\s*$/);
        return m ? parseInt(m[1], 10) : 0;
      };
      installmentPayments.forEach((p) => {
        maxReceiptNum = Math.max(maxReceiptNum, extractReceiptSeq(p.paymentReceiptNo));
      });
      if (sb) {
        const { data: existingReceipts } = await sb
          .from('installment_payments')
          .select('payment_receipt_no');
        if (Array.isArray(existingReceipts)) {
          existingReceipts.forEach((r: any) => {
            maxReceiptNum = Math.max(maxReceiptNum, extractReceiptSeq(r.payment_receipt_no));
          });
        }
      }
      const receiptSeq = (maxReceiptNum + 1).toString();
      const paymentReceiptNo = paymentData.paymentReceiptNo || `RCP-${year}-${receiptSeq}`;

      // Run FIFO allocation on plan's unpaid schedules
      const planSchedules = installmentSchedules.filter((s) => s.planId === paymentData.planId);
      const unpaid = planSchedules.filter((s) => s.status !== 'Paid');

      const { allocations, updatedSchedules } = allocatePaymentFIFO(
        unpaid,
        paymentData.amountBDT,
        paymentId
      );

      const newPayment: InstallmentPayment = {
        ...paymentData,
        id: paymentId,
        paymentReceiptNo,
        allocations,
        createdAt: new Date().toISOString(),
      };

      // Merge updated schedules back into full list
      const scheduleMap = new Map(updatedSchedules.map((s) => [s.id, s]));
      const newAllSchedules = installmentSchedules.map((s) => (scheduleMap.has(s.id) ? scheduleMap.get(s.id)! : s));

      // Recompute plan status and aggregates
      const updatedPlanSchedules = newAllSchedules.filter((s) => s.planId === plan.id);
      const totalPaid = updatedPlanSchedules.reduce((sum, s) => sum + s.paidAmountBDT, 0);
      const totalOutstanding = updatedPlanSchedules.reduce((sum, s) => sum + s.remainingAmountBDT, 0);
      const paidCount = updatedPlanSchedules.filter((s) => s.status === 'Paid').length;
      const remainingCount = updatedPlanSchedules.filter((s) => s.status !== 'Paid').length;
      const overdueSchedules = updatedPlanSchedules.filter((s) => s.status === 'Overdue');
      const overdueCount = overdueSchedules.length;
      const overdueAmt = overdueSchedules.reduce((sum, s) => sum + s.remainingAmountBDT, 0);

      let newPlanStatus = plan.status;
      if (totalOutstanding <= 0) {
        newPlanStatus = 'Settled';
      } else if (overdueCount > 0) {
        newPlanStatus = 'Overdue';
      } else {
        newPlanStatus = 'Active';
      }

      const updatedPlan: InstallmentPlan = {
        ...plan,
        totalPaidBDT: totalPaid,
        totalOutstandingBDT: totalOutstanding,
        paidInstallmentsCount: paidCount,
        remainingInstallmentsCount: remainingCount,
        overdueInstallmentsCount: overdueCount,
        overdueAmountBDT: overdueAmt,
        status: newPlanStatus,
        updatedAt: today,
      };

      setInstallmentPayments((prev) => [newPayment, ...prev]);
      setInstallmentSchedules(newAllSchedules);
      setInstallmentPlans((prev) => prev.map((p) => (p.id === plan.id ? updatedPlan : p)));

      // Update linked Sales Order Paid / Due amounts & Customer/Distributor outstanding balance
      const principalPaidBDT =
        plan.totalInterestBDT > 0 && plan.totalPayableBDT > 0
          ? Math.round(paymentData.amountBDT * (plan.financedAmountBDT / plan.totalPayableBDT))
          : paymentData.amountBDT;
      await syncInstallmentPaymentToSalesOrder(plan, principalPaidBDT, {
        markFullySettled: totalOutstanding <= 0,
      });

      // 1. Post to Cash Book & General Ledger
      const lastCash = cashBook[cashBook.length - 1];
      const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
      const cashEntry: CashBookEntry = {
        id: `cash-ins-${Date.now()}`,
        date: paymentData.paymentDate || today,
        voucherNo: paymentReceiptNo,
        accountType: paymentData.bankAccountName || 'Eastern Bank PLC (Current A/C)',
        transactionCategory: 'Installment Collection',
        description: `Installment collection for Agreement ${plan.agreementNo} (${plan.customerName}) via ${paymentData.paymentMethod} - Ref: ${paymentData.transactionReference}`,
        reference: paymentReceiptNo,
        cashInBDT: paymentData.amountBDT,
        cashOutBDT: 0,
        runningBalanceBDT: prevBal + paymentData.amountBDT,
      };
      setCashBook((prev) => [...prev, cashEntry]);

      // 2. Audit Log
      addAuditLog(
        'INSTALLMENT_PAYMENT_COLLECTED',
        'Installment & Receivables',
        `Collected ৳${paymentData.amountBDT.toLocaleString()} for Agreement ${plan.agreementNo} (${plan.customerName}) - Receipt #${paymentReceiptNo}`
      );

      // 3. Automated SMS: Payment Confirmation
      const confirmRule = smsAutomationRules.find((r) => r.ruleCode === 'RULE_PAYMENT_CONFIRM');
      if (confirmRule && confirmRule.enabled) {
        const template = smsTemplates.find((t) => t.templateCode === 'PAYMENT_CONFIRMATION') || smsTemplates[4];
        if (template) {
          const compiled = compileTemplate(template.body, {
            CustomerName: plan.customerName,
            PaidAmount: paymentData.amountBDT,
            AgreementNo: plan.agreementNo,
            OutstandingAmount: totalOutstanding,
            ReceiptNo: paymentReceiptNo,
          });

          const smsResult = await sendSMSViaGateway({
            recipientPhone: plan.customerPhone,
            recipientName: plan.customerName,
            message: compiled,
            templateCode: template.templateCode,
            ruleId: confirmRule.id,
            planId: plan.id,
            agreementNo: plan.agreementNo,
            gatewaySettings: smsGatewaySettings,
          });

          setSmsLogs((prev) => [smsResult.log, ...prev]);
        }
      }

      // 4. In-App Notification
      const paymentNotif: InstallmentNotification = {
        id: `notif-${Date.now()}`,
        title: `Payment Received: ৳${paymentData.amountBDT.toLocaleString()}`,
        message: `${plan.customerName} (Agreement ${plan.agreementNo}) via ${paymentData.paymentMethod}. Remaining: ৳${totalOutstanding.toLocaleString()}`,
        type: 'payment_received',
        priority: 'medium',
        referenceId: plan.id,
        isRead: false,
        createdAt: `${today} ${new Date().toTimeString().slice(0, 8)}`,
      };
      setInstallmentNotifications((prev) => [paymentNotif, ...prev]);

      // 5. Remote Supabase sync if online
      if (sb) {
        try {
          const { error: payErr } = await sb.from('installment_payments').insert({
            id: newPayment.id,
            payment_receipt_no: newPayment.paymentReceiptNo,
            plan_id: newPayment.planId,
            agreement_no: newPayment.agreementNo,
            customer_id: newPayment.customerId || null,
            customer_name: newPayment.customerName,
            amount_bdt: newPayment.amountBDT,
            payment_type: newPayment.paymentType,
            payment_method: newPayment.paymentMethod,
            bank_account_id: newPayment.bankAccountId || null,
            bank_account_name: newPayment.bankAccountName || null,
            transaction_reference: newPayment.transactionReference,
            payment_date: newPayment.paymentDate,
            received_by_id: newPayment.receivedById || null,
            received_by_name: newPayment.receivedByName || null,
            notes: newPayment.notes || null,
          });
          if (payErr) {
            console.error('Supabase installment_payments insert failed:', payErr);
          }

          for (const s of updatedSchedules) {
            const { error: schUpdErr } = await sb.from('installment_schedules').update({
              paid_amount_bdt: s.paidAmountBDT,
              remaining_amount_bdt: s.remainingAmountBDT,
              status: s.status,
              payment_date: s.paymentDate || null,
              overdue_days: s.overdueDays,
            }).eq('id', s.id);
            if (schUpdErr) {
              console.error('Supabase installment_schedules update failed:', schUpdErr);
            }
          }

          const { error: planUpdErr } = await sb.from('installment_plans').update({
            total_paid_bdt: updatedPlan.totalPaidBDT,
            total_outstanding_bdt: updatedPlan.totalOutstandingBDT,
            paid_installments_count: updatedPlan.paidInstallmentsCount,
            remaining_installments_count: updatedPlan.remainingInstallmentsCount,
            overdue_installments_count: updatedPlan.overdueInstallmentsCount,
            overdue_amount_bdt: updatedPlan.overdueAmountBDT,
            status: updatedPlan.status,
          }).eq('id', updatedPlan.id);
          if (planUpdErr) {
            console.error('Supabase installment_plans update failed:', planUpdErr);
          }
        } catch (sbErr) {
          console.warn('Supabase remote payment sync notice:', sbErr);
        }
      }

      return { success: true, id: paymentId, receiptNo: paymentReceiptNo };
    } catch (err: any) {
      return { success: false, id: '', receiptNo: '', error: err?.message || 'Payment collection error' };
    }
  };

  const recordEarlySettlement = async (
    planId: string,
    settlementData: {
      rebatePercent: number;
      paymentMethod: any;
      bankAccountId?: string;
      bankAccountName?: string;
      transactionRef: string;
      notes?: string;
    }
  ): Promise<{ success: boolean; error?: string }> => {
    try {
      const plan = installmentPlans.find((p) => p.id === planId);
      if (!plan) return { success: false, error: 'Plan not found' };

      const planSchedules = installmentSchedules.filter((s) => s.planId === planId);
      const calc = calculateEarlySettlement(plan, planSchedules, settlementData.rebatePercent);
      const today = new Date().toISOString().slice(0, 10);
      const receiptNo = `STL-${Date.now().toString().slice(-5)}`;

      // Mark all unpaid schedules as paid
      const updatedSchedules = installmentSchedules.map((s) => {
        if (s.planId === planId && s.status !== 'Paid') {
          return {
            ...s,
            paidAmountBDT: s.dueAmountBDT,
            remainingAmountBDT: 0,
            status: 'Paid' as const,
            paymentDate: today,
            overdueDays: 0,
          };
        }
        return s;
      });

      const updatedPlan: InstallmentPlan = {
        ...plan,
        status: 'Settled',
        totalPaidBDT: plan.totalProductPriceBDT,
        totalOutstandingBDT: 0,
        paidInstallmentsCount: planSchedules.length,
        remainingInstallmentsCount: 0,
        overdueInstallmentsCount: 0,
        overdueAmountBDT: 0,
        remarks: `${plan.remarks || ''} [Early Settlement completed with ${settlementData.rebatePercent}% rebate of ৳${calc.rebateAmountBDT.toLocaleString()} on ${today}]`.trim(),
        updatedAt: today,
      };

      const sb = getSupabase();
      if (sb) {
        const { error: planSettleErr } = await sb
          .from('installment_plans')
          .update({
            status: updatedPlan.status,
            total_paid_bdt: updatedPlan.totalPaidBDT,
            total_outstanding_bdt: updatedPlan.totalOutstandingBDT,
            paid_installments_count: updatedPlan.paidInstallmentsCount,
            remaining_installments_count: updatedPlan.remainingInstallmentsCount,
            overdue_installments_count: 0,
            overdue_amount_bdt: 0,
            remarks: updatedPlan.remarks,
            updated_at: new Date().toISOString(),
          })
          .eq('id', planId);

        if (planSettleErr) {
          return { success: false, error: `Failed to settle plan in database: ${planSettleErr.message}` };
        }

        const newlyPaidSchedules = updatedSchedules.filter((s) => s.planId === planId && s.paymentDate === today);
        for (const s of newlyPaidSchedules) {
          await sb
            .from('installment_schedules')
            .update({
              paid_amount_bdt: s.paidAmountBDT,
              remaining_amount_bdt: 0,
              status: 'Paid',
              payment_date: today,
              overdue_days: 0,
            })
            .eq('id', s.id);
        }
      }

      setInstallmentSchedules(updatedSchedules);
      setInstallmentPlans((prev) => prev.map((p) => (p.id === planId ? updatedPlan : p)));

      // Mark linked Sales Order as fully paid / zero due on early settlement
      await syncInstallmentPaymentToSalesOrder(plan, calc.settlementNetPayableBDT, {
        markFullySettled: true,
      });

      // Post Settlement Cash Inflow to Cash Book
      const lastCash = cashBook[cashBook.length - 1];
      const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
      const cashEntry: CashBookEntry = {
        id: `cash-stl-${Date.now()}`,
        date: today,
        voucherNo: receiptNo,
        accountType: settlementData.bankAccountName || 'Eastern Bank PLC (Current A/C)',
        transactionCategory: 'Installment Collection',
        description: `Early Settlement for Agreement ${plan.agreementNo} (${plan.customerName}) - Net: ৳${calc.settlementNetPayableBDT.toLocaleString()} (Rebate: ৳${calc.rebateAmountBDT.toLocaleString()})`,
        reference: receiptNo,
        cashInBDT: calc.settlementNetPayableBDT,
        cashOutBDT: 0,
        runningBalanceBDT: prevBal + calc.settlementNetPayableBDT,
      };
      setCashBook((prev) => [...prev, cashEntry]);

      addAuditLog(
        'INSTALLMENT_EARLY_SETTLEMENT',
        'Installment & Receivables',
        `Completed early settlement for Agreement ${plan.agreementNo}. Net received: ৳${calc.settlementNetPayableBDT.toLocaleString()}, Rebate discount: ৳${calc.rebateAmountBDT.toLocaleString()}`
      );

      return { success: true };
    } catch (err: any) {
      return { success: false, error: err?.message || 'Failed early settlement' };
    }
  };

  const addCollectionFollowUp = async (
    followUpData: Omit<CollectionFollowUp, 'id' | 'createdAt'>
  ): Promise<{ success: boolean; id: string }> => {
    const id = `FLP-${Date.now().toString().slice(-6)}`;
    const newFollowUp: CollectionFollowUp = {
      ...followUpData,
      id,
      createdAt: new Date().toISOString(),
    };

    setCollectionFollowUps((prev) => [newFollowUp, ...prev]);

    const sb = getSupabase();
    if (sb) {
      sb.from('collection_followups')
        .insert({
          id: newFollowUp.id,
          plan_id: newFollowUp.planId,
          agreement_no: newFollowUp.agreementNo,
          customer_id: newFollowUp.customerId || null,
          customer_name: newFollowUp.customerName,
          contact_person: newFollowUp.contactPerson,
          contact_phone: newFollowUp.contactPhone,
          activity_type: newFollowUp.activityType,
          follow_up_date: newFollowUp.followUpDate,
          next_follow_up_date: newFollowUp.nextFollowUpDate || null,
          committed_amount_bdt: newFollowUp.committedAmountBDT ?? null,
          committed_payment_date: newFollowUp.committedPaymentDate || null,
          notes: newFollowUp.notes,
          performed_by_id: newFollowUp.performedById,
          performed_by_name: newFollowUp.performedByName,
          status: newFollowUp.status,
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase collection_followups insert notice:', error.message);
        });
    }

    // Update assignment target date and status if committed
    if (newFollowUp.committedPaymentDate) {
      setCollectionAssignments((prev) =>
        prev.map((a) =>
          a.planId === newFollowUp.planId
            ? {
                ...a,
                targetDate: newFollowUp.committedPaymentDate!,
                priority: 'High',
              }
            : a
        )
      );
      if (sb) {
        sb.from('collection_assignments')
          .update({
            target_date: newFollowUp.committedPaymentDate,
            priority: 'High',
          })
          .eq('plan_id', newFollowUp.planId)
          .then(({ error }) => {
            if (error) console.warn('Supabase collection_assignments update notice:', error.message);
          });
      }
    }

    addAuditLog(
      'COLLECTION_FOLLOWUP_LOGGED',
      'Collection Management',
      `Logged ${newFollowUp.activityType} for ${newFollowUp.customerName} (${newFollowUp.agreementNo}). Next follow-up: ${newFollowUp.nextFollowUpDate || 'None'}`
    );

    return { success: true, id };
  };

  const updateCollectionAssignment = (assignmentId: string, updates: Partial<CollectionAssignment>) => {
    setCollectionAssignments((prev) =>
      prev.map((a) => (a.id === assignmentId ? { ...a, ...updates } : a))
    );
    const sb = getSupabase();
    if (sb) {
      const dbPatch: Record<string, any> = { updated_at: new Date().toISOString() };
      if (updates.assignedToId !== undefined) dbPatch.assigned_to_id = updates.assignedToId;
      if (updates.assignedToName !== undefined) dbPatch.assigned_to_name = updates.assignedToName;
      if (updates.assignedToRole !== undefined) dbPatch.assigned_to_role = updates.assignedToRole;
      if (updates.targetDate !== undefined) dbPatch.target_date = updates.targetDate;
      if (updates.targetAmountBDT !== undefined) dbPatch.target_amount_bdt = updates.targetAmountBDT;
      if (updates.escalationLevel !== undefined) dbPatch.escalation_level = updates.escalationLevel;
      if (updates.status !== undefined) dbPatch.status = updates.status;
      if (updates.priority !== undefined) dbPatch.priority = updates.priority;
      sb.from('collection_assignments')
        .update(dbPatch)
        .eq('id', assignmentId)
        .then(({ error }) => {
          if (error) console.warn('Supabase collection_assignments update notice:', error.message);
        });
    }
    addAuditLog('COLLECTION_ASSIGNMENT_UPDATED', 'Collection Management', `Updated assignment ID ${assignmentId}`);
  };

  const createCollectionAssignment = (assignment: Omit<CollectionAssignment, 'id'>): string => {
    const id = `ASN-${Date.now().toString().slice(-5)}`;
    const newAssign: CollectionAssignment = { ...assignment, id };
    setCollectionAssignments((prev) => [newAssign, ...prev]);
    const sb = getSupabase();
    if (sb) {
      sb.from('collection_assignments')
        .insert({
          id: newAssign.id,
          plan_id: newAssign.planId,
          agreement_no: newAssign.agreementNo,
          customer_id: newAssign.customerId || null,
          customer_name: newAssign.customerName,
          assigned_to_id: newAssign.assignedToId,
          assigned_to_name: newAssign.assignedToName,
          assigned_to_role: newAssign.assignedToRole,
          assigned_by_id: newAssign.assignedById || null,
          assigned_by_name: newAssign.assignedByName || null,
          assignment_date: newAssign.assignmentDate,
          target_date: newAssign.targetDate,
          target_amount_bdt: newAssign.targetAmountBDT,
          escalation_level: newAssign.escalationLevel,
          status: newAssign.status,
          priority: newAssign.priority,
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase collection_assignments insert notice:', error.message);
        });
    }
    addAuditLog('COLLECTION_ASSIGNMENT_CREATED', 'Collection Management', `Assigned ${newAssign.customerName} to ${newAssign.assignedToName}`);
    return id;
  };

  const updateSMSTemplate = (templateId: string, updates: Partial<SMSTemplate>) => {
    setSmsTemplates((prev) =>
      prev.map((t) => (t.id === templateId ? { ...t, ...updates, updatedAt: new Date().toISOString().slice(0, 10) } : t))
    );
    addAuditLog('SMS_TEMPLATE_UPDATED', 'SMS & Notification', `Updated SMS template ${templateId}`);
  };

  const toggleSMSAutomationRule = (ruleId: string) => {
    setSmsAutomationRules((prev) =>
      prev.map((r) => (r.id === ruleId ? { ...r, enabled: !r.enabled } : r))
    );
    addAuditLog('SMS_RULE_TOGGLED', 'SMS & Notification', `Toggled rule ID ${ruleId}`);
  };

  const updateSMSGatewaySettings = (settings: Partial<SMSGatewaySettings>) => {
    setSmsGatewaySettings((prev) => ({
      ...prev,
      ...settings,
      isConfigured: Boolean(settings.apiKey ? settings.apiKey.trim().length > 0 : prev.apiKey.trim().length > 0),
    }));
    addAuditLog('SMS_GATEWAY_CONFIGURED', 'SMS & Notification', `Updated SMS gateway credentials and endpoint`);
  };

  const testSMSGateway = async (phone: string, message: string): Promise<{ success: boolean; message: string }> => {
    const result = await sendSMSViaGateway({
      recipientPhone: phone,
      recipientName: 'Test Recipient',
      message,
      gatewaySettings: smsGatewaySettings,
    });

    setSmsLogs((prev) => [result.log, ...prev]);

    setSmsGatewaySettings((prev) => ({
      ...prev,
      lastTestedAt: new Date().toISOString().slice(0, 19).replace('T', ' '),
      testStatus: result.success ? 'Success' : 'Failed',
    }));

    return {
      success: result.success,
      message: result.gatewayResponse,
    };
  };

  const runAutomationCheckNow = async (): Promise<AutomationExecutionReport> => {
    const result = await runAutomatedInstallmentCheck({
      plans: installmentPlans,
      schedules: installmentSchedules,
      rules: smsAutomationRules,
      templates: smsTemplates,
      gatewaySettings: smsGatewaySettings,
      escalationRules: collectionEscalationRules,
      assignments: collectionAssignments,
      existingLogs: smsLogs,
    });

    setInstallmentPlans(result.updatedPlans);
    setInstallmentSchedules(result.updatedSchedules);
    if (result.newLogs.length > 0) {
      setSmsLogs((prev) => [...result.newLogs, ...prev]);
    }
    if (result.newNotifications.length > 0) {
      setInstallmentNotifications((prev) => [...result.newNotifications, ...prev]);
    }
    setCollectionAssignments(result.updatedAssignments);

    addAuditLog(
      'INSTALLMENT_AUTOMATION_EXECUTED',
      'System Automation',
      `Executed scheduled check: ${result.report.schedulesUpdated} schedules refreshed, ${result.report.smsSentCount} SMS dispatched.`
    );

    return result.report;
  };

  const markNotificationAsRead = (id: string) => {
    setInstallmentNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, isRead: true } : n))
    );
    const sb = getSupabase();
    if (sb) {
      sb.from('installment_notifications').update({ is_read: true }).eq('id', id).then(() => {});
    }
  };

  const markAllNotificationsAsRead = () => {
    setInstallmentNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));
    const sb = getSupabase();
    if (sb) {
      sb.from('installment_notifications').update({ is_read: true }).eq('is_read', false).then(() => {});
    }
  };

  const deleteInstallmentPlan = (planId: string) => {
    setInstallmentPlans((prev) => prev.filter((p) => p.id !== planId));
    setInstallmentSchedules((prev) => prev.filter((s) => s.planId !== planId));
    setCollectionAssignments((prev) => prev.filter((a) => a.planId !== planId));
    const sb = getSupabase();
    if (sb) {
      sb.from('installment_plans')
        .delete()
        .eq('id', planId)
        .then(({ error }) => {
          if (error) console.warn('Supabase installment_plans delete notice:', error.message);
        });
    }
    addAuditLog('INSTALLMENT_PLAN_DELETED', 'Installment & Receivables', `Deleted plan ID ${planId}`);
  };

  const clearInstallmentData = () => {
    setInstallmentPlans([]);
    setInstallmentSchedules([]);
    setInstallmentPayments([]);
    setCollectionAssignments([]);
    setCollectionFollowUps([]);
    setSmsLogs([]);
    setInstallmentNotifications([]);

    if (typeof window !== 'undefined') {
      try {
        localStorage.removeItem('ensec_installment_plans');
        localStorage.removeItem('ensec_installment_schedules');
        localStorage.removeItem('ensec_installment_payments');
        localStorage.removeItem('ensec_collection_assignments');
        localStorage.removeItem('ensec_collection_followups');
        localStorage.removeItem('ensec_sms_logs');
        localStorage.removeItem('ensec_installment_notifications');
        try {
          sessionStorage.removeItem('ensec_installment_plans');
          sessionStorage.removeItem('ensec_installment_schedules');
          sessionStorage.removeItem('ensec_installment_payments');
        } catch {}
        localStorage.setItem('ensec_installment_test_purged_v2', 'true');
      } catch (e) {
        console.warn('Error clearing installment storage:', e);
      }
    }
    addAuditLog(
      'INSTALLMENT_DATA_CLEARED',
      'Installment & Receivables',
      'Cleared test and local session memory data from Installment Management'
    );
  };

  // ==========================================
  // CENTRAL PAYROLL MANAGEMENT FUNCTIONS
  // ==========================================

  const persistSalaryStructureToSupabase = async (
    record: EmployeeSalaryStructure
  ): Promise<{
    dbSynced: boolean;
    error?: string;
    sqlFix?: string;
    dbStatus: SalaryStructuresDbStatus;
  }> => {
    const sb = getSupabase();
    if (!sb) {
      const notConfigured: SalaryStructuresDbStatus = {
        synced: false,
        status: 'not_configured',
        error: 'Supabase client is not configured.',
        sqlFix: null,
      };
      setSalaryStructuresDbStatus(notConfigured);
      return { dbSynced: false, error: notConfigured.error || undefined, dbStatus: notConfigured };
    }

    const matchedRep = fieldForceReps.find(
      (r) =>
        r.id === record.employeeId ||
        r.id === record.fieldForceId ||
        (record.employeeCode && r.code === record.employeeCode)
    );

    const effectiveEmployeeId = String(record.employeeId || record.fieldForceId || matchedRep?.id || '');
    const effectiveEmployeeCode = String(record.employeeCode || matchedRep?.code || effectiveEmployeeId || 'EMP');
    const effectiveEmployeeName = String(record.employeeName || matchedRep?.name || 'Employee');
    const effectiveFrom =
      record.effectiveFrom && /^\d{4}-\d{2}-\d{2}/.test(record.effectiveFrom)
        ? record.effectiveFrom.slice(0, 10)
        : new Date().toISOString().slice(0, 10);

    // Keep linked employee basic/conveyance/mobile columns aligned on field_force_reps
    if (matchedRep) {
      updateFieldForceRep(matchedRep.id, {
        basicSalaryBDT: Number(record.basicSalaryBDT) || 0,
        conveyanceBDT: Number(record.conveyanceAllowanceBDT) || 0,
        mobileAllowanceBDT: Number(record.mobileAllowanceBDT) || 0,
      });
    }

    const upsertPayload: Record<string, any> = {
      id: String(record.id),
      employee_id: effectiveEmployeeId,
      employee_code: effectiveEmployeeCode,
      employee_name: effectiveEmployeeName,
      basic_salary_bdt: Number(record.basicSalaryBDT) || 0,
      house_rent_bdt: Number(record.houseRentBDT) || 0,
      medical_allowance_bdt: Number(record.medicalAllowanceBDT) || 0,
      conveyance_allowance_bdt: Number(record.conveyanceAllowanceBDT) || 0,
      mobile_allowance_bdt: Number(record.mobileAllowanceBDT) || 0,
      special_allowance_bdt: Number(record.specialAllowanceBDT) || 0,
      other_allowances_bdt: Number(record.otherAllowancesBDT) || 0,
      gross_salary_bdt: Number(record.grossSalaryBDT) || 0,
      effective_from: effectiveFrom,
      history_json: Array.isArray(record.history) ? record.history : [],
      updated_at: new Date().toISOString(),
    };

    try {
      let lastError: any = null;
      const workingPayload: Record<string, any> = { ...upsertPayload };

      for (let attempt = 0; attempt < 10; attempt++) {
        const { error } = await sb
          .from('employee_salary_structures')
          .upsert(workingPayload, { onConflict: 'id' });

        if (!error) {
          const okStatus: SalaryStructuresDbStatus = {
            synced: true,
            status: 'synced',
            error: null,
            sqlFix: null,
          };
          setSalaryStructuresDbStatus(okStatus);
          return { dbSynced: true, dbStatus: okStatus };
        }

        lastError = error;
        const msg = String(error.message || '');
        let missingCol: string | null = null;
        if (error.code === 'PGRST204' || msg.includes('schema cache')) {
          missingCol = msg.match(/Could not find the '([^']+)' column/i)?.[1] || null;
        } else if (error.code === '42703' || msg.toLowerCase().includes('does not exist')) {
          missingCol =
            msg.match(/column\s+"([^"]+)"/i)?.[1] ||
            msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1] ||
            null;
        }
        if (missingCol && Object.prototype.hasOwnProperty.call(workingPayload, missingCol)) {
          delete workingPayload[missingCol];
          continue;
        }
        break;
      }

      const failStatus = classifySalaryStructuresSupabaseError(lastError);
      setSalaryStructuresDbStatus(failStatus);
      console.error('[SalaryStructure] Supabase save failed:', lastError);
      return {
        dbSynced: false,
        error: failStatus.error || lastError?.message || 'Failed to save salary structure to Supabase.',
        sqlFix: failStatus.sqlFix || SALARY_STRUCTURES_TABLE_SQL,
        dbStatus: failStatus,
      };
    } catch (err: any) {
      const failStatus = classifySalaryStructuresSupabaseError(err);
      setSalaryStructuresDbStatus(failStatus);
      console.error('[SalaryStructure] Supabase save exception:', err);
      return {
        dbSynced: false,
        error: failStatus.error || err?.message || 'Network error while saving salary structure.',
        sqlFix: failStatus.sqlFix || SALARY_STRUCTURES_TABLE_SQL,
        dbStatus: failStatus,
      };
    }
  };

  const addSalaryStructure = async (
    structure: Omit<EmployeeSalaryStructure, 'id' | 'createdAt' | 'updatedAt'>
  ): Promise<{
    success: boolean;
    id: string;
    dbSynced: boolean;
    error?: string;
    sqlFix?: string;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'edit_salary_structure')) {
      console.warn('Permission denied: edit_salary_structure required to create salary structure.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to create salary structure without edit_salary_structure permission`);
      return {
        success: false,
        id: '',
        dbSynced: false,
        error: 'Permission denied: "Edit Salary Structure" permission is required to modify salary structures.',
      };
    }
    const empKey = String(structure.employeeId || structure.fieldForceId || '').trim();
    const existing = salaryStructures.find(
      (s) =>
        (empKey && (s.employeeId === empKey || s.fieldForceId === empKey)) ||
        (structure.employeeCode && s.employeeCode === structure.employeeCode)
    );
    const id = existing?.id || `sal-str-${empKey || Date.now().toString().slice(-6)}`;
    const now = new Date().toISOString().slice(0, 10);
    const prevHistory = existing?.history || [];
    const newEntry = {
      effectiveDate: structure.effectiveFrom || now,
      grossSalaryBDT: structure.grossSalaryBDT,
      basicSalaryBDT: structure.basicSalaryBDT,
      reason: structure.revisionReason || (existing ? 'Salary Structure Revision' : 'Initial Structure Creation'),
      changedBy: structure.revisedBy || currentUser?.name || 'HR Admin',
      changedAt: now,
    };

    const newStr: EmployeeSalaryStructure = {
      ...structure,
      id,
      employeeId: empKey || existing?.employeeId,
      fieldForceId: empKey || existing?.fieldForceId,
      createdAt: existing?.createdAt || now,
      updatedAt: now,
      history: [...prevHistory, newEntry],
    };

    setSalaryStructures((prev) => [
      newStr,
      ...prev.filter(
        (s) =>
          s.id !== id &&
          !(empKey && (s.employeeId === empKey || s.fieldForceId === empKey))
      ),
    ]);

    addAuditLog(
      'SALARY_STRUCTURE_SET',
      'HR & Payroll',
      `Configured salary structure for employee ${structure.employeeName} (${structure.employeeCode}) - Gross: ৳${structure.grossSalaryBDT.toLocaleString()}`
    );

    const syncRes = await persistSalaryStructureToSupabase(newStr);
    return {
      success: true,
      id,
      dbSynced: syncRes.dbSynced,
      error: syncRes.error,
      sqlFix: syncRes.sqlFix,
    };
  };

  const updateSalaryStructure = async (
    id: string,
    updates: Partial<EmployeeSalaryStructure>,
    reason?: string
  ): Promise<{
    success: boolean;
    id: string;
    dbSynced: boolean;
    error?: string;
    sqlFix?: string;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'edit_salary_structure')) {
      console.warn('Permission denied: edit_salary_structure required to update salary structure.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to update salary structure (${id}) without edit_salary_structure permission`);
      return {
        success: false,
        id: id || '',
        dbSynced: false,
        error: 'Permission denied: "Edit Salary Structure" permission is required to modify salary structures.',
      };
    }
    const now = new Date().toISOString().slice(0, 10);
    const existing = salaryStructures.find(
      (s) =>
        s.id === id ||
        (updates.employeeId && (s.employeeId === updates.employeeId || s.fieldForceId === updates.employeeId))
    );

    if (!existing) {
      return addSalaryStructure({
        employeeId: updates.employeeId || updates.fieldForceId,
        fieldForceId: updates.fieldForceId || updates.employeeId,
        employeeCode: updates.employeeCode || '',
        employeeName: updates.employeeName || 'Employee',
        designation: updates.designation || 'Staff',
        department: updates.department || 'Operations',
        employeeCategory: updates.employeeCategory,
        effectiveFrom: updates.effectiveFrom || now,
        basicSalaryBDT: updates.basicSalaryBDT ?? 0,
        houseRentBDT: updates.houseRentBDT ?? 0,
        medicalAllowanceBDT: updates.medicalAllowanceBDT ?? 0,
        conveyanceAllowanceBDT: updates.conveyanceAllowanceBDT ?? 0,
        mobileAllowanceBDT: updates.mobileAllowanceBDT ?? 0,
        specialAllowanceBDT: updates.specialAllowanceBDT ?? 0,
        otherAllowancesBDT: updates.otherAllowancesBDT ?? 0,
        grossSalaryBDT: updates.grossSalaryBDT ?? 0,
        revisionReason: reason || updates.revisionReason || 'Salary Structure Revision',
        revisedBy: updates.revisedBy || currentUser?.name || 'HR Admin',
      });
    }

    const history = [...(existing.history || [])];
    const hasMonetaryChange =
      updates.grossSalaryBDT !== existing.grossSalaryBDT ||
      updates.basicSalaryBDT !== existing.basicSalaryBDT ||
      updates.houseRentBDT !== existing.houseRentBDT ||
      updates.medicalAllowanceBDT !== existing.medicalAllowanceBDT ||
      updates.conveyanceAllowanceBDT !== existing.conveyanceAllowanceBDT ||
      updates.mobileAllowanceBDT !== existing.mobileAllowanceBDT ||
      updates.specialAllowanceBDT !== existing.specialAllowanceBDT ||
      updates.otherAllowancesBDT !== existing.otherAllowancesBDT;

    if (hasMonetaryChange || (reason && reason.trim() && reason.trim() !== 'Salary Structure Revision')) {
      history.push({
        effectiveDate: updates.effectiveFrom || existing.effectiveFrom || now,
        grossSalaryBDT: updates.grossSalaryBDT ?? existing.grossSalaryBDT,
        basicSalaryBDT: updates.basicSalaryBDT ?? existing.basicSalaryBDT,
        reason: reason || updates.revisionReason || 'Salary Revision / Increment',
        changedBy: updates.revisedBy || currentUser?.name || 'HR Admin',
        changedAt: now,
      });
    }

    const updatedRecord: EmployeeSalaryStructure = {
      ...existing,
      ...updates,
      id: existing.id,
      updatedAt: now,
      history,
    };

    setSalaryStructures((prev) =>
      prev.map((s) => (s.id === existing.id ? updatedRecord : s))
    );

    addAuditLog(
      'SALARY_STRUCTURE_UPDATED',
      'HR & Payroll',
      `Updated salary structure for ${updatedRecord.employeeName} (${updatedRecord.employeeCode || existing.id}) - Gross: ৳${(updatedRecord.grossSalaryBDT || 0).toLocaleString()}`
    );

    const syncRes = await persistSalaryStructureToSupabase(updatedRecord);
    return {
      success: true,
      id: existing.id,
      dbSynced: syncRes.dbSynced,
      error: syncRes.error,
      sqlFix: syncRes.sqlFix,
    };
  };

  const syncSalaryStructuresToSupabase = async (): Promise<{
    success: boolean;
    syncedCount: number;
    error?: string;
    sqlFix?: string;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'edit_salary_structure')) {
      console.warn('Permission denied: edit_salary_structure required to sync salary structures.');
      return {
        success: false,
        syncedCount: 0,
        error: 'Permission denied: "Edit Salary Structure" permission is required to sync salary structures.',
      };
    }
    const recordsToSync = salaryStructures.filter((s) => {
      const empId = s.employeeId || s.fieldForceId;
      if (!empId) return false;
      return !String(s.id).startsWith('str-ff-') || fieldForceReps.some((r) => r.id === empId);
    });

    if (recordsToSync.length === 0) {
      // Probe table write/select access even when 0 edited records exist
      const sb = getSupabase();
      if (!sb) {
        return { success: false, syncedCount: 0, error: 'Supabase client is not configured.' };
      }
      const { error } = await sb.from('employee_salary_structures').select('id').limit(1);
      if (error) {
        const failStatus = classifySalaryStructuresSupabaseError(error);
        setSalaryStructuresDbStatus(failStatus);
        return {
          success: false,
          syncedCount: 0,
          error: failStatus.error || error.message,
          sqlFix: failStatus.sqlFix || SALARY_STRUCTURES_TABLE_SQL,
        };
      }
      setSalaryStructuresDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
      return { success: true, syncedCount: 0 };
    }

    let syncedCount = 0;
    for (const rec of recordsToSync) {
      const res = await persistSalaryStructureToSupabase(rec);
      if (!res.dbSynced) {
        return {
          success: false,
          syncedCount,
          error: res.error,
          sqlFix: res.sqlFix,
        };
      }
      syncedCount++;
    }

    return { success: true, syncedCount };
  };

  const getEmployeeSalaryStructure = (employeeId: string): EmployeeSalaryStructure | undefined => {
    return salaryStructures.find(
      (s) => s.employeeId === employeeId || s.fieldForceId === employeeId
    );
  };

  const formatOfficeLocationSupabaseError = (error: any): string => {
    const rawMsg = String(error?.message || 'Unknown Supabase error');
    const code = String(error?.code || '');
    if (code === '23505' || rawMsg.toLowerCase().includes('duplicate key')) {
      return 'An office location with this Office Code already exists in Supabase. Please use a unique Office Code.';
    }
    if (code === '42P01' || rawMsg.includes('relation "public.office_locations" does not exist') || rawMsg.includes('office_locations')) {
      return 'Supabase table "office_locations" does not exist yet. Please run the Office Locations SQL script from supabase_schema.sql.';
    }
    if (code === '42501' || rawMsg.toLowerCase().includes('row-level security') || rawMsg.toLowerCase().includes('permission denied')) {
      return `Supabase RLS/permission blocked saving office_locations: ${rawMsg}`;
    }
    return `Failed to save office location to Supabase: ${rawMsg}`;
  };

  const addOfficeLocation = async (
    locData: Omit<OfficeLocation, 'id'>
  ): Promise<{ success: boolean; id: string; error?: string }> => {
    const normalizedName = (locData.name || '').trim();
    const normalizedCode = locData.code ? locData.code.trim() : undefined;
    const normalizedAddress = (locData.address || '').trim();
    const lat = Number(locData.latitude);
    const lng = Number(locData.longitude);

    if (!normalizedName || !Number.isFinite(lat) || !Number.isFinite(lng)) {
      return {
        success: false,
        id: '',
        error: 'Valid office name, latitude, and longitude are required.',
      };
    }

    if (
      normalizedCode &&
      officeLocations.some(
        (loc) => (loc.code || '').trim().toLowerCase() === normalizedCode.toLowerCase()
      )
    ) {
      return {
        success: false,
        id: '',
        error: `Office Code "${normalizedCode}" is already assigned to another office location.`,
      };
    }

    const id = `office-${Date.now().toString().slice(-6)}-${Math.random().toString(36).slice(2, 5)}`;
    const nowIso = new Date().toISOString();
    const newLoc: OfficeLocation = {
      ...locData,
      id,
      code: normalizedCode,
      name: normalizedName,
      address: normalizedAddress,
      latitude: lat,
      longitude: lng,
      allowedRadiusMeters:
        Number(locData.allowedRadiusMeters) > 0
          ? Math.round(Number(locData.allowedRadiusMeters))
          : DEFAULT_ALLOWED_RADIUS_METERS,
      status: locData.status === 'Inactive' ? 'Inactive' : 'Active',
      createdAt: nowIso,
      updatedAt: nowIso,
    };

    const prevLocations = officeLocations;
    setOfficeLocations((prev) => [newLoc, ...prev]);

    const sb = getSupabase();
    if (sb) {
      try {
        const { data, error } = await sb
          .from('office_locations')
          .upsert(
            {
              id: newLoc.id,
              code: newLoc.code || null,
              name: newLoc.name,
              address: newLoc.address,
              latitude: newLoc.latitude,
              longitude: newLoc.longitude,
              allowed_radius_meters: newLoc.allowedRadiusMeters,
              status: newLoc.status,
              created_at: nowIso,
              updated_at: nowIso,
            },
            { onConflict: 'id' }
          )
          .select();

        if (error) {
          console.error('Supabase office_locations insert failed:', error);
          setOfficeLocations(prevLocations);
          return {
            success: false,
            id,
            error: formatOfficeLocationSupabaseError(error),
          };
        }

        if (typeof window !== 'undefined') {
          localStorage.setItem('ensec_office_locations_seeded_v1', 'true');
        }

        if (Array.isArray(data) && data[0]) {
          const confirmed = data[0];
          const confirmedLoc: OfficeLocation = {
            id: String(confirmed.id),
            code: confirmed.code || undefined,
            name: confirmed.name || newLoc.name,
            address: confirmed.address ?? newLoc.address,
            latitude: Number(confirmed.latitude),
            longitude: Number(confirmed.longitude),
            allowedRadiusMeters:
              Number(confirmed.allowed_radius_meters) || newLoc.allowedRadiusMeters,
            status: confirmed.status === 'Inactive' ? 'Inactive' : 'Active',
            createdAt: confirmed.created_at || nowIso,
            updatedAt: confirmed.updated_at || nowIso,
          };
          setOfficeLocations((prev) =>
            prev.map((loc) => (loc.id === newLoc.id ? confirmedLoc : loc))
          );
        }
      } catch (err: any) {
        console.error('Exception saving office location to Supabase:', err);
        setOfficeLocations(prevLocations);
        return {
          success: false,
          id,
          error: err?.message || 'Database connection error while saving office location.',
        };
      }
    }

    addAuditLog(
      'OFFICE_LOCATION_CREATED',
      'Field Force Master',
      `Created office geofence ${newLoc.name} (${newLoc.latitude}, ${newLoc.longitude}, ${newLoc.allowedRadiusMeters}m)`
    );

    try {
      await fetch('/api/office-locations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...newLoc, skipSupabaseSync: Boolean(sb) }),
      });
    } catch {}

    return { success: true, id };
  };

  const updateOfficeLocation = async (
    id: string,
    updates: Partial<OfficeLocation>
  ): Promise<{ success: boolean; error?: string }> => {
    const nowIso = new Date().toISOString();
    const existingOffice = officeLocations.find((loc) => loc.id === id);
    if (!existingOffice && !updates.name) {
      return { success: false, error: 'Office location record not found.' };
    }

    const normalizedCode =
      updates.code !== undefined
        ? updates.code?.trim() || undefined
        : existingOffice?.code?.trim() || undefined;
    const normalizedName = (updates.name ?? existingOffice?.name ?? 'Office Location').trim();
    const normalizedAddress = (updates.address ?? existingOffice?.address ?? '').trim();
    const lat =
      updates.latitude !== undefined
        ? Number(updates.latitude)
        : Number(existingOffice?.latitude);
    const lng =
      updates.longitude !== undefined
        ? Number(updates.longitude)
        : Number(existingOffice?.longitude);
    const radius =
      Number(updates.allowedRadiusMeters ?? existingOffice?.allowedRadiusMeters) > 0
        ? Math.round(Number(updates.allowedRadiusMeters ?? existingOffice?.allowedRadiusMeters))
        : DEFAULT_ALLOWED_RADIUS_METERS;
    const status =
      (updates.status ?? existingOffice?.status) === 'Inactive' ? 'Inactive' : 'Active';

    if (!normalizedName || !Number.isFinite(lat) || !Number.isFinite(lng)) {
      return {
        success: false,
        error: 'Valid office name, latitude, and longitude are required.',
      };
    }

    if (
      normalizedCode &&
      officeLocations.some(
        (loc) =>
          loc.id !== id &&
          (loc.code || '').trim().toLowerCase() === normalizedCode.toLowerCase()
      )
    ) {
      return {
        success: false,
        error: `Office Code "${normalizedCode}" is already assigned to another office location.`,
      };
    }

    const mergedOffice: OfficeLocation = {
      ...(existingOffice || { id }),
      ...updates,
      id,
      code: normalizedCode,
      name: normalizedName,
      address: normalizedAddress,
      latitude: lat,
      longitude: lng,
      allowedRadiusMeters: radius,
      status,
      createdAt: existingOffice?.createdAt || nowIso,
      updatedAt: nowIso,
    };

    const prevLocations = officeLocations;
    const prevUsers = users;

    setOfficeLocations((prev) =>
      prev.some((loc) => loc.id === id)
        ? prev.map((loc) => (loc.id === id ? mergedOffice : loc))
        : [mergedOffice, ...prev]
    );

    // Cascade coordinate/radius updates to User records assigned to this office ID
    setUsers((prev) =>
      prev.map((u) => {
        if (u.assignedOfficeId === id) {
          const updatedUser: User = {
            ...u,
            assignedOfficeName: mergedOffice.name,
            officeLatitude: mergedOffice.latitude,
            officeLongitude: mergedOffice.longitude,
            allowedRadiusMeters: mergedOffice.allowedRadiusMeters,
            officeAddress: mergedOffice.address,
            locationStatus: mergedOffice.status,
          };
          if (currentUser.id === u.id) {
            setCurrentUser(updatedUser);
          }
          return updatedUser;
        }
        return u;
      })
    );

    const sb = getSupabase();
    if (sb) {
      try {
        const { data, error } = await sb
          .from('office_locations')
          .upsert(
            {
              id: mergedOffice.id,
              code: mergedOffice.code || null,
              name: mergedOffice.name,
              address: mergedOffice.address,
              latitude: mergedOffice.latitude,
              longitude: mergedOffice.longitude,
              allowed_radius_meters: mergedOffice.allowedRadiusMeters,
              status: mergedOffice.status,
              updated_at: nowIso,
            },
            { onConflict: 'id' }
          )
          .select();

        if (error) {
          console.error('Supabase office_locations update failed:', error);
          setOfficeLocations(prevLocations);
          setUsers(prevUsers);
          return {
            success: false,
            error: formatOfficeLocationSupabaseError(error),
          };
        }

        if (typeof window !== 'undefined') {
          localStorage.setItem('ensec_office_locations_seeded_v1', 'true');
        }

        if (Array.isArray(data) && data[0]) {
          const confirmed = data[0];
          const confirmedLoc: OfficeLocation = {
            id: String(confirmed.id),
            code: confirmed.code || undefined,
            name: confirmed.name || mergedOffice.name,
            address: confirmed.address ?? mergedOffice.address,
            latitude: Number(confirmed.latitude),
            longitude: Number(confirmed.longitude),
            allowedRadiusMeters:
              Number(confirmed.allowed_radius_meters) || mergedOffice.allowedRadiusMeters,
            status: confirmed.status === 'Inactive' ? 'Inactive' : 'Active',
            createdAt: confirmed.created_at || mergedOffice.createdAt,
            updatedAt: confirmed.updated_at || nowIso,
          };
          setOfficeLocations((prev) =>
            prev.map((loc) => (loc.id === id ? confirmedLoc : loc))
          );
        }

        // Persist cascaded office coordinate/name/radius updates to assigned users in Supabase
        const hasAssignedUsers = prevUsers.some((u) => u.assignedOfficeId === id);
        if (hasAssignedUsers) {
          sb.from('users')
            .update({
              assigned_office_name: mergedOffice.name,
              office_latitude: mergedOffice.latitude,
              office_longitude: mergedOffice.longitude,
              allowed_radius_meters: mergedOffice.allowedRadiusMeters,
              office_address: mergedOffice.address,
              location_status: mergedOffice.status,
            })
            .eq('assigned_office_id', id)
            .then(({ error: userErr }) => {
              if (userErr && userErr.code !== '42703') {
                console.warn('Notice syncing updated office coordinates to users:', userErr.message);
              }
            });
        }
      } catch (err: any) {
        console.error('Exception updating office location in Supabase:', err);
        setOfficeLocations(prevLocations);
        setUsers(prevUsers);
        return {
          success: false,
          error: err?.message || 'Database connection error while updating office location.',
        };
      }
    }

    addAuditLog('OFFICE_LOCATION_UPDATED', 'Field Force Master', `Updated office geofence ID ${id}`);

    try {
      await fetch(`/api/office-locations/${encodeURIComponent(id)}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...mergedOffice, skipSupabaseSync: Boolean(sb) }),
      });
    } catch {}

    return { success: true };
  };

  const deleteOfficeLocation = async (id: string): Promise<{ success: boolean; error?: string }> => {
    const prevLocations = officeLocations;
    setOfficeLocations((prev) => prev.filter((loc) => loc.id !== id));

    const sb = getSupabase();
    if (sb) {
      try {
        const { error } = await sb.from('office_locations').delete().eq('id', id);
        if (error) {
          console.error('Supabase office_locations delete failed:', error);
          setOfficeLocations(prevLocations);
          return {
            success: false,
            error: formatOfficeLocationSupabaseError(error),
          };
        }
        if (typeof window !== 'undefined') {
          localStorage.setItem('ensec_office_locations_seeded_v1', 'true');
        }
      } catch (err: any) {
        console.error('Exception deleting office location from Supabase:', err);
        setOfficeLocations(prevLocations);
        return {
          success: false,
          error: err?.message || 'Database connection error while deleting office location.',
        };
      }
    }

    addAuditLog('OFFICE_LOCATION_DELETED', 'Field Force Master', `Deleted office geofence ID ${id}`);

    try {
      await fetch(
        `/api/office-locations/${encodeURIComponent(id)}${sb ? '?skipSupabaseSync=1' : ''}`,
        { method: 'DELETE' }
      );
    } catch {}

    return { success: true };
  };

  const recordRejectedAttendanceAttempt = (
    attempt: Omit<RejectedAttendanceAttempt, 'id' | 'createdAt'>
  ) => {
    const newAttempt: RejectedAttendanceAttempt = {
      ...attempt,
      id: `att-rej-${Date.now()}-${Math.random().toString(36).slice(2, 5)}`,
      createdAt: new Date().toISOString(),
    };
    setRejectedAttendanceAttempts((prev) => [newAttempt, ...prev].slice(0, 300));
    addAuditLog(
      'ATTENDANCE_GPS_REJECTED',
      'Attendance & Geofence',
      `Rejected ${attempt.attemptType} for ${attempt.employeeName} (${attempt.rejectionReason})`
    );
  };

  const resolveEmployeeGeofenceConfig = (employee: FieldForceRep) => {
    const linkedUser = findLinkedUserForEmployee(employee, users);
    return resolveGeofenceConfigFromUser(
      linkedUser,
      officeLocations,
      payrollSettings,
      employee.branchWorkplace
    );
  };

  const mapSupabaseOvertimeRow = (r: any): OvertimeRequest => ({
    id: String(r.id),
    requestNumber: r.request_number,
    employeeId: String(r.employee_id),
    employeeCode: r.employee_code || '',
    employeeName: r.employee_name || '',
    department: r.department || '',
    designation: r.designation || '',
    employeeCategory: r.employee_category || undefined,
    overtimeDate: String(r.overtime_date),
    purposeCategory: r.purpose_category || 'Direct Production',
    productionOrderId: r.production_order_id || undefined,
    productionOrderNumber: r.production_order_number || undefined,
    productionBatchNumber: r.production_batch_number || undefined,
    productName: r.product_name || undefined,
    projectPurpose: r.project_purpose || '',
    sourceType: (r.source_type || 'MANUAL') as OvertimeRequest['sourceType'],
    purposeId: r.purpose_id || undefined,
    purposeSelectedBy: r.purpose_selected_by || undefined,
    purposeSelectedAt: r.purpose_selected_at || undefined,
    expectedStartTime: r.expected_start_time || '18:00',
    expectedEndTime: r.expected_end_time || '22:00',
    expectedHours: Number(r.expected_hours) || 0,
    overtimeReason: r.overtime_reason || '',
    requestedBy: r.requested_by || '',
    requestedAt: r.requested_at || r.created_at || new Date().toISOString(),
    status: r.status || 'Pending Supervisor',
    supervisorId: r.supervisor_id || undefined,
    supervisorName: r.supervisor_name || undefined,
    supervisorApprovedAt: r.supervisor_approved_at || undefined,
    supervisorRemarks: r.supervisor_remarks || undefined,
    productionManagerId: r.production_manager_id || undefined,
    productionManagerName: r.production_manager_name || undefined,
    productionApprovedAt: r.production_approved_at || undefined,
    productionRemarks: r.production_remarks || undefined,
    hrVerifierId: r.hr_verifier_id || undefined,
    hrVerifierName: r.hr_verifier_name || undefined,
    hrVerifiedAt: r.hr_verified_at || undefined,
    hrRemarks: r.hr_remarks || undefined,
    finalApproverId: r.final_approver_id || undefined,
    finalApproverName: r.final_approver_name || undefined,
    finalApprovedAt: r.final_approved_at || undefined,
    finalRemarks: r.final_remarks || undefined,
    rejectionReason: r.rejection_reason || undefined,
    rejectedBy: r.rejected_by || undefined,
    rejectedAt: r.rejected_at || undefined,
    cancellationReason: r.cancellation_reason || undefined,
    cancelledBy: r.cancelled_by || undefined,
    cancelledAt: r.cancelled_at || undefined,
    attendanceId: r.attendance_id || undefined,
    actualOvertimeHours:
      r.actual_overtime_hours !== null && r.actual_overtime_hours !== undefined
        ? Number(r.actual_overtime_hours)
        : undefined,
    basicSalaryBDT: Number(r.basic_salary_bdt) || 0,
    hourlyRateBDT: Number(r.hourly_rate_bdt) || 0,
    overtimeMultiplier:
      r.overtime_multiplier !== null &&
      r.overtime_multiplier !== undefined &&
      !Number.isNaN(Number(r.overtime_multiplier))
        ? Number(r.overtime_multiplier)
        : 2.0,
    calculatedOvertimeAmountBDT: Number(r.calculated_overtime_amount_bdt) || 0,
    batchAllocations: [],
    isPayrollProcessed: Boolean(r.is_payroll_processed),
    payrollRunId: r.payroll_run_id || undefined,
    payrollMonth: r.payroll_month || undefined,
    isCostingAllocated: Boolean(r.is_costing_allocated),
    costingAllocationBatch: r.costing_allocation_batch || undefined,
    createdAt: r.created_at || new Date().toISOString(),
    updatedAt: r.updated_at || undefined,
  });

  const upsertOvertimeRequestInState = (otReq: OvertimeRequest) => {
    setOvertimeRequests((prev) => {
      const idx = prev.findIndex(
        (r) =>
          r.id === otReq.id ||
          (otReq.status !== 'Cancelled' &&
            r.status !== 'Cancelled' &&
            r.employeeId === otReq.employeeId &&
            r.overtimeDate === otReq.overtimeDate)
      );
      if (idx >= 0) {
        return prev.map((r, i) => (i === idx ? { ...r, ...otReq } : r));
      }
      return [otReq, ...prev];
    });
  };

  const appendLocalOvertimeAuditLogOnly = (log: Omit<OvertimeAuditTrail, 'id' | 'timestamp'>) => {
    const newLog: OvertimeAuditTrail = {
      ...log,
      id: `ot-aud-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      timestamp: new Date().toISOString(),
    };
    setOvertimeAuditLogs((prev) => [newLog, ...prev]);
  };

  const applyServerOvertimeSyncToState = (
    syncResult: { action?: string; request?: OvertimeRequest; message?: string } | null | undefined,
    actorLabel?: string
  ) => {
    if (!syncResult) return;
    if (
      (syncResult.action === 'CREATED' ||
        syncResult.action === 'UPDATED' ||
        syncResult.action === 'CANCELLED') &&
      syncResult.request
    ) {
      upsertOvertimeRequestInState(syncResult.request);
      if (syncResult.message) {
        appendLocalOvertimeAuditLogOnly({
          recordId: syncResult.request.id,
          recordType: 'REQUEST',
          action: `ATTENDANCE_AUTO_${syncResult.action}`,
          actorName: actorLabel || currentUser?.name || 'Attendance Synchronization',
          actorRole: currentUser?.role || 'System',
          details: syncResult.message,
          newState: syncResult.request.status,
        });
      }
    } else if (
      (syncResult.action === 'LOCKED_APPROVED' ||
        syncResult.action === 'LOCKED_REJECTED' ||
        syncResult.action === 'LOCKED_CANCELLED') &&
      syncResult.request &&
      syncResult.message
    ) {
      appendLocalOvertimeAuditLogOnly({
        recordId: syncResult.request.id,
        recordType: 'REQUEST',
        action: `ATTENDANCE_SYNC_${syncResult.action}`,
        actorName: actorLabel || currentUser?.name || 'Attendance Synchronization',
        actorRole: currentUser?.role || 'System',
        details: syncResult.message,
        previousState: syncResult.request.status,
        newState: syncResult.request.status,
      });
    }
  };

  const syncAttendanceToOvertimeClientFallback = async (params: {
    attendanceRecord: AttendanceRecord;
    sourceMode: AttendanceOvertimeSourceMode;
    existingRequestsSnapshot?: OvertimeRequest[];
    dbSyncedAttendance?: boolean;
  }): Promise<{
    action: QrOvertimeSyncResult['action'];
    request?: OvertimeRequest;
    message: string;
    nextRequestsSnapshot: OvertimeRequest[];
  }> => {
    const {
      attendanceRecord,
      sourceMode,
      existingRequestsSnapshot = overtimeRequests,
      dbSyncedAttendance = false,
    } = params;

    const emp =
      fieldForceReps.find(
        (r) =>
          String(r.id) === String(attendanceRecord.employeeId) ||
          (attendanceRecord.employeeCode &&
            r.code &&
            r.code.toLowerCase() === attendanceRecord.employeeCode.toLowerCase())
      ) || {
        id: attendanceRecord.employeeId,
        code: attendanceRecord.employeeCode || 'EMP-000',
        name: attendanceRecord.employeeName || 'Staff Member',
        department: attendanceRecord.department || 'Operations',
        designation: attendanceRecord.designation || 'Staff',
        employeeCategory: attendanceRecord.employeeCategory,
        basicSalaryBDT: 25000,
      };

    const str = salaryStructures.find(
      (s) => s.employeeId === emp.id || (emp.code && s.employeeCode === emp.code)
    );
    const basic = str ? str.basicSalaryBDT : emp.basicSalaryBDT || 25000;
    const gross = str ? str.grossSalaryBDT : Math.round(basic * 1.6);
    const policy = getEmployeeEffectiveOvertimePolicy(emp.id, attendanceRecord.date);
    const actorName =
      sourceMode === 'QR'
        ? currentUser?.name || 'QR Attendance Automation'
        : currentUser?.name || 'Attendance Synchronization';

    const beforeActive = findDuplicateOvertimeRequest(
      existingRequestsSnapshot,
      emp.id,
      emp.code,
      attendanceRecord.date
    );
    const beforeCancelled = !beforeActive
      ? findCancelledOvertimeRequest(
          existingRequestsSnapshot,
          emp.id,
          emp.code,
          attendanceRecord.date
        )
      : undefined;
    const beforeOt = beforeActive || beforeCancelled || null;

    // If Supabase persisted the attendance row, check whether PostgreSQL trigger already synced overtime_requests
    const sb = getSupabase();
    if (sb && dbSyncedAttendance && attendanceRecord.date) {
      try {
        const { data: dbOtRows } = await sb
          .from('overtime_requests')
          .select('*')
          .eq('overtime_date', attendanceRecord.date)
          .order('created_at', { ascending: false });
        if (Array.isArray(dbOtRows)) {
          const mappedDbRows = dbOtRows.map(mapSupabaseOvertimeRow);
          const dbActive = findDuplicateOvertimeRequest(
            mappedDbRows,
            emp.id,
            emp.code,
            attendanceRecord.date
          );
          const dbCancelled = !dbActive
            ? findCancelledOvertimeRequest(
                mappedDbRows,
                emp.id,
                emp.code,
                attendanceRecord.date
              )
            : undefined;
          const afterDbRow = dbActive || dbCancelled || null;

          const triggerHandled = Boolean(
            afterDbRow &&
              ((!beforeOt && afterDbRow.status !== 'Cancelled') ||
                (beforeOt &&
                  beforeOt.id === afterDbRow.id &&
                  (beforeOt.status !== afterDbRow.status ||
                    beforeOt.expectedHours !== afterDbRow.expectedHours ||
                    beforeOt.expectedEndTime !== afterDbRow.expectedEndTime ||
                    beforeOt.expectedStartTime !== afterDbRow.expectedStartTime)))
          );

          if (triggerHandled && afterDbRow) {
            upsertOvertimeRequestInState(afterDbRow);
            const inferredAction: QrOvertimeSyncResult['action'] = !beforeOt
              ? 'CREATED'
              : afterDbRow.status === 'Cancelled' && beforeOt.status !== 'Cancelled'
              ? 'CANCELLED'
              : 'UPDATED';
            const inferredMsg =
              inferredAction === 'CREATED'
                ? `Auto-generated Overtime Request ${afterDbRow.requestNumber} (${afterDbRow.expectedHours}h OT on ${attendanceRecord.date}).`
                : inferredAction === 'CANCELLED'
                ? `Cancelled Pending Overtime Request ${afterDbRow.requestNumber}: ${
                    afterDbRow.cancellationReason || 'Attendance OUT Time Updated – No Overtime'
                  }.`
                : `Updated pending Overtime Request ${afterDbRow.requestNumber} to ${afterDbRow.expectedHours}h.`;

            appendLocalOvertimeAuditLogOnly({
              recordId: afterDbRow.id,
              recordType: 'REQUEST',
              action:
                sourceMode === 'QR'
                  ? `QR_AUTO_${inferredAction}`
                  : `ATTENDANCE_AUTO_${inferredAction}`,
              actorName,
              actorRole: currentUser?.role || 'System',
              details: inferredMsg,
              previousState: beforeOt?.status,
              newState: afterDbRow.status,
            });

            const idx = existingRequestsSnapshot.findIndex(
              (r) =>
                r.id === afterDbRow.id ||
                (afterDbRow.status !== 'Cancelled' &&
                  r.status !== 'Cancelled' &&
                  r.employeeId === afterDbRow.employeeId &&
                  r.overtimeDate === afterDbRow.overtimeDate)
            );
            const nextSnapshot =
              idx >= 0
                ? existingRequestsSnapshot.map((r, i) => (i === idx ? afterDbRow : r))
                : [afterDbRow, ...existingRequestsSnapshot];

            return {
              action: inferredAction,
              request: afterDbRow,
              message: inferredMsg,
              nextRequestsSnapshot: nextSnapshot,
            };
          }
        }
      } catch {
        // Proceed with standard client-side reconciliation fallback
      }
    }

    const otResult = reconcileAttendanceOvertimeRequest({
      existingRequests: existingRequestsSnapshot,
      attendanceRecord,
      employee: {
        id: emp.id,
        code: emp.code,
        name: emp.name,
        department: emp.department,
        designation: emp.designation,
        employeeCategory: emp.employeeCategory,
        basicSalaryBDT: basic,
      },
      salaryBasicBDT: basic,
      salaryGrossBDT: gross,
      policy,
      defaultShiftEndTime: payrollSettings?.shiftEndTime || DEFAULT_SHIFT_END_TIME,
      defaultShiftStartTime: payrollSettings?.shiftStartTime || DEFAULT_SHIFT_START_TIME,
      nowIso: attendanceRecord.updatedAt || new Date().toISOString(),
      sourceMode,
      actorName,
    });

    let nextRequestsSnapshot = existingRequestsSnapshot;

    if (
      (otResult.action === 'CREATED' ||
        otResult.action === 'UPDATED' ||
        otResult.action === 'CANCELLED') &&
      otResult.request
    ) {
      const otReq = otResult.request;
      upsertOvertimeRequestInState(otReq);
      const idx = existingRequestsSnapshot.findIndex(
        (r) =>
          r.id === otReq.id ||
          (otReq.status !== 'Cancelled' &&
            r.status !== 'Cancelled' &&
            r.employeeId === otReq.employeeId &&
            r.overtimeDate === otReq.overtimeDate)
      );
      nextRequestsSnapshot =
        idx >= 0
          ? existingRequestsSnapshot.map((r, i) => (i === idx ? otReq : r))
          : [otReq, ...existingRequestsSnapshot];

      if (sb) {
        if (otResult.action === 'CANCELLED') {
          const cancelFields: Record<string, any> = {
            status: 'Cancelled',
            attendance_id: otReq.attendanceId || null,
            actual_overtime_hours: 0,
            cancellation_reason:
              otReq.cancellationReason || 'Attendance OUT Time Updated – No Overtime',
            cancelled_by: otReq.cancelledBy || actorName,
            cancelled_at: otReq.cancelledAt || new Date().toISOString(),
            rejection_reason:
              otReq.cancellationReason || 'Attendance OUT Time Updated – No Overtime',
            updated_at: otReq.updatedAt || new Date().toISOString(),
          };
          for (let attempt = 0; attempt < 6; attempt++) {
            const { error } = await sb
              .from('overtime_requests')
              .update(cancelFields)
              .eq('id', otReq.id);
            if (!error) break;
            const msg = String(error.message || '');
            const missingCol =
              error.code === 'PGRST204' || msg.includes('schema cache')
                ? msg.match(/Could not find the '([^']+)' column/i)?.[1]
                : error.code === '42703' || msg.toLowerCase().includes('does not exist')
                ? msg.match(/column\s+"([^"]+)"/i)?.[1] ||
                  msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1]
                : null;
            if (missingCol && Object.prototype.hasOwnProperty.call(cancelFields, missingCol)) {
              delete cancelFields[missingCol];
              continue;
            }
            break;
          }
        } else if (otResult.action === 'UPDATED') {
          await sb
            .from('overtime_requests')
            .update({
              expected_start_time: otReq.expectedStartTime,
              expected_end_time: otReq.expectedEndTime,
              expected_hours: otReq.expectedHours,
              actual_overtime_hours: otReq.actualOvertimeHours ?? otReq.expectedHours,
              attendance_id: otReq.attendanceId || null,
              basic_salary_bdt: otReq.basicSalaryBDT || 0,
              hourly_rate_bdt: otReq.hourlyRateBDT || 0,
              overtime_multiplier: otReq.overtimeMultiplier ?? 2.0,
              calculated_overtime_amount_bdt: otReq.calculatedOvertimeAmountBDT || 0,
              overtime_reason: otReq.overtimeReason,
              updated_at: otReq.updatedAt || new Date().toISOString(),
            })
            .eq('id', otReq.id);
        } else {
          const workingPayload: Record<string, any> = {
            id: otReq.id,
            request_number: otReq.requestNumber,
            employee_id: otReq.employeeId,
            employee_code: otReq.employeeCode,
            employee_name: otReq.employeeName,
            department: otReq.department,
            designation: otReq.designation,
            employee_category: otReq.employeeCategory || 'Factory Employee',
            overtime_date: otReq.overtimeDate,
            purpose_category: otReq.purposeCategory,
            project_purpose: otReq.projectPurpose ?? '',
            source_type: otReq.sourceType || 'ATTENDANCE_AUTO',
            expected_start_time: otReq.expectedStartTime,
            expected_end_time: otReq.expectedEndTime,
            expected_hours: otReq.expectedHours,
            overtime_reason: otReq.overtimeReason,
            requested_by: otReq.requestedBy,
            requested_at: otReq.requestedAt,
            status: otReq.status,
            attendance_id: otReq.attendanceId || null,
            actual_overtime_hours: otReq.actualOvertimeHours ?? otReq.expectedHours,
            basic_salary_bdt: otReq.basicSalaryBDT || 0,
            hourly_rate_bdt: otReq.hourlyRateBDT || 0,
            overtime_multiplier: otReq.overtimeMultiplier ?? 2.0,
            calculated_overtime_amount_bdt: otReq.calculatedOvertimeAmountBDT || 0,
            is_payroll_processed: false,
            is_costing_allocated: false,
            created_at: otReq.createdAt,
            updated_at: otReq.updatedAt || new Date().toISOString(),
          };
          for (let attempt = 0; attempt < 6; attempt++) {
            const { error } = await sb
              .from('overtime_requests')
              .upsert(workingPayload, { onConflict: 'id' });
            if (!error) break;
            const msg = String(error.message || '');
            const missingCol =
              error.code === 'PGRST204' || msg.includes('schema cache')
                ? msg.match(/Could not find the '([^']+)' column/i)?.[1]
                : error.code === '42703' || msg.toLowerCase().includes('does not exist')
                ? msg.match(/column\s+"([^"]+)"/i)?.[1] ||
                  msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1]
                : null;
            if (missingCol && Object.prototype.hasOwnProperty.call(workingPayload, missingCol)) {
              delete workingPayload[missingCol];
              continue;
            }
            break;
          }
        }
      }

      addOvertimeAuditLog({
        recordId: otReq.id,
        recordType: 'REQUEST',
        action:
          sourceMode === 'QR'
            ? `QR_AUTO_${otResult.action}`
            : `ATTENDANCE_AUTO_${otResult.action}`,
        actorName,
        actorRole: currentUser?.role || 'System',
        details: otResult.auditDetails || otResult.message,
        previousState: otResult.previousStatus,
        newState: otReq.status,
      });
    } else if (
      (otResult.action === 'LOCKED_APPROVED' ||
        otResult.action === 'LOCKED_REJECTED' ||
        otResult.action === 'LOCKED_CANCELLED') &&
      otResult.request
    ) {
      addOvertimeAuditLog({
        recordId: otResult.request.id,
        recordType: 'REQUEST',
        action: `ATTENDANCE_SYNC_${otResult.action}`,
        actorName,
        actorRole: currentUser?.role || 'System',
        details: otResult.auditDetails || otResult.message,
        previousState: otResult.request.status,
        newState: otResult.request.status,
      });
    }

    return {
      action: otResult.action,
      request: otResult.request,
      message: otResult.message,
      nextRequestsSnapshot,
    };
  };

  const markAttendance = async (
    record: Omit<AttendanceRecord, 'id' | 'createdAt' | 'updatedAt'>
  ): Promise<{
    success: boolean;
    id: string;
    dbSynced: boolean;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
    overtimeSync?: {
      action: string;
      request?: OvertimeRequest;
      message?: string;
    } | null;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'quick_action')) {
      console.warn('Permission denied: quick_action required to use Daily Grid Quick Action attendance controls.');
      addAuditLog(
        'PERMISSION_DENIED',
        'HR & Payroll',
        `${currentUser?.name || 'User'} attempted Daily Grid Quick Action attendance update without quick_action permission`
      );
      return {
        success: false,
        id: '',
        dbSynced: false,
        error: 'Permission denied: Quick Action permission required.',
      };
    }

    const existing = attendanceRecords.find(
      (a) =>
        (a.employeeId === record.employeeId || a.fieldForceId === record.employeeId) &&
        a.date === record.date
    );
    const id =
      existing?.id || `att-${record.employeeId || 'emp'}-${record.date}-${Date.now().toString().slice(-4)}`;
    const now = new Date().toISOString();
    const inVal = record.inTime ?? record.checkInTime;
    const outVal = record.outTime ?? record.checkOutTime;
    const newRecord: AttendanceRecord = {
      ...(existing || {}),
      ...record,
      id,
      fieldForceId: record.fieldForceId || record.employeeId,
      inTime: inVal || undefined,
      checkInTime: inVal || undefined,
      outTime: outVal || undefined,
      checkOutTime: outVal || undefined,
      gpsValidationStatus: record.gpsValidationStatus || existing?.gpsValidationStatus || 'Manual',
      createdAt: existing?.createdAt || now,
      updatedAt: now,
    };

    const nextSnapshot = [
      newRecord,
      ...attendanceRecords.filter(
        (a) =>
          !(
            (a.employeeId === record.employeeId || a.fieldForceId === record.employeeId) &&
            a.date === record.date
          )
      ),
    ];
    setAttendanceRecords(nextSnapshot);

    const logManualAttendance = () =>
      addAuditLog(
        'ATTENDANCE_MARKED',
        'HR & Payroll',
        `Updated attendance for ${newRecord.employeeName} (${newRecord.date}): ${newRecord.status}${
          newRecord.inTime ? ` In ${newRecord.inTime}` : ''
        }${newRecord.outTime ? ` Out ${newRecord.outTime}` : ''}`
      );

    // Attempt server-backed atomic upsert + OT reconciliation first
    const callManualUpsertApi = async (overrideToken?: string | null) =>
      fetch('/api/attendance/manual-upsert', {
        method: 'POST',
        headers: getErpAuthHeaders(overrideToken),
        body: JSON.stringify({
          record: newRecord,
          employeesSnapshot: fieldForceReps,
          payrollSettings,
        }),
      });

    try {
      let resp = await callManualUpsertApi();
      if (resp.status === 401 && isAuthenticated && currentUser?.id && currentUser.id !== 'guest') {
        const freshToken = await establishServerSession(currentUser);
        if (freshToken) {
          resp = await callManualUpsertApi(freshToken);
        }
      }
      const contentType = String(resp.headers.get('content-type') || '').toLowerCase();
      const rawText = await resp.text();
      const parsed = tryParseJsonSafe(rawText);
      const data = parsed.data;
      if (resp.status === 403 && parsed.ok && data?.error) {
        setAttendanceRecords(attendanceRecords);
        return {
          success: false,
          id: '',
          dbSynced: false,
          error: data.error,
        };
      }
      if (
        contentType.includes('application/json') &&
        parsed.ok &&
        resp.ok &&
        data?.success &&
        Array.isArray(data.records)
      ) {
        const savedRec: AttendanceRecord = data.records[0] || newRecord;
        const syncedSnapshot = [
          savedRec,
          ...nextSnapshot.filter(
            (a) =>
              !(
                (a.employeeId === savedRec.employeeId || a.fieldForceId === savedRec.employeeId) &&
                a.date === savedRec.date
              )
          ),
        ];
        setAttendanceRecords(syncedSnapshot);

        let dbSynced = Boolean(data.dbSynced);
        let dbError = data.dbError as string | undefined;
        let sqlFix: string | undefined;
        let backedUp: boolean | undefined;
        let overtimeSync = (Array.isArray(data.overtimeSyncResults)
          ? data.overtimeSyncResults[0]
          : null) || null;

        if (!dbSynced) {
          const persistFallback = await persistAttendanceRecordsToSupabase([savedRec], syncedSnapshot);
          dbSynced = persistFallback.dbSynced;
          dbError = persistFallback.error || dbError;
          sqlFix = persistFallback.sqlFix;
          backedUp = persistFallback.backedUp;
        } else {
          setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
        }

        if (overtimeSync) {
          applyServerOvertimeSyncToState(overtimeSync, currentUser?.name);
        } else {
          const otClient = await syncAttendanceToOvertimeClientFallback({
            attendanceRecord: savedRec,
            sourceMode: 'MANUAL',
            dbSyncedAttendance: dbSynced,
          });
          overtimeSync = {
            action: otClient.action,
            request: otClient.request,
            message: otClient.message,
          };
        }

        logManualAttendance();
        return {
          success: true,
          id: savedRec.id || id,
          dbSynced,
          backedUp,
          error: dbError,
          sqlFix,
          overtimeSync,
        };
      }
    } catch {
      // Static SPA or unreachable backend -> proceed with direct Supabase + client fallback
    }

    const persistResult = await persistAttendanceRecordsToSupabase([newRecord], nextSnapshot);
    const otFallback = await syncAttendanceToOvertimeClientFallback({
      attendanceRecord: newRecord,
      sourceMode: 'MANUAL',
      dbSyncedAttendance: persistResult.dbSynced,
    });
    logManualAttendance();

    return {
      success: true,
      id,
      dbSynced: persistResult.dbSynced,
      backedUp: persistResult.backedUp,
      error: persistResult.error,
      sqlFix: persistResult.sqlFix,
      overtimeSync: {
        action: otFallback.action,
        request: otFallback.request,
        message: otFallback.message,
      },
    };
  };

  const bulkMarkAttendance = async (
    records: Omit<AttendanceRecord, 'id' | 'createdAt' | 'updatedAt'>[]
  ): Promise<{
    success: boolean;
    dbSynced: boolean;
    syncedCount: number;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
    overtimeSyncResults?: Array<{
      employeeId?: string;
      date?: string;
      action: string;
      request?: OvertimeRequest;
      message?: string;
    }>;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to bulk mark attendance.');
      addAuditLog(
        'PERMISSION_DENIED',
        'HR & Payroll',
        `${currentUser?.name || 'User'} attempted bulk attendance marking without create_payroll permission`
      );
      return {
        success: false,
        dbSynced: false,
        syncedCount: 0,
        error: 'Permission denied: Process Monthly Payroll permission required.',
      };
    }

    const now = new Date().toISOString();
    const newItems: AttendanceRecord[] = records.map((r, idx) => {
      const existing = attendanceRecords.find(
        (a) => (a.employeeId === r.employeeId || a.fieldForceId === r.employeeId) && a.date === r.date
      );
      const inVal = r.inTime ?? r.checkInTime;
      const outVal = r.outTime ?? r.checkOutTime;
      return {
        ...(existing || {}),
        ...r,
        id: existing?.id || `att-${Date.now()}-${idx}`,
        fieldForceId: r.fieldForceId || r.employeeId,
        inTime: inVal || undefined,
        checkInTime: inVal || undefined,
        outTime: outVal || undefined,
        checkOutTime: outVal || undefined,
        gpsValidationStatus: r.gpsValidationStatus || existing?.gpsValidationStatus || 'Manual',
        createdAt: existing?.createdAt || now,
        updatedAt: now,
      };
    });

    const keys = new Set(newItems.map((i) => `${i.employeeId}_${i.date}`));
    const nextSnapshot = [
      ...newItems,
      ...attendanceRecords.filter((p) => !keys.has(`${p.employeeId}_${p.date}`)),
    ];
    setAttendanceRecords(nextSnapshot);

    const callBulkApi = async (overrideToken?: string | null) =>
      fetch('/api/attendance/manual-upsert', {
        method: 'POST',
        headers: getErpAuthHeaders(overrideToken),
        body: JSON.stringify({
          records: newItems,
          employeesSnapshot: fieldForceReps,
          payrollSettings,
        }),
      });

    try {
      let resp = await callBulkApi();
      if (resp.status === 401 && isAuthenticated && currentUser?.id && currentUser.id !== 'guest') {
        const freshToken = await establishServerSession(currentUser);
        if (freshToken) {
          resp = await callBulkApi(freshToken);
        }
      }
      const contentType = String(resp.headers.get('content-type') || '').toLowerCase();
      const rawText = await resp.text();
      const parsed = tryParseJsonSafe(rawText);
      const data = parsed.data;
      if (
        contentType.includes('application/json') &&
        parsed.ok &&
        resp.ok &&
        data?.success &&
        Array.isArray(data.records)
      ) {
        const srvRecords: AttendanceRecord[] = data.records;
        const srvKeys = new Set(srvRecords.map((i) => `${i.employeeId}_${i.date}`));
        const syncedSnapshot = [
          ...srvRecords,
          ...nextSnapshot.filter((p) => !srvKeys.has(`${p.employeeId}_${p.date}`)),
        ];
        setAttendanceRecords(syncedSnapshot);

        let dbSynced = Boolean(data.dbSynced);
        let syncedCount = dbSynced ? srvRecords.length : 0;
        let backedUp: boolean | undefined;
        let dbError = data.dbError as string | undefined;
        let sqlFix: string | undefined;

        if (!dbSynced) {
          const persistFallback = await persistAttendanceRecordsToSupabase(srvRecords, syncedSnapshot);
          dbSynced = persistFallback.dbSynced;
          syncedCount = persistFallback.syncedCount;
          backedUp = persistFallback.backedUp;
          dbError = persistFallback.error || dbError;
          sqlFix = persistFallback.sqlFix;
        } else {
          setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
        }

        const otResults = Array.isArray(data.overtimeSyncResults) ? data.overtimeSyncResults : [];
        for (const r of otResults) {
          applyServerOvertimeSyncToState(r, currentUser?.name);
        }

        addAuditLog('ATTENDANCE_BULK_LOGGED', 'HR & Payroll', `Marked attendance for ${records.length} employees`);
        return {
          success: true,
          dbSynced,
          syncedCount,
          backedUp,
          error: dbError,
          sqlFix,
          overtimeSyncResults: otResults,
        };
      }
    } catch {
      // Static SPA or unreachable backend -> fall back cleanly
    }

    const persistResult = await persistAttendanceRecordsToSupabase(newItems, nextSnapshot);
    const overtimeSyncResults: Array<{
      employeeId?: string;
      date?: string;
      action: string;
      request?: OvertimeRequest;
      message?: string;
    }> = [];
    let workingReqs = [...overtimeRequests];
    for (const item of newItems) {
      const otRes = await syncAttendanceToOvertimeClientFallback({
        attendanceRecord: item,
        sourceMode: 'MANUAL',
        existingRequestsSnapshot: workingReqs,
        dbSyncedAttendance: persistResult.dbSynced,
      });
      workingReqs = otRes.nextRequestsSnapshot;
      overtimeSyncResults.push({
        employeeId: item.employeeId,
        date: item.date,
        action: otRes.action,
        request: otRes.request,
        message: otRes.message,
      });
    }

    addAuditLog('ATTENDANCE_BULK_LOGGED', 'HR & Payroll', `Marked attendance for ${records.length} employees`);

    return {
      success: true,
      dbSynced: persistResult.dbSynced,
      syncedCount: persistResult.syncedCount,
      backedUp: persistResult.backedUp,
      error: persistResult.error,
      sqlFix: persistResult.sqlFix,
      overtimeSyncResults,
    };
  };

  const syncAttendanceToSupabase = async (): Promise<{
    success: boolean;
    dbSynced: boolean;
    syncedCount: number;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      return {
        success: false,
        dbSynced: false,
        syncedCount: 0,
        error: 'Permission denied: Process Monthly Payroll permission required.',
      };
    }
    if (attendanceRecords.length === 0) {
      await refreshAttendanceData();
      const sb = getSupabase();
      if (sb) {
        const probe = await sb.from('employee_attendances').select('id').limit(1);
        if (probe.error) {
          const status = classifyAttendanceSupabaseError(probe.error);
          setAttendanceDbStatus(status);
          return {
            success: false,
            dbSynced: false,
            syncedCount: 0,
            error: status.error || undefined,
            sqlFix: status.sqlFix || EMPLOYEE_ATTENDANCES_TABLE_SQL,
          };
        }
        setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
      }
      return {
        success: true,
        dbSynced: true,
        syncedCount: 0,
      };
    }

    const persistResult = await persistAttendanceRecordsToSupabase(attendanceRecords, attendanceRecords);
    return {
      success: persistResult.dbSynced,
      dbSynced: persistResult.dbSynced,
      syncedCount: persistResult.syncedCount,
      backedUp: persistResult.backedUp,
      error: persistResult.error,
      sqlFix: persistResult.sqlFix,
    };
  };

  const submitGpsCheckIn: ERPContextType['submitGpsCheckIn'] = async ({
    employee,
    latitude,
    longitude,
    accuracy,
    date,
    checkInTime,
    source = 'erp',
  }) => {
    const todayStr = date || new Date().toISOString().slice(0, 10);
    const nowObj = new Date();
    const timeHHmm =
      checkInTime ||
      `${String(nowObj.getHours()).padStart(2, '0')}:${String(nowObj.getMinutes()).padStart(2, '0')}`;
    const existing = attendanceRecords.find(
      (a) =>
        (a.employeeId === employee.id || a.fieldForceId === employee.id) &&
        a.date === todayStr &&
        (a.checkInTime || a.inTime) &&
        a.gpsValidationStatus === 'Accepted'
    );
    if (existing) {
      return {
        accepted: false,
        errorCode: 'DUPLICATE_CHECK_IN',
        reason: `Duplicate Check-In blocked: ${employee.name} has already checked in on ${todayStr} at ${existing.checkInTime || existing.inTime}.`,
      };
    }

    const cfg = resolveEmployeeGeofenceConfig(employee);
    try {
      const resp = await fetch('/api/attendance/check-in', {
        method: 'POST',
        headers: {
          ...getErpAuthHeaders(),
          ...(source === 'mobile-field' ? { 'x-mobile-portal': 'true' } : {}),
        },
        body: JSON.stringify({
          source,
          userId: currentUser?.id,
          employeeId: employee.id,
          employeeCode: employee.code,
          employeeName: employee.name,
          department: employee.department || 'Operations',
          designation: employee.designation,
          employeeCategory: employee.employeeCategory,
          date: todayStr,
          checkInTime: timeHHmm,
          latitude,
          longitude,
          accuracy,
          assignedOfficeId: cfg.assignedOfficeId,
          assignedOfficeName: cfg.assignedOfficeName,
          officeAddress: cfg.officeAddress,
          officeLatitude: cfg.officeLatitude,
          officeLongitude: cfg.officeLongitude,
          allowedRadiusMeters: cfg.allowedRadiusMeters,
          locationStatus: cfg.locationStatus,
          shiftStartTime: cfg.shiftStartTime,
          gracePeriodMinutes: cfg.gracePeriodMinutes,
          standardDailyHours: cfg.standardDailyHours,
          maxGpsAccuracyMeters: cfg.maxGpsAccuracyMeters,
          hasExistingCheckIn: Boolean(existing),
        }),
      });
      const data = await resp.json();
      if (resp.status === 401) {
        logout();
        return {
          accepted: false,
          errorCode: 'UNAUTHORIZED',
          reason: data?.reason || 'ERP session expired. Redirecting to login.',
        };
      }
      if (data.accepted && data.record) {
        const rec: AttendanceRecord = data.record;
        const nextSnapshot = [
          rec,
          ...attendanceRecords.filter((a) => !(a.employeeId === employee.id && a.date === todayStr)),
        ];
        setAttendanceRecords(nextSnapshot);
        if (data.dbSynced === false) {
          await persistAttendanceRecordsToSupabase([rec], nextSnapshot);
        } else {
          setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
        }
        updateRepLocation(employee.id, latitude, longitude, `${cfg.assignedOfficeName} (GPS Check-In)`);
        addAuditLog(
          'GPS_CHECK_IN_ACCEPTED',
          'Attendance & Geofence',
          `${employee.name} checked in at ${timeHHmm} (${data.distanceMeters}m from ${cfg.assignedOfficeName})`
        );
        return data;
      }
      if (data.rejectedAttempt) {
        setRejectedAttendanceAttempts((prev) => [data.rejectedAttempt, ...prev].slice(0, 300));
        addAuditLog(
          'GPS_CHECK_IN_REJECTED',
          'Attendance & Geofence',
          `Check-In rejected for ${employee.name}: ${data.reason}`
        );
      }
      return data;
    } catch {
      // Offline fallback validation using identical shared geofence evaluator
      const validation = evaluateGeofenceAttendance({
        employeeLatitude: latitude,
        employeeLongitude: longitude,
        gpsAccuracyMeters: accuracy,
        officeLatitude: cfg.officeLatitude,
        officeLongitude: cfg.officeLongitude,
        allowedRadiusMeters: cfg.allowedRadiusMeters,
        locationStatus: cfg.locationStatus,
        maxGpsAccuracyMeters: cfg.maxGpsAccuracyMeters,
      });
      if (!validation.accepted) {
        const rej: RejectedAttendanceAttempt = {
          id: `att-rej-${Date.now()}`,
          employeeId: employee.id,
          employeeCode: employee.code,
          employeeName: employee.name,
          department: employee.department,
          designation: employee.designation,
          assignedOfficeId: cfg.assignedOfficeId,
          assignedOfficeName: cfg.assignedOfficeName,
          officeLatitude: cfg.officeLatitude,
          officeLongitude: cfg.officeLongitude,
          allowedRadiusMeters: validation.allowedRadiusMeters,
          attemptType: 'Check In',
          attendanceDate: todayStr,
          attemptTime: nowObj.toTimeString().slice(0, 8),
          latitude,
          longitude,
          distanceMeters: validation.distanceMeters,
          gpsAccuracyMeters: accuracy,
          gpsValidationStatus: 'Rejected',
          rejectionReason: validation.reason,
          createdAt: nowObj.toISOString(),
        };
        setRejectedAttendanceAttempts((prev) => [rej, ...prev].slice(0, 300));
        return {
          accepted: false,
          errorCode: validation.errorCode,
          distanceMeters: validation.distanceMeters,
          allowedRadiusMeters: validation.allowedRadiusMeters,
          reason: validation.reason,
          rejectedAttempt: rej,
        };
      }
      const shiftCalc = calculateShiftAttendanceStatus({
        checkInTime: timeHHmm,
        shiftStartTime: cfg.shiftStartTime,
        gracePeriodMinutes: cfg.gracePeriodMinutes,
        standardDailyHours: cfg.standardDailyHours,
      });
      const rec: AttendanceRecord = {
        id: `att-${Date.now().toString().slice(-6)}`,
        fieldForceId: employee.id,
        employeeId: employee.id,
        employeeCode: employee.code,
        employeeName: employee.name,
        employeeCategory: employee.employeeCategory as EmployeeCategory | undefined,
        department: employee.department || 'Operations',
        designation: employee.designation,
        date: todayStr,
        status: shiftCalc.status,
        inTime: timeHHmm,
        checkInTime: timeHHmm,
        isLate: shiftCalc.isLate,
        lateMinutes: shiftCalc.lateDurationMinutes,
        lateDurationMinutes: shiftCalc.lateDurationMinutes,
        workHours: 0,
        overtimeHours: 0,
        assignedOfficeId: cfg.assignedOfficeId,
        assignedOfficeName: cfg.assignedOfficeName,
        officeLatitude: cfg.officeLatitude,
        officeLongitude: cfg.officeLongitude,
        allowedRadiusMeters: validation.allowedRadiusMeters,
        checkInLatitude: latitude,
        checkInLongitude: longitude,
        checkInDistanceMeters: validation.distanceMeters,
        checkInGpsAccuracyMeters: accuracy,
        checkInLocationText: `${latitude.toFixed(6)}, ${longitude.toFixed(6)}`,
        gpsValidationStatus: 'Accepted',
        validationReason: validation.reason,
        remarks: `GPS Check-In Accepted (${validation.distanceMeters}m from ${cfg.assignedOfficeName})`,
        createdAt: nowObj.toISOString(),
        updatedAt: nowObj.toISOString(),
      };
      const nextSnapshot = [
        rec,
        ...attendanceRecords.filter((a) => !(a.employeeId === employee.id && a.date === todayStr)),
      ];
      setAttendanceRecords(nextSnapshot);
      await persistAttendanceRecordsToSupabase([rec], nextSnapshot);
      return {
        accepted: true,
        distanceMeters: validation.distanceMeters,
        allowedRadiusMeters: validation.allowedRadiusMeters,
        reason: validation.reason,
        record: rec,
      };
    }
  };

  const submitGpsCheckOut: ERPContextType['submitGpsCheckOut'] = async ({
    employee,
    latitude,
    longitude,
    accuracy,
    date,
    checkOutTime,
    source = 'erp',
  }) => {
    const todayStr = date || new Date().toISOString().slice(0, 10);
    const nowObj = new Date();
    const timeHHmm =
      checkOutTime ||
      `${String(nowObj.getHours()).padStart(2, '0')}:${String(nowObj.getMinutes()).padStart(2, '0')}`;
    const existing = attendanceRecords.find(
      (a) => (a.employeeId === employee.id || a.fieldForceId === employee.id) && a.date === todayStr
    );
    if (!existing || !(existing.checkInTime || existing.inTime) || existing.status === 'Absent') {
      return {
        accepted: false,
        errorCode: 'NO_CHECK_IN',
        reason: `Cannot Check Out: No valid Check-In record found for ${employee.name} on ${todayStr}.`,
      };
    }
    if (existing.checkOutTime || existing.outTime) {
      return {
        accepted: false,
        errorCode: 'DUPLICATE_CHECK_OUT',
        reason: `Duplicate Check-Out blocked: ${employee.name} has already checked out on ${todayStr} at ${existing.checkOutTime || existing.outTime}.`,
      };
    }

    const cfg = resolveEmployeeGeofenceConfig(employee);
    try {
      const resp = await fetch('/api/attendance/check-out', {
        method: 'POST',
        headers: {
          ...getErpAuthHeaders(),
          ...(source === 'mobile-field' ? { 'x-mobile-portal': 'true' } : {}),
        },
        body: JSON.stringify({
          source,
          userId: currentUser?.id,
          employeeId: employee.id,
          employeeCode: employee.code,
          employeeName: employee.name,
          department: employee.department || 'Operations',
          designation: employee.designation,
          date: todayStr,
          checkOutTime: timeHHmm,
          latitude,
          longitude,
          accuracy,
          assignedOfficeId: cfg.assignedOfficeId,
          assignedOfficeName: cfg.assignedOfficeName,
          officeAddress: cfg.officeAddress,
          officeLatitude: cfg.officeLatitude,
          officeLongitude: cfg.officeLongitude,
          allowedRadiusMeters: cfg.allowedRadiusMeters,
          locationStatus: cfg.locationStatus,
          shiftStartTime: cfg.shiftStartTime,
          gracePeriodMinutes: cfg.gracePeriodMinutes,
          standardDailyHours: cfg.standardDailyHours,
          maxGpsAccuracyMeters: cfg.maxGpsAccuracyMeters,
          existingRecord: existing,
        }),
      });
      const data = await resp.json();
      if (resp.status === 401) {
        logout();
        return {
          accepted: false,
          errorCode: 'UNAUTHORIZED',
          reason: data?.reason || 'ERP session expired. Redirecting to login.',
        };
      }
      if (data.accepted && data.record) {
        const updatedRec: AttendanceRecord = data.record;
        const nextSnapshot = [
          updatedRec,
          ...attendanceRecords.filter((a) => !(a.employeeId === employee.id && a.date === todayStr)),
        ];
        setAttendanceRecords(nextSnapshot);
        if (data.dbSynced === false) {
          await persistAttendanceRecordsToSupabase([updatedRec], nextSnapshot);
        } else {
          setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
        }
        if (data.overtimeSync) {
          applyServerOvertimeSyncToState(data.overtimeSync, currentUser?.name || employee.name);
        }
        updateRepLocation(employee.id, latitude, longitude, `${cfg.assignedOfficeName} (GPS Check-Out)`);
        addAuditLog(
          'GPS_CHECK_OUT_ACCEPTED',
          'Attendance & Geofence',
          `${employee.name} checked out at ${timeHHmm} (${data.distanceMeters}m from ${cfg.assignedOfficeName})`
        );
        return data;
      }
      if (data.rejectedAttempt) {
        setRejectedAttendanceAttempts((prev) => [data.rejectedAttempt, ...prev].slice(0, 300));
        addAuditLog(
          'GPS_CHECK_OUT_REJECTED',
          'Attendance & Geofence',
          `Check-Out rejected for ${employee.name}: ${data.reason}`
        );
      }
      return data;
    } catch {
      const validation = evaluateGeofenceAttendance({
        employeeLatitude: latitude,
        employeeLongitude: longitude,
        gpsAccuracyMeters: accuracy,
        officeLatitude: cfg.officeLatitude,
        officeLongitude: cfg.officeLongitude,
        allowedRadiusMeters: cfg.allowedRadiusMeters,
        locationStatus: cfg.locationStatus,
        maxGpsAccuracyMeters: cfg.maxGpsAccuracyMeters,
      });
      if (!validation.accepted) {
        const rej: RejectedAttendanceAttempt = {
          id: `att-rej-${Date.now()}`,
          employeeId: employee.id,
          employeeCode: employee.code,
          employeeName: employee.name,
          department: employee.department,
          designation: employee.designation,
          assignedOfficeId: cfg.assignedOfficeId,
          assignedOfficeName: cfg.assignedOfficeName,
          officeLatitude: cfg.officeLatitude,
          officeLongitude: cfg.officeLongitude,
          allowedRadiusMeters: validation.allowedRadiusMeters,
          attemptType: 'Check Out',
          attendanceDate: todayStr,
          attemptTime: nowObj.toTimeString().slice(0, 8),
          latitude,
          longitude,
          distanceMeters: validation.distanceMeters,
          gpsAccuracyMeters: accuracy,
          gpsValidationStatus: 'Rejected',
          rejectionReason: validation.reason,
          createdAt: nowObj.toISOString(),
        };
        setRejectedAttendanceAttempts((prev) => [rej, ...prev].slice(0, 300));
        return {
          accepted: false,
          errorCode: validation.errorCode,
          distanceMeters: validation.distanceMeters,
          allowedRadiusMeters: validation.allowedRadiusMeters,
          reason: validation.reason,
          rejectedAttempt: rej,
        };
      }
      const shiftCalc = calculateShiftAttendanceStatus({
        checkInTime: existing.checkInTime || existing.inTime || '09:00',
        checkOutTime: timeHHmm,
        shiftStartTime: cfg.shiftStartTime,
        gracePeriodMinutes: cfg.gracePeriodMinutes,
        standardDailyHours: cfg.standardDailyHours,
      });
      const updatedRec: AttendanceRecord = {
        ...existing,
        outTime: timeHHmm,
        checkOutTime: timeHHmm,
        workHours: shiftCalc.totalWorkingHours,
        overtimeHours: shiftCalc.overtimeHours,
        status: shiftCalc.status,
        checkOutLatitude: latitude,
        checkOutLongitude: longitude,
        checkOutDistanceMeters: validation.distanceMeters,
        checkOutGpsAccuracyMeters: accuracy,
        checkOutLocationText: `${latitude.toFixed(6)}, ${longitude.toFixed(6)}`,
        gpsValidationStatus: 'Accepted',
        validationReason: validation.reason,
        updatedAt: nowObj.toISOString(),
      };
      const nextSnapshot = [
        updatedRec,
        ...attendanceRecords.filter((a) => !(a.employeeId === employee.id && a.date === todayStr)),
      ];
      setAttendanceRecords(nextSnapshot);
      const persistRes = await persistAttendanceRecordsToSupabase([updatedRec], nextSnapshot);
      const otRes = await syncAttendanceToOvertimeClientFallback({
        attendanceRecord: updatedRec,
        sourceMode: 'GPS',
        dbSyncedAttendance: persistRes.dbSynced,
      });
      return {
        accepted: true,
        distanceMeters: validation.distanceMeters,
        allowedRadiusMeters: validation.allowedRadiusMeters,
        reason: validation.reason,
        record: updatedRec,
        overtimeSync: {
          action: otRes.action,
          request: otRes.request,
          message: otRes.message,
        },
      };
    }
  };

  const submitQrAttendanceScan = async (qrPayload: string) => {
    const qrLatestRecordsStore: Map<string, AttendanceRecord> =
      (globalThis as any).__ensecLatestQrRecordsMap ||
      ((globalThis as any).__ensecLatestQrRecordsMap = new Map<string, AttendanceRecord>());

    const applyScannedRecordToState = (scannedRecord: AttendanceRecord, alreadySynced: boolean) => {
      const cacheKey = `${scannedRecord.employeeId || scannedRecord.fieldForceId || ''}_${scannedRecord.date}`;
      qrLatestRecordsStore.set(cacheKey, scannedRecord);
      setAttendanceRecords((prev) => {
        const filtered = prev.filter(
          (a) =>
            !(
              (a.employeeId === scannedRecord.employeeId ||
                a.fieldForceId === scannedRecord.employeeId) &&
              a.date === scannedRecord.date
            )
        );
        const nextSnapshot = [scannedRecord, ...filtered];
        if (!alreadySynced) {
          void persistAttendanceRecordsToSupabase([scannedRecord], nextSnapshot);
        } else {
          setAttendanceDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
        }
        return nextSnapshot;
      });
    };

    const runClientQrFallback = async () => {
      const verified = await verifyEmployeeQrTokenLocal(qrPayload);
      if (!verified.valid || !verified.employeeId) {
        return {
          success: false,
          duplicateBlocked: false,
          errorCode: 'INVALID_QR_CODE',
          error: verified.reason || 'Invalid employee QR code.',
        };
      }

      const resolvedRep =
        fieldForceReps.find((r) => String(r.id) === String(verified.employeeId)) ||
        (verified.employeeCode
          ? fieldForceReps.find(
              (r) => r.code && r.code.toLowerCase() === verified.employeeCode!.toLowerCase()
            )
          : undefined);

      if (!resolvedRep) {
        return {
          success: false,
          duplicateBlocked: false,
          errorCode: 'EMPLOYEE_NOT_FOUND',
          error: `No matching employee record found for ID ${verified.employeeCode || verified.employeeId}.`,
        };
      }

      const isEmpInactive =
        resolvedRep.status === 'Inactive' ||
        resolvedRep.isActive === false ||
        resolvedRep.employmentStatus === 'Inactive' ||
        resolvedRep.employmentStatus === 'Terminated';
      if (isEmpInactive) {
        return {
          success: false,
          duplicateBlocked: false,
          errorCode: 'EMPLOYEE_INACTIVE',
          error: `${resolvedRep.name} (${resolvedRep.code}) is currently Inactive and cannot record attendance.`,
          employee: {
            id: resolvedRep.id,
            code: resolvedRep.code,
            name: resolvedRep.name,
            department: resolvedRep.department,
            designation: resolvedRep.designation,
            employeeCategory: resolvedRep.employeeCategory,
          },
        };
      }

      const now = new Date();
      const attendanceDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(
        now.getDate()
      ).padStart(2, '0')}`;
      const scanTime24 = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
      const time12 = formatTime12Hour(scanTime24) || scanTime24;
      const nowIso = now.toISOString();

      const qrCooldownStore: Map<string, number> =
        (globalThis as any).__ensecQrCooldownMap ||
        ((globalThis as any).__ensecQrCooldownMap = new Map<string, number>());
      const prevScanMs = qrCooldownStore.get(resolvedRep.id);
      const nowMs = Date.now();
      if (prevScanMs && nowMs - prevScanMs < 3000) {
        const remainingMs = 3000 - (nowMs - prevScanMs);
        return {
          success: false,
          duplicateBlocked: true,
          cooldownRemainingMs: remainingMs,
          errorCode: 'DUPLICATE_SCAN_COOLDOWN',
          error: `Please wait ${Math.ceil(remainingMs / 1000)}s before scanning ${resolvedRep.name} again.`,
          employee: {
            id: resolvedRep.id,
            code: resolvedRep.code,
            name: resolvedRep.name,
            department: resolvedRep.department,
            designation: resolvedRep.designation,
            employeeCategory: resolvedRep.employeeCategory,
          },
          date: attendanceDate,
        };
      }

      // Check latest synchronous cache first, then memory state, then Supabase if configured
      const qrLockKey = `${resolvedRep.id}_${attendanceDate}`;
      let existing: AttendanceRecord | undefined =
        qrLatestRecordsStore.get(qrLockKey) ||
        attendanceRecords.find(
          (a) =>
            (a.employeeId === resolvedRep.id ||
              a.fieldForceId === resolvedRep.id ||
              (resolvedRep.code && a.employeeCode === resolvedRep.code)) &&
            a.date === attendanceDate
        );

      if (!existing) {
        const client = getSupabase();
        if (client && isSupabaseConfigured) {
          try {
            const { data: dbRow } = await client
              .from('employee_attendances')
              .select('*')
              .eq('employee_id', resolvedRep.id)
              .eq('date', attendanceDate)
              .maybeSingle();
            if (dbRow) {
              existing = {
                id: String(dbRow.id),
                fieldForceId: String(dbRow.employee_id),
                employeeId: String(dbRow.employee_id),
                employeeCode: dbRow.employee_code || resolvedRep.code,
                employeeName: dbRow.employee_name || resolvedRep.name,
                department: dbRow.department || resolvedRep.department,
                designation: dbRow.designation || resolvedRep.designation,
                date: String(dbRow.date),
                status: dbRow.status || 'Present',
                inTime: dbRow.in_time || undefined,
                checkInTime: dbRow.in_time || undefined,
                outTime: dbRow.out_time || undefined,
                checkOutTime: dbRow.out_time || undefined,
                workHours: Number(dbRow.work_hours) || 0,
                overtimeHours: Number(dbRow.overtime_hours) || 0,
                lateDurationMinutes: Number(dbRow.late_duration_minutes) || 0,
                lateMinutes: Number(dbRow.late_duration_minutes) || 0,
                gpsValidationStatus: (dbRow.gps_validation_status || 'Manual') as AttendanceRecord['gpsValidationStatus'],
                remarks: dbRow.remarks || undefined,
                createdAt: dbRow.created_at || undefined,
                updatedAt: dbRow.updated_at || undefined,
              };
            }
          } catch {
            // Fall back to local attendanceRecords state
          }
        }
      }

      const linkedUserForQr = findLinkedUserForEmployee(resolvedRep, users);
      const qrGeoCfg = resolveGeofenceConfigFromUser(
        linkedUserForQr,
        officeLocations,
        payrollSettings,
        resolvedRep.branchWorkplace
      );
      const shiftStartTime = qrGeoCfg.shiftStartTime;
      const gracePeriodMinutes = qrGeoCfg.gracePeriodMinutes;
      const standardDailyHours = qrGeoCfg.standardDailyHours;

      const existingIn = String(existing?.inTime || existing?.checkInTime || '').trim();
      const existingOut = String(existing?.outTime || existing?.checkOutTime || '').trim();

      let action: 'IN' | 'OUT' | 'OUT_UPDATE';
      let statusMessage: string;
      let nextRecord: AttendanceRecord;

      if (!existing || !existingIn || existing.status === 'Absent') {
        action = 'IN';
        statusMessage = 'IN Recorded Successfully';
        const shiftCalc = calculateShiftAttendanceStatus({
          checkInTime: scanTime24,
          shiftStartTime,
          gracePeriodMinutes,
          standardDailyHours,
        });
        nextRecord = {
          id: existing?.id || `att-qr-${Date.now().toString().slice(-6)}-${Math.random().toString(36).slice(2, 5)}`,
          userId: linkedUserForQr?.id || currentUser?.id,
          fieldForceId: resolvedRep.id,
          employeeId: resolvedRep.id,
          employeeCode: resolvedRep.code || undefined,
          employeeName: resolvedRep.name,
          employeeCategory: resolvedRep.employeeCategory as EmployeeCategory | undefined,
          department: resolvedRep.department || 'Operations',
          designation: resolvedRep.designation,
          assignedOfficeId: qrGeoCfg.assignedOfficeId,
          assignedOfficeName: qrGeoCfg.assignedOfficeName,
          date: attendanceDate,
          status: shiftCalc.status,
          inTime: scanTime24,
          checkInTime: scanTime24,
          outTime: undefined,
          checkOutTime: undefined,
          workHours: 0,
          overtimeHours: 0,
          isLate: shiftCalc.isLate,
          lateMinutes: shiftCalc.lateDurationMinutes,
          lateDurationMinutes: shiftCalc.lateDurationMinutes,
          gpsValidationStatus: 'QR Scan',
          scanMethod: 'QR',
          scanCount: 1,
          lastScanAt: nowIso,
          validationReason: `QR Scan IN at ${time12} (${attendanceDate})`,
          remarks: `QR Scan IN at ${time12}`,
          recordedBy: currentUser?.name || 'QR Attendance Scanner',
          createdAt: existing?.createdAt || nowIso,
          updatedAt: nowIso,
        };
      } else if (!existingOut) {
        action = 'OUT';
        statusMessage = 'OUT Recorded Successfully';
        const shiftCalc = calculateShiftAttendanceStatus({
          checkInTime: existingIn,
          checkOutTime: scanTime24,
          shiftStartTime,
          gracePeriodMinutes,
          standardDailyHours,
        });
        nextRecord = {
          ...existing,
          inTime: existingIn,
          checkInTime: existingIn,
          outTime: scanTime24,
          checkOutTime: scanTime24,
          workHours: shiftCalc.totalWorkingHours,
          overtimeHours: shiftCalc.overtimeHours,
          status: existing.isLate || existing.status === 'Late' ? 'Late' : shiftCalc.status,
          isLate: existing.isLate ?? shiftCalc.isLate,
          lateMinutes: existing.lateMinutes ?? existing.lateDurationMinutes ?? shiftCalc.lateDurationMinutes,
          lateDurationMinutes:
            existing.lateDurationMinutes ?? existing.lateMinutes ?? shiftCalc.lateDurationMinutes,
          gpsValidationStatus: existing.gpsValidationStatus === 'Accepted' ? 'Accepted' : 'QR Scan',
          scanMethod: 'QR',
          scanCount: Math.max(2, (existing.scanCount || 1) + 1),
          lastScanAt: nowIso,
          validationReason: `QR Scan OUT at ${time12}`,
          remarks: `${existing.remarks || `IN ${formatTime12Hour(existingIn) || existingIn}`} | QR Scan OUT at ${time12}`,
          updatedAt: nowIso,
        };
      } else {
        action = 'OUT_UPDATE';
        statusMessage = 'OUT Updated Successfully';
        const shiftCalc = calculateShiftAttendanceStatus({
          checkInTime: existingIn,
          checkOutTime: scanTime24,
          shiftStartTime,
          gracePeriodMinutes,
          standardDailyHours,
        });
        const baseRemarks = String(existing.remarks || `IN ${formatTime12Hour(existingIn) || existingIn}`)
          .split('|')[0]
          .trim();
        nextRecord = {
          ...existing,
          inTime: existingIn,
          checkInTime: existingIn,
          outTime: scanTime24,
          checkOutTime: scanTime24,
          workHours: shiftCalc.totalWorkingHours,
          overtimeHours: shiftCalc.overtimeHours,
          status: existing.isLate || existing.status === 'Late' ? 'Late' : shiftCalc.status,
          isLate: existing.isLate ?? shiftCalc.isLate,
          lateMinutes: existing.lateMinutes ?? existing.lateDurationMinutes ?? shiftCalc.lateDurationMinutes,
          lateDurationMinutes:
            existing.lateDurationMinutes ?? existing.lateMinutes ?? shiftCalc.lateDurationMinutes,
          gpsValidationStatus: existing.gpsValidationStatus === 'Accepted' ? 'Accepted' : 'QR Scan',
          scanMethod: 'QR',
          scanCount: Math.max(3, (existing.scanCount || 2) + 1),
          lastScanAt: nowIso,
          validationReason: `QR Scan OUT updated at ${time12}`,
          remarks: `${baseRemarks} | QR Scan OUT updated at ${time12}`,
          updatedAt: nowIso,
        };
      }

      const syncAutoOvertimeClientSide = async (
        scannedRecord: AttendanceRecord
      ) => {
        const res = await syncAttendanceToOvertimeClientFallback({
          attendanceRecord: scannedRecord,
          sourceMode: 'QR',
          dbSyncedAttendance: true,
        });
        return {
          action: res.action,
          request: res.request,
          message: res.message,
        };
      };

      qrCooldownStore.set(resolvedRep.id, Date.now());
      applyScannedRecordToState(nextRecord, false);
      let overtimeSyncResult: any = null;
      if (action === 'OUT' || action === 'OUT_UPDATE') {
        overtimeSyncResult = await syncAutoOvertimeClientSide(nextRecord);
      }
      addAuditLog(
        action === 'IN' ? 'QR_ATTENDANCE_IN' : 'QR_ATTENDANCE_OUT',
        'Payroll & HR Attendance',
        `${resolvedRep.name} (${resolvedRep.code || resolvedRep.id}) — ${statusMessage} at ${time12} (${attendanceDate})`
      );

      return {
        success: true,
        duplicateBlocked: false,
        action,
        statusLabel: (action === 'IN' ? 'IN' : 'OUT') as 'IN' | 'OUT',
        statusMessage,
        date: attendanceDate,
        recordedTime24: scanTime24,
        recordedTime12: time12,
        inTime: nextRecord.inTime || nextRecord.checkInTime,
        outTime: nextRecord.outTime || nextRecord.checkOutTime,
        employee: {
          id: resolvedRep.id,
          code: resolvedRep.code,
          name: resolvedRep.name,
          department: resolvedRep.department,
          designation: resolvedRep.designation,
          employeeCategory: resolvedRep.employeeCategory,
        },
        record: nextRecord,
        overtimeSync: overtimeSyncResult,
        dbSynced: true,
      };
    };

    const sendScan = async (overrideToken?: string | null) => {
      return fetch('/api/attendance/qr-scan', {
        method: 'POST',
        headers: getErpAuthHeaders(overrideToken),
        body: JSON.stringify({
          qrPayload,
          employeesSnapshot: fieldForceReps,
          payrollSettings,
        }),
      });
    };

    try {
      let resp = await sendScan();
      if (resp.status === 401 && isAuthenticated && currentUser?.id && currentUser.id !== 'guest') {
        const freshToken = await establishServerSession(currentUser);
        if (freshToken) {
          resp = await sendScan(freshToken);
        } else {
          return await runClientQrFallback();
        }
      }

      const contentType = String(resp.headers.get('content-type') || '').toLowerCase();
      const rawText = await resp.text();
      const parsed = tryParseJsonSafe(rawText);
      const data = parsed.data;
      const isQrScanApiPayload =
        Boolean(data) &&
        typeof data === 'object' &&
        !Array.isArray(data) &&
        ('success' in data || 'errorCode' in data || 'error' in data);

      // On static SPA hosting (e.g. Firebase Hosting rewrite returning index.html) or non-QR 200 JSON responses, fall back cleanly
      if (
        !contentType.includes('application/json') ||
        !parsed.ok ||
        (resp.ok && !isQrScanApiPayload) ||
        resp.status >= 500
      ) {
        return await runClientQrFallback();
      }

      if (!resp.ok || !data?.success) {
        return {
          success: false,
          duplicateBlocked: Boolean(data?.duplicateBlocked || resp.status === 429),
          cooldownRemainingMs: data?.cooldownRemainingMs,
          errorCode: data?.errorCode,
          error: data?.error || `Failed to process QR attendance scan (HTTP ${resp.status}).`,
          employee: data?.employee,
          date: data?.date,
          record: data?.record,
        };
      }

      const scannedRecord = data.record as AttendanceRecord | undefined;
      const finalDbSynced = Boolean(data.dbSynced);
      if (scannedRecord) {
        applyScannedRecordToState(scannedRecord, finalDbSynced);
      }

      if (data?.overtimeSync) {
        applyServerOvertimeSyncToState(data.overtimeSync, currentUser?.name || data?.employee?.name);
      }

      if (data?.employee?.name) {
        addAuditLog(
          data.action === 'IN' ? 'QR_ATTENDANCE_IN' : 'QR_ATTENDANCE_OUT',
          'Payroll & HR Attendance',
          `${data.employee.name} (${data.employee.code || data.employee.id}) — ${data.statusMessage || data.action} at ${data.recordedTime12 || data.recordedTime24} (${data.date})`
        );
      }

      return {
        success: true,
        duplicateBlocked: false,
        action: data.action,
        statusLabel: data.statusLabel,
        statusMessage: data.statusMessage,
        date: data.date,
        recordedTime24: data.recordedTime24,
        recordedTime12: data.recordedTime12,
        inTime: data.inTime,
        outTime: data.outTime,
        employee: data.employee,
        record: scannedRecord,
        overtimeSync: data.overtimeSync || null,
        dbSynced: finalDbSynced,
      };
    } catch {
      return await runClientQrFallback();
    }
  };

  const getEmployeeAttendanceSummary = (employeeId: string, monthYear: string) => {
    const [year, month] = monthYear.split('-').map(Number);
    const recs = attendanceRecords.filter(
      (a) => (a.employeeId === employeeId || a.fieldForceId === employeeId) && a.date.startsWith(monthYear)
    );
    const totalDays = new Date(year, month, 0).getDate();
    let present = 0;
    let absent = 0;
    let late = 0;
    let leave = 0;
    let holiday = 0;
    let halfDay = 0;
    let overtimeHours = 0;
    let totalWorkHours = 0;
    let totalLateMinutes = 0;

    recs.forEach((r) => {
      if (r.status === 'Present') present++;
      else if (r.status === 'Absent') absent++;
      else if (r.status === 'Late') {
        late++;
        present++;
      } else if (r.status === 'Leave' || r.status === 'Paid Leave' || r.status === 'Unpaid Leave') {
        leave++;
      } else if (r.status === 'Holiday' || r.status === 'Weekly Off' || r.status === 'Public Holiday') {
        holiday++;
      } else if (r.status === 'Half-Day' || r.status === 'Half Day') {
        halfDay++;
        present += 0.5;
      }
      const recIn = r.checkInTime || r.inTime;
      const recOut = r.checkOutTime || r.outTime;
      const netHrs = recIn && recOut ? calculateNetWorkingHours(recIn, recOut) : r.workHours || 0;
      overtimeHours += r.overtimeHours || 0;
      totalWorkHours += netHrs;
      totalLateMinutes += r.lateDurationMinutes ?? r.lateMinutes ?? 0;
    });

    const rejectedCount = rejectedAttendanceAttempts.filter(
      (att) => att.employeeId === employeeId && att.attendanceDate.startsWith(monthYear)
    ).length;

    return {
      totalDays,
      presentDays: present,
      absentDays: absent,
      lateDays: late,
      leaveDays: leave,
      holidays: holiday,
      halfDays: halfDay,
      rejectedCount,
      totalOvertimeHours: overtimeHours,
      totalWorkHours: Math.round(totalWorkHours * 100) / 100,
      totalLateMinutes,
    };
  };

  const refreshLeaveRecords = async () => {
    const sb = getSupabase();
    if (!sb) return;
    try {
      const [primaryRes, backupRes] = await Promise.all([
        sb.from('employee_leaves').select('*').order('applied_at', { ascending: false }).limit(500),
        sb
          .from('system_settings')
          .select('settings_json')
          .eq('id', 'employee_leaves')
          .maybeSingle(),
      ]);

      const mergedMap = new Map<string, LeaveRecord>();

      const backupList = Array.isArray((backupRes.data?.settings_json as any)?.records)
        ? ((backupRes.data!.settings_json as any).records as LeaveRecord[])
        : [];
      backupList.forEach((rec) => {
        if (rec?.id) mergedMap.set(rec.id, rec);
      });

      if (!primaryRes.error && Array.isArray(primaryRes.data)) {
        primaryRes.data.forEach((row: any) => {
          if (!row?.id) return;
          mergedMap.set(String(row.id), {
            id: String(row.id),
            employeeId: row.employee_id ? String(row.employee_id) : undefined,
            fieldForceId: row.employee_id ? String(row.employee_id) : undefined,
            employeeCode: row.employee_code ? String(row.employee_code) : undefined,
            employeeName: String(row.employee_name || ''),
            leaveType: (row.leave_type || 'Casual Leave') as LeaveRecord['leaveType'],
            startDate: String(row.start_date || ''),
            endDate: String(row.end_date || ''),
            daysCount: Number(row.days_count) || 1,
            totalDays: Number(row.days_count) || 1,
            reason: String(row.reason || ''),
            status: (row.status || 'Pending') as LeaveRecord['status'],
            appliedAt: row.applied_at ? String(row.applied_at) : undefined,
            approvedBy: row.approved_by ? String(row.approved_by) : undefined,
            approvedAt: row.approved_at ? String(row.approved_at) : undefined,
            rejectionReason: row.rejection_reason ? String(row.rejection_reason) : undefined,
          });
        });
      }

      if (mergedMap.size > 0) {
        const list = Array.from(mergedMap.values()).sort((a, b) =>
          (b.appliedAt || b.startDate || '').localeCompare(a.appliedAt || a.startDate || '')
        );
        setLeaveRecords(list);
      }
    } catch (err) {
      console.warn('refreshLeaveRecords notice:', err);
    }
  };

  const persistLeavesToSupabase = async (targetRecord: LeaveRecord, snapshotList: LeaveRecord[]) => {
    const sb = getSupabase();
    if (!sb) return;
    try {
      const { error } = await sb.from('employee_leaves').upsert(
        {
          id: targetRecord.id,
          employee_id: targetRecord.employeeId || targetRecord.fieldForceId || '',
          employee_code: targetRecord.employeeCode || '',
          employee_name: targetRecord.employeeName,
          leave_type: targetRecord.leaveType,
          start_date: targetRecord.startDate,
          end_date: targetRecord.endDate,
          days_count: Number(targetRecord.daysCount ?? targetRecord.totalDays ?? 1) || 1,
          reason: targetRecord.reason,
          status: targetRecord.status,
          applied_at: targetRecord.appliedAt || new Date().toISOString(),
          approved_by: targetRecord.approvedBy || null,
          approved_at: targetRecord.approvedAt || null,
          rejection_reason: targetRecord.rejectionReason || null,
        },
        { onConflict: 'id' }
      );

      if (error) {
        await sb.from('system_settings').upsert(
          {
            id: 'employee_leaves',
            software_name: 'Employee Leaves',
            logo_data_url: null,
            branding_json: { type: 'employee_leaves' },
            settings_json: { records: snapshotList.slice(0, 500) },
            updated_by: currentUser?.name || 'Admin',
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'id' }
        );
      }
    } catch (err) {
      console.warn('persistLeavesToSupabase notice:', err);
    }
  };

  const applyLeave = (leave: Omit<LeaveRecord, 'id' | 'appliedAt' | 'status'>): string => {
    const canSelectAnyEmployee =
      currentUser?.role === 'Super Admin' ||
      hasPageAction(currentUser, 'payroll', 'create_payroll');
    const canSubmitLeave =
      canSelectAnyEmployee ||
      hasPageAction(currentUser, 'payroll', 'view_leaves') ||
      hasPageAction(currentUser, 'mobile-field', 'view') ||
      hasPageAction(currentUser, 'mobile-field', 'create');
    if (!canSubmitLeave) {
      console.warn('Permission denied: Leaves page permission, create_payroll, or mobile-field access required to apply leave.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to apply leave without permission`);
      return '';
    }
    const id = `leave-${Date.now().toString().slice(-6)}`;
    const resolvedSelfId = currentEmployeeProfile?.employeeId || currentUser?.id;
    const resolvedSelfCode =
      currentEmployeeProfile?.employeeCode ||
      currentUser?.salesmanCode ||
      currentUser?.userId ||
      currentUser?.id;
    const resolvedSelfName = currentEmployeeProfile?.name || currentUser?.name || leave.employeeName;
    const resolvedSelfDept = currentEmployeeProfile?.department || currentUser?.department || leave.department;

    const newLeave: LeaveRecord = {
      ...leave,
      id,
      userId: canSelectAnyEmployee ? leave.userId || currentUser?.id : currentUser?.id,
      employeeId: canSelectAnyEmployee
        ? leave.employeeId || resolvedSelfId
        : resolvedSelfId,
      fieldForceId: canSelectAnyEmployee
        ? leave.fieldForceId || leave.employeeId || resolvedSelfId
        : resolvedSelfId,
      employeeCode: canSelectAnyEmployee
        ? leave.employeeCode || resolvedSelfCode
        : resolvedSelfCode,
      employeeName: canSelectAnyEmployee
        ? leave.employeeName || resolvedSelfName
        : resolvedSelfName,
      department: canSelectAnyEmployee
        ? leave.department || resolvedSelfDept
        : resolvedSelfDept,
      appliedAt: new Date().toISOString(),
      status: 'Pending',
    };
    const nextList = [newLeave, ...leaveRecords];
    setLeaveRecords((prev) => [newLeave, ...prev]);
    void persistLeavesToSupabase(newLeave, nextList);
    addAuditLog(
      'LEAVE_APPLIED',
      'HR & Payroll',
      `${newLeave.employeeName} applied for ${newLeave.leaveType} (${newLeave.daysCount} days: ${newLeave.startDate} to ${newLeave.endDate})`
    );
    return id;
  };

  const approveLeave = (id: string, approvedBy: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'approve_leave')) {
      console.warn('Permission denied: approve_leave required to approve leave.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to approve leave (${id}) without approve_leave permission`);
      return;
    }
    const approvedAt = new Date().toISOString();
    let updatedRecord: LeaveRecord | null = null;
    const nextList = leaveRecords.map((l) => {
      if (l.id === id) {
        updatedRecord = { ...l, status: 'Approved', approvedBy, approvedAt };
        return updatedRecord;
      }
      return l;
    });
    setLeaveRecords((prev) =>
      prev.map((l) => (l.id === id ? { ...l, status: 'Approved', approvedBy, approvedAt } : l))
    );
    if (updatedRecord) {
      void persistLeavesToSupabase(updatedRecord, nextList);
    }
    addAuditLog('LEAVE_APPROVED', 'HR & Payroll', `Approved leave ID ${id} by ${approvedBy}`);
  };

  const rejectLeave = (id: string, reason: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'approve_leave')) {
      console.warn('Permission denied: approve_leave required to reject leave.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to reject leave (${id}) without approve_leave permission`);
      return;
    }
    let updatedRecord: LeaveRecord | null = null;
    const nextList = leaveRecords.map((l) => {
      if (l.id === id) {
        updatedRecord = { ...l, status: 'Rejected', rejectionReason: reason };
        return updatedRecord;
      }
      return l;
    });
    setLeaveRecords((prev) =>
      prev.map((l) => (l.id === id ? { ...l, status: 'Rejected', rejectionReason: reason } : l))
    );
    if (updatedRecord) {
      void persistLeavesToSupabase(updatedRecord, nextList);
    }
    addAuditLog('LEAVE_REJECTED', 'HR & Payroll', `Rejected leave ID ${id} (Reason: ${reason})`);
  };

  const getEmployeeLeaveBalance = (employeeId: string, year: number) => {
    const yearStr = `${year}`;
    const taken = leaveRecords.filter(
      (l) => l.employeeId === employeeId && l.status === 'Approved' && l.startDate.startsWith(yearStr)
    );
    const annualTaken = taken.filter((l) => l.leaveType === 'Annual Leave').reduce((s, l) => s + l.daysCount, 0);
    const casualTaken = taken.filter((l) => l.leaveType === 'Casual Leave').reduce((s, l) => s + l.daysCount, 0);
    const sickTaken = taken.filter((l) => l.leaveType === 'Sick Leave').reduce((s, l) => s + l.daysCount, 0);
    const maternityTaken = taken.filter((l) => l.leaveType === 'Maternity Leave').reduce((s, l) => s + l.daysCount, 0);
    const unpaidTaken = taken.filter((l) => l.leaveType === 'Unpaid Leave').reduce((s, l) => s + l.daysCount, 0);
    const q = payrollSettings?.leaveQuotas || DEFAULT_PAYROLL_SETTINGS.leaveQuotas || {
      annualLeave: 14,
      casualLeave: 10,
      sickLeave: 14,
      maternityLeave: 112,
    };
    return {
      annual: { quota: q.annualLeave, taken: annualTaken, remaining: Math.max(0, q.annualLeave - annualTaken) },
      casual: { quota: q.casualLeave, taken: casualTaken, remaining: Math.max(0, q.casualLeave - casualTaken) },
      sick: { quota: q.sickLeave, taken: sickTaken, remaining: Math.max(0, q.sickLeave - sickTaken) },
      maternity: { quota: q.maternityLeave, taken: maternityTaken, remaining: Math.max(0, q.maternityLeave - maternityTaken) },
      unpaid: { quota: 0, taken: unpaidTaken, remaining: 0 },
    };
  };

  const classifyAdvanceLoansSupabaseError = (err: any): AdvanceLoansDbStatus => {
    const code = String(err?.code || '').trim();
    const message = String(err?.message || '').trim();
    const lower = message.toLowerCase();
    if (
      code === 'PGRST205' ||
      code === '42P01' ||
      lower.includes('could not find the table') ||
      lower.includes('does not exist')
    ) {
      return {
        synced: false,
        status: 'table_missing',
        error: 'Supabase table "public.employee_advances_loans" does not exist yet.',
        sqlFix: EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
      };
    }
    if (
      code === '42501' ||
      lower.includes('row-level security') ||
      lower.includes('permission denied')
    ) {
      return {
        synced: false,
        status: 'rls_blocked',
        error: `Supabase Row-Level Security blocked saving to "public.employee_advances_loans": ${message}`,
        sqlFix: EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
      };
    }
    return {
      synced: false,
      status: 'error',
      error: message || 'Failed to communicate with Supabase employee_advances_loans table.',
      sqlFix: EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
    };
  };

  const mapAdvanceLoanRowToRecord = (row: any): AdvanceLoanRecord => {
    const principal = Number(row.principal_amount_bdt) || 0;
    const repaid = Number(row.repaid_amount_bdt) || 0;
    const remaining =
      row.remaining_amount_bdt !== undefined && row.remaining_amount_bdt !== null
        ? Number(row.remaining_amount_bdt)
        : Math.max(0, principal - repaid);
    return {
      id: String(row.id),
      employeeId: row.employee_id ? String(row.employee_id) : undefined,
      fieldForceId: row.employee_id ? String(row.employee_id) : undefined,
      employeeCode: row.employee_code ? String(row.employee_code) : undefined,
      employeeName: String(row.employee_name || ''),
      loanType: (row.loan_type || 'Employee Loan') as AdvanceLoanType,
      principalAmountBDT: principal,
      repaymentTenureMonths: Math.max(1, Number(row.repayment_tenure_months) || 1),
      monthlyDeductionBDT: Number(row.monthly_deduction_bdt) || 0,
      deductionStartMonthYear: String(row.deduction_start_month_year || ''),
      repaidAmountBDT: repaid,
      remainingAmountBDT: remaining,
      purpose: row.purpose ? String(row.purpose) : undefined,
      status: (row.status || 'Pending') as AdvanceLoanRecord['status'],
      appliedDate: row.applied_date ? String(row.applied_date) : undefined,
      approvedBy: row.approved_by ? String(row.approved_by) : undefined,
      approvalDate: row.approval_date ? String(row.approval_date) : undefined,
      remarks: row.remarks ? String(row.remarks) : undefined,
      schedule: Array.isArray(row.schedule_json) ? row.schedule_json : [],
    };
  };

  const buildAdvanceLoanUpsertPayload = (loan: AdvanceLoanRecord): Record<string, any> => {
    const principal = Number(loan.principalAmountBDT ?? loan.approvedAmountBDT ?? loan.requestedAmountBDT ?? 0) || 0;
    const tenure = Math.max(1, Number(loan.repaymentTenureMonths ?? loan.installmentDurationMonths ?? 1) || 1);
    const monthly = Number(loan.monthlyDeductionBDT ?? loan.monthlyInstallmentBDT ?? Math.round(principal / tenure)) || 0;
    const repaid = Number(loan.repaidAmountBDT ?? loan.totalPaidBDT ?? 0) || 0;
    const remaining = Number(loan.remainingAmountBDT ?? loan.remainingBalanceBDT ?? Math.max(0, principal - repaid));
    return {
      id: loan.id,
      employee_id: loan.employeeId || loan.fieldForceId || '',
      employee_code: loan.employeeCode || '',
      employee_name: loan.employeeName || '',
      loan_type: loan.loanType || loan.type || 'Employee Loan',
      principal_amount_bdt: principal,
      repayment_tenure_months: tenure,
      monthly_deduction_bdt: monthly,
      deduction_start_month_year:
        loan.deductionStartMonthYear || loan.repaymentStartMonth || new Date().toISOString().slice(0, 7),
      repaid_amount_bdt: repaid,
      remaining_amount_bdt: remaining,
      purpose: loan.purpose || null,
      status: loan.status || 'Pending',
      applied_date: loan.appliedDate || loan.requestDate || new Date().toISOString().slice(0, 10),
      approved_by: loan.approvedBy || null,
      approval_date: loan.approvalDate || null,
      remarks: loan.remarks || null,
      schedule_json: Array.isArray(loan.schedule) ? loan.schedule : [],
    };
  };

  const refreshAdvanceLoans = async () => {
    const sb = getSupabase();
    if (!sb) {
      setAdvanceLoansDbStatus({
        synced: false,
        status: 'not_configured',
        error: 'Supabase client is not configured.',
        sqlFix: null,
      });
      return;
    }
    try {
      const [primaryRes, backupRes] = await Promise.all([
        sb
          .from('employee_advances_loans')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(500),
        sb
          .from('system_settings')
          .select('settings_json')
          .eq('id', 'employee_advances_loans')
          .maybeSingle(),
      ]);

      const mergedMap = new Map<string, AdvanceLoanRecord>();

      const backupList = Array.isArray((backupRes.data?.settings_json as any)?.records)
        ? ((backupRes.data!.settings_json as any).records as AdvanceLoanRecord[])
        : [];
      backupList.forEach((rec) => {
        if (rec?.id) mergedMap.set(rec.id, rec);
      });

      const primaryRows: AdvanceLoanRecord[] =
        !primaryRes.error && Array.isArray(primaryRes.data)
          ? primaryRes.data.filter((r: any) => r?.id).map(mapAdvanceLoanRowToRecord)
          : [];

      primaryRows.forEach((rec) => {
        mergedMap.set(rec.id, rec);
      });

      if (mergedMap.size > 0) {
        const list = Array.from(mergedMap.values()).sort((a, b) =>
          (b.appliedDate || b.id || '').localeCompare(a.appliedDate || a.id || '')
        );
        setAdvanceLoans(list);
      }

      if (primaryRes.error) {
        setAdvanceLoansDbStatus(classifyAdvanceLoansSupabaseError(primaryRes.error));
      } else if (backupList.length > primaryRows.length) {
        setAdvanceLoansDbStatus({
          synced: false,
          status: 'rls_blocked',
          error:
            'Some Advance/Loan records are stored in system_settings backup because direct writes to "public.employee_advances_loans" were blocked by Row-Level Security.',
          sqlFix: EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
        });
      } else if (primaryRows.length > 0) {
        setAdvanceLoansDbStatus({
          synced: true,
          status: 'synced',
          error: null,
          sqlFix: null,
        });
      }
    } catch (err) {
      console.warn('refreshAdvanceLoans notice:', err);
      setAdvanceLoansDbStatus(classifyAdvanceLoansSupabaseError(err));
    }
  };

  const persistAdvanceLoansToSupabase = async (
    recordsToPersist: AdvanceLoanRecord[],
    snapshotList: AdvanceLoanRecord[]
  ): Promise<{
    dbSynced: boolean;
    backedUp: boolean;
    syncedCount: number;
    error?: string;
    sqlFix?: string;
  }> => {
    const sb = getSupabase();
    if (!sb) {
      setAdvanceLoansDbStatus({
        synced: false,
        status: 'not_configured',
        error: 'Supabase client is not configured.',
        sqlFix: null,
      });
      return {
        dbSynced: false,
        backedUp: false,
        syncedCount: 0,
        error: 'Supabase client is not configured.',
      };
    }

    const payloads = recordsToPersist.map(buildAdvanceLoanUpsertPayload);
    try {
      let lastError: any = null;
      if (payloads.length > 0) {
        const { error } = await sb
          .from('employee_advances_loans')
          .upsert(payloads, { onConflict: 'id' });
        lastError = error;
      }

      if (!lastError) {
        setAdvanceLoansDbStatus({
          synced: true,
          status: 'synced',
          error: null,
          sqlFix: null,
        });
        try {
          await sb.from('system_settings').upsert(
            {
              id: 'employee_advances_loans',
              software_name: 'Employee Advances & Loans',
              logo_data_url: null,
              branding_json: { type: 'employee_advances_loans' },
              settings_json: { records: snapshotList.slice(0, 500) },
              updated_by: currentUser?.name || 'Admin',
              updated_at: new Date().toISOString(),
            },
            { onConflict: 'id' }
          );
        } catch {}
        return {
          dbSynced: true,
          backedUp: true,
          syncedCount: payloads.length,
        };
      }

      const primaryStatus = classifyAdvanceLoansSupabaseError(lastError);
      setAdvanceLoansDbStatus(primaryStatus);

      let backedUp = false;
      try {
        const { error: backupErr } = await sb.from('system_settings').upsert(
          {
            id: 'employee_advances_loans',
            software_name: 'Employee Advances & Loans',
            logo_data_url: null,
            branding_json: { type: 'employee_advances_loans' },
            settings_json: { records: snapshotList.slice(0, 500) },
            updated_by: currentUser?.name || 'Admin',
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'id' }
        );
        backedUp = !backupErr;
      } catch {
        backedUp = false;
      }

      return {
        dbSynced: false,
        backedUp,
        syncedCount: 0,
        error: backedUp
          ? 'Saved to Supabase backup (system_settings), but Row-Level Security blocked writing directly to "public.employee_advances_loans". Run the SQL fix below once in Supabase SQL Editor, then click Sync to Supabase.'
          : primaryStatus.error || lastError?.message || 'Failed to save loan to Supabase.',
        sqlFix: primaryStatus.sqlFix || EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
      };
    } catch (err: any) {
      const failStatus = classifyAdvanceLoansSupabaseError(err);
      setAdvanceLoansDbStatus(failStatus);
      return {
        dbSynced: false,
        backedUp: false,
        syncedCount: 0,
        error: failStatus.error || err?.message || 'Network error while saving advance/loan.',
        sqlFix: failStatus.sqlFix || EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
      };
    }
  };

  const syncAdvanceLoansToSupabase = async () => {
    const sb = getSupabase();
    const mergedMap = new Map<string, AdvanceLoanRecord>();
    if (sb) {
      try {
        const { data: backupRow } = await sb
          .from('system_settings')
          .select('settings_json')
          .eq('id', 'employee_advances_loans')
          .maybeSingle();
        const backupList = Array.isArray((backupRow?.settings_json as any)?.records)
          ? ((backupRow!.settings_json as any).records as AdvanceLoanRecord[])
          : [];
        backupList.forEach((rec) => {
          if (rec?.id) mergedMap.set(rec.id, rec);
        });
      } catch {}
    }
    advanceLoans.forEach((rec) => {
      if (rec?.id) mergedMap.set(rec.id, rec);
    });
    const allRecords = Array.from(mergedMap.values());
    if (allRecords.length === 0) {
      // Probe table write/read permission cleanly if list is empty
      if (sb) {
        const probeId = `probe-loan-${Date.now()}`;
        const { error: probeErr } = await sb.from('employee_advances_loans').upsert(
          {
            id: probeId,
            employee_id: 'probe',
            employee_code: 'PROBE',
            employee_name: 'Probe',
            loan_type: 'Employee Loan',
            principal_amount_bdt: 1,
            repayment_tenure_months: 1,
            monthly_deduction_bdt: 1,
            deduction_start_month_year: new Date().toISOString().slice(0, 7),
            repaid_amount_bdt: 0,
            remaining_amount_bdt: 1,
            status: 'Pending',
          },
          { onConflict: 'id' }
        );
        if (probeErr) {
          const st = classifyAdvanceLoansSupabaseError(probeErr);
          setAdvanceLoansDbStatus(st);
          return {
            dbSynced: false,
            backedUp: false,
            syncedCount: 0,
            error: st.error || probeErr.message,
            sqlFix: st.sqlFix || EMPLOYEE_ADVANCES_LOANS_TABLE_SQL,
          };
        }
        await sb.from('employee_advances_loans').delete().eq('id', probeId);
      }
      setAdvanceLoansDbStatus({ synced: true, status: 'synced', error: null, sqlFix: null });
      return { dbSynced: true, backedUp: true, syncedCount: 0 };
    }

    const res = await persistAdvanceLoansToSupabase(allRecords, allRecords);
    if (res.dbSynced) {
      await refreshAdvanceLoans();
    }
    return res;
  };

  const applyAdvanceLoan = async (
    loanData: Omit<AdvanceLoanRecord, 'id' | 'appliedDate' | 'status' | 'repaidAmountBDT' | 'remainingAmountBDT' | 'schedule'>
  ): Promise<{
    success: boolean;
    id?: string;
    dbSynced?: boolean;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
  }> => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to apply for employee advance/loan.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to create advance/loan without create_payroll permission`);
      return {
        success: false,
        error: 'Permission denied: Process Monthly Payroll permission is required to apply for an advance/loan.',
      };
    }
    const principal = Number(loanData.principalAmountBDT) || 0;
    const tenure = Math.max(1, Math.floor(Number(loanData.repaymentTenureMonths) || 1));
    if (principal <= 0) {
      return {
        success: false,
        error: 'Principal loan/advance amount must be greater than 0 BDT.',
      };
    }

    const id = `loan-${Date.now().toString().slice(-6)}`;
    const monthlyInstallment = Math.round(principal / tenure);
    const startMonthStr = loanData.deductionStartMonthYear || new Date().toISOString().slice(0, 7);
    const [parsedYear, parsedMonth] = startMonthStr.split('-').map(Number);
    const startYear = Number.isFinite(parsedYear) && parsedYear > 2000 ? parsedYear : new Date().getFullYear();
    const startMonth = Number.isFinite(parsedMonth) && parsedMonth >= 1 && parsedMonth <= 12 ? parsedMonth : new Date().getMonth() + 1;

    const schedule: LoanInstallmentSchedule[] = [];
    for (let i = 0; i < tenure; i++) {
      const date = new Date(startYear, startMonth - 1 + i, 1);
      const mStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      schedule.push({
        installmentNumber: i + 1,
        monthYear: mStr,
        amountBDT:
          i === tenure - 1
            ? principal - monthlyInstallment * (tenure - 1)
            : monthlyInstallment,
        status: 'Scheduled',
      });
    }

    const newRecord: AdvanceLoanRecord = {
      ...loanData,
      id,
      principalAmountBDT: principal,
      repaymentTenureMonths: tenure,
      deductionStartMonthYear: `${startYear}-${String(startMonth).padStart(2, '0')}`,
      appliedDate: new Date().toISOString().slice(0, 10),
      status: 'Pending',
      monthlyDeductionBDT: monthlyInstallment,
      repaidAmountBDT: 0,
      remainingAmountBDT: principal,
      schedule,
    };

    const nextList = [newRecord, ...advanceLoans];
    setAdvanceLoans((prev) => [newRecord, ...prev]);
    addAuditLog(
      'LOAN_APPLIED',
      'HR & Payroll',
      `${loanData.loanType} of ৳${principal.toLocaleString()} applied by ${loanData.employeeName} (${tenure} months tenure @ ৳${monthlyInstallment.toLocaleString()}/mo)`
    );

    const syncRes = await persistAdvanceLoansToSupabase([newRecord], nextList);
    return {
      success: true,
      id,
      ...syncRes,
    };
  };

  const approveAdvanceLoan = async (id: string, approvedBy?: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'approve_advance_loan')) {
      console.warn('Permission denied: approve_advance_loan required to approve advance/loan.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to approve loan (${id}) without approve_advance_loan permission`);
      return {
        success: false,
        error: 'Permission denied: Advance & Loan Approve permission is required to approve advances/loans.',
      };
    }
    const approvalDate = new Date().toISOString().slice(0, 10);
    const approver = approvedBy || currentUser?.name || 'Managing Director';
    let updatedRecord: AdvanceLoanRecord | null = null;
    const nextList = advanceLoans.map((l) => {
      if (l.id === id) {
        updatedRecord = { ...l, status: 'Approved', approvedBy: approver, approvalDate };
        return updatedRecord;
      }
      return l;
    });
    setAdvanceLoans((prev) =>
      prev.map((l) => (l.id === id ? { ...l, status: 'Approved', approvedBy: approver, approvalDate } : l))
    );
    addAuditLog('LOAN_APPROVED', 'HR & Payroll', `Approved loan ID ${id} by ${approver}`);
    if (updatedRecord) {
      const syncRes = await persistAdvanceLoansToSupabase([updatedRecord], nextList);
      return { success: true, ...syncRes };
    }
    return { success: true };
  };

  const recordLoanInstallmentDeduction = (loanId: string, installmentNumber: number, payrollRunId: string) => {
    let updatedRecord: AdvanceLoanRecord | null = null;
    const nextList = advanceLoans.map((l) => {
      if (l.id === loanId) {
        let deductedAmt = 0;
        const newSchedule = l.schedule.map((s) => {
          if (s.installmentNumber === installmentNumber && s.status !== 'Deducted') {
            deductedAmt = s.amountBDT || s.installmentAmountBDT || 0;
            return {
              ...s,
              status: 'Deducted' as const,
              deductedInPayrollId: payrollRunId,
              paidDate: new Date().toISOString().slice(0, 10),
            };
          }
          return s;
        });
        const newRepaid = (l.repaidAmountBDT || 0) + deductedAmt;
        const newRemaining = Math.max(0, (l.principalAmountBDT || 0) - newRepaid);
        const isFullyPaid = newRemaining === 0;
        updatedRecord = {
          ...l,
          repaidAmountBDT: newRepaid,
          remainingAmountBDT: newRemaining,
          status: isFullyPaid ? 'Closed' : l.status,
          schedule: newSchedule,
        };
        return updatedRecord;
      }
      return l;
    });
    setAdvanceLoans((prev) =>
      prev.map((l) => (l.id === loanId && updatedRecord ? updatedRecord : l))
    );
    if (updatedRecord) {
      void persistAdvanceLoansToSupabase([updatedRecord], nextList);
    }
  };

  const earlySettleAdvanceLoan = async (id: string, paymentMethod: string, notes?: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'disburse')) {
      console.warn('Permission denied: disburse required to settle employee advance/loan.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted early loan settlement (${id}) without disburse permission`);
      return {
        success: false,
        error: 'Permission denied: Disburse Salary Payments permission is required to settle loans.',
      };
    }
    const today = new Date().toISOString().slice(0, 10);
    let updatedRecord: AdvanceLoanRecord | null = null;
    const nextList = advanceLoans.map((l) => {
      if (l.id === id) {
        const settlementAmount = l.remainingAmountBDT ?? l.remainingBalanceBDT ?? 0;
        const updatedSchedule = l.schedule.map((s) => ({
          ...s,
          status: s.status === 'Scheduled' ? ('Deducted' as const) : s.status,
          paidDate: s.paidDate || today,
        }));

        // Post cash book inflow
        const lastCash = cashBook[cashBook.length - 1];
        const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
        const cashEntry: CashBookEntry = {
          id: `cash-ln-${Date.now()}`,
          date: today,
          voucherNo: `CB-LN-${Date.now().toString().slice(-4)}`,
          accountType: (paymentMethod as any) || 'City Bank PLC',
          transactionCategory: 'Other Receipt',
          description: `Early loan settlement: ${l.loanType} for ${l.employeeName} (${l.employeeCode})`,
          reference: `LOAN-${l.id}`,
          cashInBDT: settlementAmount,
          cashOutBDT: 0,
          runningBalanceBDT: prevBal + settlementAmount,
        };
        setCashBook((cb) => [...cb, cashEntry]);

        updatedRecord = {
          ...l,
          repaidAmountBDT: l.principalAmountBDT,
          remainingAmountBDT: 0,
          status: 'Settled',
          remarks: `${l.remarks || ''} [Early settled ৳${settlementAmount.toLocaleString()} via ${paymentMethod} on ${today} ${notes || ''}]`.trim(),
          schedule: updatedSchedule,
        };
        return updatedRecord;
      }
      return l;
    });

    setAdvanceLoans((prev) =>
      prev.map((l) => (l.id === id && updatedRecord ? updatedRecord : l))
    );
    addAuditLog('LOAN_EARLY_SETTLED', 'HR & Payroll', `Early settled loan ${id}`);
    if (updatedRecord) {
      const syncRes = await persistAdvanceLoansToSupabase([updatedRecord], nextList);
      return { success: true, ...syncRes };
    }
    return { success: true };
  };

  const addOvertimeRecord = (ot: Omit<OvertimeRecord, 'id' | 'status'>): string => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to log payroll overtime.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to log overtime without create_payroll permission`);
      return '';
    }
    const id = `ot-${Date.now().toString().slice(-6)}-${Math.random().toString(36).substring(2, 5)}`;
    const newOt: OvertimeRecord = { ...ot, id, status: 'Pending' };
    setOvertimeRecords((prev) => [newOt, ...prev]);
    addAuditLog('OVERTIME_LOGGED', 'HR & Payroll', `Overtime logged for ${ot.employeeName}: ${ot.hours} hrs @ ৳${ot.ratePerHourBDT}/hr`);
    const sb = getSupabase();
    if (sb) {
      sb.from('employee_overtimes')
        .upsert({
          id: newOt.id,
          employee_id: String(newOt.employeeId || newOt.fieldForceId || ''),
          employee_code: newOt.employeeCode || '',
          employee_name: newOt.employeeName,
          date: newOt.date,
          month_year: newOt.monthYear || String(newOt.date).slice(0, 7),
          hours: Number(newOt.hours) || 0,
          rate_per_hour_bdt: Number(newOt.ratePerHourBDT) || 0,
          total_amount_bdt: Number(newOt.totalAmountBDT) || 0,
          reason: newOt.reason || '',
          status: 'Pending',
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase employee_overtimes insert failed:', error.message);
        });
    }
    return id;
  };

