  // --------------------------------------------------------------------------
  // Complete Overtime Management Module Implementation (with Supabase Sync)
  // --------------------------------------------------------------------------
  const addOvertimeAuditLog = (log: Omit<OvertimeAuditTrail, 'id' | 'timestamp'>) => {
    const newLog: OvertimeAuditTrail = {
      ...log,
      id: `ot-aud-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      timestamp: new Date().toISOString(),
    };
    setOvertimeAuditLogs((prev) => [newLog, ...prev]);
    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_audit_logs')
        .insert({
          id: newLog.id,
          record_id: newLog.recordId,
          record_type: newLog.recordType,
          action: newLog.action,
          actor_id: newLog.actorId || currentUser?.id || null,
          actor_name: newLog.actorName,
          actor_role: newLog.actorRole,
          timestamp: newLog.timestamp,
          details: newLog.details,
          previous_state: newLog.previousState || null,
          new_state: newLog.newState || null,
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase overtime_audit_logs insert failed:', error.message);
        });
    }
  };

  const getEmployeeEffectiveOvertimePolicy = (employeeId: string, forDate?: string): EmployeeOvertimePolicy => {
    const emp = fieldForceReps.find((r) => r.id === employeeId || r.code === employeeId);
    const dateToCheck = forDate || new Date().toISOString().substring(0, 10);

    // 1. Check historical policy versions for a match by effective date window
    if (emp?.overtimePolicyHistory && Array.isArray(emp.overtimePolicyHistory) && emp.overtimePolicyHistory.length > 0) {
      const historicalMatch = emp.overtimePolicyHistory.find((p) => {
        const afterFrom = !p.effectiveFrom || p.effectiveFrom <= dateToCheck;
        const beforeTo = !p.effectiveTo || p.effectiveTo >= dateToCheck;
        return afterFrom && beforeTo;
      });
      if (historicalMatch) {
        return {
          ...historicalMatch,
          employeeId: emp.id,
          employeeCode: emp.code,
          employeeName: emp.name,
          department: emp.department,
        };
      }
    }

    // 2. Return the employee's configured individual policy
    if (emp) {
      return {
        id: `pol-${emp.id}`,
        employeeId: emp.id,
        employeeCode: emp.code,
        employeeName: emp.name,
        department: emp.department,
        isEligible: emp.isOvertimeEligible !== undefined ? Boolean(emp.isOvertimeEligible) : true,
        calculationBasis: (emp.overtimeCalculationBasis as OvertimeCalculationBasis) || 'Basic Salary',
        standardMonthlyWorkingHours: Number(emp.overtimeStandardMonthlyHours) || 208,
        overtimeMultiplier:
          emp.overtimeMultiplier !== undefined && emp.overtimeMultiplier !== null && !Number.isNaN(Number(emp.overtimeMultiplier))
            ? Number(emp.overtimeMultiplier)
            : 2.0,
        fixedHourlyRateBDT: Number(emp.overtimeFixedHourlyRateBDT) || 0,
        effectiveFrom: emp.overtimePolicyEffectiveFrom || emp.joiningDate || '2026-01-01',
        status: (emp.overtimePolicyStatus as any) || (emp.isActive === false ? 'Inactive' : 'Active'),
        notes: emp.overtimePolicyNotes || 'Configured via Field Force Master',
        createdAt: emp.joiningDate || new Date().toISOString(),
      };
    }

    // 3. Fallback standard individual policy (no global dependency)
    return {
      id: 'pol-default',
      employeeId,
      isEligible: true,
      calculationBasis: 'Basic Salary',
      standardMonthlyWorkingHours: 208,
      overtimeMultiplier: 2.0,
      fixedHourlyRateBDT: 0,
      effectiveFrom: '2026-01-01',
      status: 'Active',
      createdAt: new Date().toISOString(),
    };
  };

  const updateEmployeeOvertimePolicy = (
    employeeId: string,
    policyUpdates: Partial<EmployeeOvertimePolicy>,
    amendmentNotes?: string
  ) => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_policies') ||
      !hasPageAction(currentUser, 'overtime-management', 'configure_policy')
    ) {
      console.warn('Permission denied: view_policies & configure_policy required to amend employee overtime policy.');
      return;
    }
    const emp = fieldForceReps.find((r) => r.id === employeeId || r.code === employeeId);
    if (!emp) return;

    const now = new Date().toISOString();
    const todayStr = now.substring(0, 10);

    // Archive current policy snapshot into version history to preserve historical calculations
    const previousSnapshot = {
      id: `pol-hist-${Date.now()}-${Math.random().toString(36).substring(2, 5)}`,
      employeeId: emp.id,
      isEligible: emp.isOvertimeEligible !== undefined ? Boolean(emp.isOvertimeEligible) : true,
      calculationBasis: (emp.overtimeCalculationBasis as OvertimeCalculationBasis) || 'Basic Salary',
      standardMonthlyWorkingHours: Number(emp.overtimeStandardMonthlyHours) || 208,
      overtimeMultiplier:
        emp.overtimeMultiplier !== undefined && emp.overtimeMultiplier !== null && !Number.isNaN(Number(emp.overtimeMultiplier))
          ? Number(emp.overtimeMultiplier)
          : 2.0,
      fixedHourlyRateBDT: Number(emp.overtimeFixedHourlyRateBDT) || 0,
      effectiveFrom: emp.overtimePolicyEffectiveFrom || emp.joiningDate || '2026-01-01',
      effectiveTo: todayStr,
      status: (emp.overtimePolicyStatus as any) || 'Active',
      notes: amendmentNotes || 'Historical policy snapshot archived upon policy amendment',
      createdAt: now,
      updatedBy: currentUser.name,
    };

    const newHistory = [previousSnapshot, ...(emp.overtimePolicyHistory || [])];

    const updatedFields: Partial<FieldForceRep> = {
      isOvertimeEligible: policyUpdates.isEligible !== undefined ? policyUpdates.isEligible : emp.isOvertimeEligible,
      overtimeCalculationBasis: policyUpdates.calculationBasis || emp.overtimeCalculationBasis || 'Basic Salary',
      overtimeStandardMonthlyHours: policyUpdates.standardMonthlyWorkingHours ?? emp.overtimeStandardMonthlyHours ?? 208,
      overtimeMultiplier: policyUpdates.overtimeMultiplier ?? emp.overtimeMultiplier ?? 2.0,
      overtimeFixedHourlyRateBDT: policyUpdates.fixedHourlyRateBDT ?? emp.overtimeFixedHourlyRateBDT ?? 0,
      overtimePolicyEffectiveFrom: policyUpdates.effectiveFrom || todayStr,
      overtimePolicyStatus: policyUpdates.status || emp.overtimePolicyStatus || 'Active',
      overtimePolicyNotes: amendmentNotes || policyUpdates.notes || emp.overtimePolicyNotes,
      overtimePolicyHistory: newHistory,
    };

    updateFieldForceRep(emp.id, updatedFields);

    addOvertimeAuditLog({
      recordId: emp.id,
      recordType: 'POLICY',
      action: 'INDIVIDUAL_POLICY_AMENDED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Amended Overtime Policy for ${emp.name} (${emp.code}): Multiplier=${updatedFields.overtimeMultiplier}x, Basis=${updatedFields.overtimeCalculationBasis}, Divisor=${updatedFields.overtimeStandardMonthlyHours}h. Effective: ${updatedFields.overtimePolicyEffectiveFrom}`,
      previousState: `Old Multiplier: ${previousSnapshot.overtimeMultiplier}x, Basis: ${previousSnapshot.calculationBasis}`,
      newState: `New Multiplier: ${updatedFields.overtimeMultiplier}x, Basis: ${updatedFields.overtimeCalculationBasis}`,
    });

    addAuditLog('OVERTIME_POLICY_AMENDED', 'Field Force Master', `Overtime Policy updated for employee ${emp.name} (${emp.code})`);
  };

  const createOvertimeRequest = (req: Partial<OvertimeRequest>): OvertimeRequest => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_requests') ||
      !hasPageAction(currentUser, 'overtime-management', 'create_request')
    ) {
      console.warn('Permission denied: view_requests & create_request required to create overtime request.');
      return {
        id: '',
        requestNumber: '',
        employeeId: req.employeeId || '',
        employeeCode: req.employeeCode || '',
        employeeName: req.employeeName || '',
        department: req.department || '',
        designation: req.designation || '',
        overtimeDate: req.overtimeDate || '',
        purposeCategory: req.purposeCategory || 'Direct Production',
        projectPurpose: req.projectPurpose || '',
        expectedStartTime: req.expectedStartTime || '',
        expectedEndTime: req.expectedEndTime || '',
        expectedHours: 0,
        overtimeReason: req.overtimeReason || '',
        requestedBy: currentUser.name,
        requestedAt: new Date().toISOString(),
        status: 'Pending Supervisor',
        hourlyRateBDT: 0,
        overtimeMultiplier: 0,
        calculatedOvertimeAmountBDT: 0,
        batchAllocations: [],
        isPayrollProcessed: false,
        isCostingAllocated: false,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
    }
    const emp = fieldForceReps.find((r) => r.id === req.employeeId || r.code === req.employeeCode);
    const otDate = req.overtimeDate || new Date().toISOString().substring(0, 10);
    const resolvedEmpId = req.employeeId || emp?.id || '';
    const resolvedEmpCode = req.employeeCode || emp?.code || 'EMP-000';

    // Enforce unique employee + attendance date validation across manual & automated requests
    const duplicateExisting = findDuplicateOvertimeRequest(
      overtimeRequests,
      resolvedEmpId,
      resolvedEmpCode,
      otDate
    );
    if (duplicateExisting) {
      console.warn(
        `Duplicate overtime request blocked for employee ${resolvedEmpCode} on ${otDate}. Existing: ${duplicateExisting.requestNumber}`
      );
      return duplicateExisting;
    }

    const existingMax = overtimeRequests.reduce((max, r) => {
      const m = String(r.requestNumber || '').match(/(\d+)$/);
      const num = m ? parseInt(m[1], 10) : 0;
      return num > max ? num : max;
    }, 0);
    const nextSeq = Math.max(existingMax + 1, overtimeRequests.length + 1);
    const reqNum = `OTR-${new Date().getFullYear()}-${String(nextSeq).padStart(3, '0')}`;
    const id = `otr-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`;

    const str = salaryStructures.find((s) => s.employeeId === req.employeeId || s.employeeId === emp?.id);
    const basic = str ? str.basicSalaryBDT : (emp?.basicSalaryBDT || 25000);
    const gross = str ? str.grossSalaryBDT : (emp?.basicSalaryBDT ? emp.basicSalaryBDT * 1.6 : 40000);

    // Retrieve employee's assigned individual overtime policy for the overtime date
    const policy = getEmployeeEffectiveOvertimePolicy(resolvedEmpId, otDate);

    // Calculate according to individual employee's policy
    const expHours = req.expectedHours || calculateNetOvertimeHours(req.expectedStartTime || '18:00', req.expectedEndTime || '22:00', 0);
    const calc = calculateEmployeeIndividualOvertime(basic, policy, expHours);

    const hourly = calc.hourlyRate;
    const mult = calc.multiplier;
    const calcAmt = calc.totalAmountBDT;
    const nowIso = new Date().toISOString();
    const sourceType = req.sourceType || 'MANUAL';

    const newRequest: OvertimeRequest = {
      id,
      requestNumber: reqNum,
      employeeId: resolvedEmpId,
      employeeCode: resolvedEmpCode,
      employeeName: req.employeeName || emp?.name || 'Staff Member',
      department: req.department || emp?.department || 'Manufacturing & Assembly',
      designation: req.designation || emp?.designation || 'Technician',
      employeeCategory: req.employeeCategory || emp?.employeeCategory || 'Factory Employee',
      overtimeDate: otDate,
      purposeCategory: req.purposeCategory || 'Direct Production',
      productionOrderId: req.productionOrderId,
      productionOrderNumber: req.productionOrderNumber,
      productionBatchNumber: req.productionBatchNumber,
      productName: req.productName,
      projectPurpose:
        req.projectPurpose !== undefined
          ? req.projectPurpose
          : sourceType === 'QR_ATTENDANCE_AUTO'
          ? ''
          : 'Assembly line overtime quota',
      sourceType,
      requisitionId: req.requisitionId || undefined,
      requisitionNumber: req.requisitionNumber || undefined,
      purposeId: req.purposeId,
      expectedStartTime: req.expectedStartTime || '18:00',
      expectedEndTime: req.expectedEndTime || '22:00',
      expectedHours: expHours,
      overtimeReason: req.overtimeReason || 'Urgent production order fulfillment',
      requestedBy: req.requestedBy || currentUser.name,
      requestedAt: nowIso,
      status: 'Pending Supervisor',
      basicSalaryBDT: basic,
      grossSalaryBDT: gross,
      hourlyRateBDT: hourly,
      overtimeMultiplier: mult,
      calculatedOvertimeAmountBDT: calcAmt,
      batchAllocations: req.batchAllocations || [],
      isPayrollProcessed: false,
      isCostingAllocated: false,
      createdAt: nowIso,
      updatedAt: nowIso,
    };

    setOvertimeRequests((prev) => [newRequest, ...prev]);

    const sb = getSupabase();
    if (sb) {
      const dbInsert: Record<string, any> = {
        id: newRequest.id,
        request_number: newRequest.requestNumber,
        employee_id: newRequest.employeeId,
        employee_code: newRequest.employeeCode,
        employee_name: newRequest.employeeName,
        department: newRequest.department,
        designation: newRequest.designation,
        employee_category: newRequest.employeeCategory || 'Factory Employee',
        overtime_date: newRequest.overtimeDate,
        purpose_category: newRequest.purposeCategory,
        production_order_id: newRequest.productionOrderId || null,
        production_order_number: newRequest.productionOrderNumber || null,
        production_batch_number: newRequest.productionBatchNumber || null,
        product_name: newRequest.productName || null,
        project_purpose: newRequest.projectPurpose,
        source_type: newRequest.sourceType || 'MANUAL',
        requisition_id: newRequest.requisitionId || null,
        requisition_number: newRequest.requisitionNumber || null,
        purpose_id: newRequest.purposeId || null,
        expected_start_time: newRequest.expectedStartTime,
        expected_end_time: newRequest.expectedEndTime,
        expected_hours: newRequest.expectedHours,
        overtime_reason: newRequest.overtimeReason,
        requested_by: newRequest.requestedBy,
        requested_at: newRequest.requestedAt,
        status: newRequest.status,
        basic_salary_bdt: newRequest.basicSalaryBDT || 0,
        hourly_rate_bdt: newRequest.hourlyRateBDT || 0,
        overtime_multiplier: newRequest.overtimeMultiplier ?? 2.0,
        calculated_overtime_amount_bdt: newRequest.calculatedOvertimeAmountBDT || 0,
        is_payroll_processed: false,
        is_costing_allocated: false,
        created_at: newRequest.createdAt,
        updated_at: newRequest.updatedAt,
      };
      (async () => {
        for (let attempt = 0; attempt < 6; attempt++) {
          const { error } = await sb.from('overtime_requests').upsert(dbInsert);
          if (!error) {
            if (newRequest.batchAllocations.length > 0) {
              await sb.from('overtime_batch_allocations').insert(
                newRequest.batchAllocations.map((a) => ({
                  id: a.id,
                  request_id: newRequest.id,
                  production_order_id: a.productionOrderId || null,
                  production_order_number: a.productionOrderNumber,
                  production_batch_number: a.productionBatchNumber,
                  product_id: a.productId || null,
                  product_name: a.productName,
                  process_type: a.processType,
                  allocated_hours: Number(a.allocatedHours) || 0,
                  hourly_rate_bdt: Number(a.hourlyRateBDT) || 0,
                  allocated_cost_bdt: Number(a.allocatedCostBDT) || 0,
                  is_overhead: Boolean(a.isOverhead),
                  notes: a.notes || null,
                }))
              );
            }
            return;
          }
          const msg = String(error.message || '');
          const missingCol =
            error.code === 'PGRST204' || msg.includes('schema cache')
              ? msg.match(/Could not find the '([^']+)' column/i)?.[1]
              : error.code === '42703' || msg.toLowerCase().includes('does not exist')
              ? msg.match(/column\s+"([^"]+)"/i)?.[1] ||
                msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1]
              : null;
          if (missingCol && Object.prototype.hasOwnProperty.call(dbInsert, missingCol)) {
            delete dbInsert[missingCol];
            continue;
          }
          console.warn('Supabase overtime_requests insert failed:', error.message);
          return;
        }
      })();
    }

    addOvertimeAuditLog({
      recordId: id,
      recordType: 'REQUEST',
      action: 'CREATED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Created overtime request ${reqNum} for ${newRequest.employeeName} (${expHours} hrs, rate ৳${hourly}/hr × ${mult}x = ৳${calcAmt}) using individual policy (Basis: ${policy.calculationBasis}, Divisor: ${policy.standardMonthlyWorkingHours}h)`,
      newState: 'Pending Supervisor',
    });
    addAuditLog('OVERTIME_REQUEST_CREATED', 'Overtime Hub', `Created OT request ${reqNum} for ${newRequest.employeeName}`);
    return newRequest;
  };

  const updateOvertimeRequest = (id: string, updates: Partial<OvertimeRequest>) => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_requests') ||
      !hasPageAction(currentUser, 'overtime-management', 'edit_request')
    ) {
      console.warn('Permission denied: view_requests & edit_request required to modify overtime requests.');
      return;
    }
    const target = overtimeRequests.find((r) => r.id === id);
    if (!target) return;
    if (target.isPayrollProcessed || target.status === 'Final Approved' || target.status === 'Rejected') {
      console.warn('Cannot edit finalized, rejected, or payroll-processed overtime requests.');
      return;
    }
    const nowIso = new Date().toISOString();
    setOvertimeRequests((prev) =>
      prev.map((r) => (r.id === id ? { ...r, ...updates, updatedAt: nowIso } : r))
    );
    const sb = getSupabase();
    if (sb) {
      const dbPatch: any = { updated_at: nowIso };
      if (updates.status !== undefined) dbPatch.status = updates.status;
      if (updates.employeeId !== undefined) dbPatch.employee_id = updates.employeeId;
      if (updates.employeeCode !== undefined) dbPatch.employee_code = updates.employeeCode;
      if (updates.employeeName !== undefined) dbPatch.employee_name = updates.employeeName;
      if (updates.department !== undefined) dbPatch.department = updates.department;
      if (updates.designation !== undefined) dbPatch.designation = updates.designation;
      if (updates.overtimeDate !== undefined) dbPatch.overtime_date = updates.overtimeDate;
      if (updates.purposeCategory !== undefined) dbPatch.purpose_category = updates.purposeCategory;
      if (updates.productionOrderId !== undefined) dbPatch.production_order_id = updates.productionOrderId || null;
      if (updates.productionOrderNumber !== undefined) dbPatch.production_order_number = updates.productionOrderNumber || null;
      if (updates.productionBatchNumber !== undefined) dbPatch.production_batch_number = updates.productionBatchNumber || null;
      if (updates.productName !== undefined) dbPatch.product_name = updates.productName || null;
      if (updates.expectedStartTime !== undefined) dbPatch.expected_start_time = updates.expectedStartTime;
      if (updates.expectedEndTime !== undefined) dbPatch.expected_end_time = updates.expectedEndTime;
      if (updates.expectedHours !== undefined) dbPatch.expected_hours = updates.expectedHours;
      if (updates.actualOvertimeHours !== undefined) dbPatch.actual_overtime_hours = updates.actualOvertimeHours;
      if (updates.basicSalaryBDT !== undefined) dbPatch.basic_salary_bdt = updates.basicSalaryBDT;
      if (updates.hourlyRateBDT !== undefined) dbPatch.hourly_rate_bdt = updates.hourlyRateBDT;
      if (updates.overtimeMultiplier !== undefined) dbPatch.overtime_multiplier = updates.overtimeMultiplier;
      if (updates.calculatedOvertimeAmountBDT !== undefined) dbPatch.calculated_overtime_amount_bdt = updates.calculatedOvertimeAmountBDT;
      if (updates.overtimeReason !== undefined) dbPatch.overtime_reason = updates.overtimeReason;
      if (updates.projectPurpose !== undefined) dbPatch.project_purpose = updates.projectPurpose;
      if (updates.requisitionId !== undefined) dbPatch.requisition_id = updates.requisitionId || null;
      if (updates.requisitionNumber !== undefined) dbPatch.requisition_number = updates.requisitionNumber || null;
      if (updates.isPayrollProcessed !== undefined) dbPatch.is_payroll_processed = updates.isPayrollProcessed;
      if (updates.payrollRunId !== undefined) dbPatch.payroll_run_id = updates.payrollRunId;
      if (updates.payrollMonth !== undefined) dbPatch.payroll_month = updates.payrollMonth;
      (async () => {
        let updateOk = false;
        for (let attempt = 0; attempt < 6; attempt++) {
          const { error } = await sb.from('overtime_requests').update(dbPatch).eq('id', id);
          if (!error) {
            updateOk = true;
            break;
          }
          const msg = String(error.message || '');
          const missingCol =
            error.code === 'PGRST204' || msg.includes('schema cache')
              ? msg.match(/Could not find the '([^']+)' column/i)?.[1]
              : error.code === '42703' || msg.toLowerCase().includes('does not exist')
              ? msg.match(/column\s+"([^"]+)"/i)?.[1] ||
                msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1]
              : null;
          if (missingCol && Object.prototype.hasOwnProperty.call(dbPatch, missingCol)) {
            delete dbPatch[missingCol];
            continue;
          }
          console.warn('Supabase overtime_requests update failed:', error.message);
          return;
        }
        if (updateOk && Array.isArray(updates.batchAllocations)) {
          await sb.from('overtime_batch_allocations').delete().eq('request_id', id);
          if (updates.batchAllocations.length > 0) {
            await sb.from('overtime_batch_allocations').insert(
              updates.batchAllocations.map((a) => ({
                id: a.id,
                request_id: id,
                production_order_id: a.productionOrderId || null,
                production_order_number: a.productionOrderNumber,
                production_batch_number: a.productionBatchNumber,
                product_id: a.productId || null,
                product_name: a.productName,
                process_type: a.processType,
                allocated_hours: Number(a.allocatedHours) || 0,
                hourly_rate_bdt: Number(a.hourlyRateBDT) || 0,
                allocated_cost_bdt: Number(a.allocatedCostBDT) || 0,
                is_overhead: Boolean(a.isOverhead),
                notes: a.notes || null,
              }))
            );
          }
        }
      })();
    }
    addOvertimeAuditLog({
      recordId: id,
      recordType: 'REQUEST',
      action: 'UPDATED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Updated overtime request ${target.requestNumber}`,
    });
  };

  const deleteOvertimeRequest = (id: string) => {
    const target = overtimeRequests.find((r) => r.id === id);
    if (!target) return;
    const canViewReqs = hasPageAction(currentUser, 'overtime-management', 'view_requests');
    const canEdit = hasPageAction(currentUser, 'overtime-management', 'edit_request');
    const canFinal = hasPageAction(currentUser, 'overtime-management', 'approve_final');
    const isFinalOrRejected = target.status === 'Final Approved' || target.status === 'Rejected';
    if (!canViewReqs || (isFinalOrRejected ? !canFinal : !canEdit && !canFinal)) {
      console.warn('Permission denied: insufficient clearance to delete this overtime request.');
      return;
    }
    if (target.isPayrollProcessed) {
      console.warn('Cannot delete overtime request that has already been processed in payroll.');
      return;
    }
    setOvertimeRequests((prev) => prev.filter((r) => r.id !== id));
    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_requests').delete().eq('id', id).then(({ error }) => {
        if (error) console.warn('Supabase overtime_requests delete failed:', error.message);
      });
    }
    addOvertimeAuditLog({
      recordId: id,
      recordType: 'REQUEST',
      action: 'DELETED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Deleted overtime request ${target.requestNumber}`,
    });
    addAuditLog('OVERTIME_REQUEST_DELETED', 'Overtime Hub', `Deleted OT request ${target.requestNumber}`);
  };

  const deduplicateOvertimeRequisitions = (rows: OvertimeRequisition[]): OvertimeRequisition[] => {
    const byId = new Map<string, OvertimeRequisition>();
    for (const r of rows) {
      if (r && r.id) {
        byId.set(String(r.id), r);
      }
    }
    return Array.from(byId.values()).sort((a, b) =>
      String(b.submittedAt || b.createdAt).localeCompare(String(a.submittedAt || a.createdAt))
    );
  };

  const fetchOvertimeRequisitionApi = async (
    url: string,
    init?: Omit<RequestInit, 'headers'>
  ): Promise<Response> => {
    const initialResp = await fetch(url, {
      ...init,
      cache: 'no-store',
      headers: getErpAuthHeaders(),
    });
    if (initialResp.status === 401 && currentUser?.id && currentUser.id !== 'guest') {
      const freshToken = await establishServerSession(currentUser);
      if (freshToken) {
        return fetch(url, {
          ...init,
          cache: 'no-store',
          headers: getErpAuthHeaders(freshToken),
        });
      }
    }
    return initialResp;
  };

  const parseOvertimeRequisitionApiResponse = async (
    resp: Response
  ): Promise<{ isJsonApi: boolean; data: any }> => {
    const contentType = String(resp.headers.get('content-type') || '').toLowerCase();
    const rawText = await resp.text().catch(() => '');
    const parsed = tryParseJsonSafe(rawText);
    const isJsonApi = contentType.includes('application/json') && parsed.ok && parsed.data && typeof parsed.data === 'object';
    return { isJsonApi, data: isJsonApi ? parsed.data : {} };
  };

  const shouldFallbackToDirectSupabaseRequisition = (resp: Response, isJsonApi: boolean): boolean => {
    if (!isJsonApi) return true;
    return [404, 405, 502, 503, 504].includes(resp.status);
  };

  const refreshOvertimeRequisitions = async (): Promise<{ success: boolean; error?: string }> => {
    purgeOvertimeRequisitionLocalSessionMemory();
    if (!currentUser?.id || currentUser.id === 'guest') {
      setOvertimeRequisitions([]);
      setGrantedOvertimeRequisitions([]);
      return { success: false, error: 'User authentication is required to load overtime requisitions.' };
    }
    const sb = getSupabase();
    const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;

    if (usingCustomSupabase && sb) {
      const direct = await refreshOvertimeRequisitionsDirect(sb, currentUser);
      if (direct.success) {
        setOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.requisitions));
        setGrantedOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.grantedRequisitions));
        return { success: true };
      }
      setOvertimeRequisitions([]);
      setGrantedOvertimeRequisitions([]);
      return { success: false, error: direct.error };
    }

    try {
      const [mainResp, grantedResp] = await Promise.all([
        fetchOvertimeRequisitionApi('/api/overtime/requisitions'),
        fetchOvertimeRequisitionApi('/api/overtime/requisitions?grantedOnly=1'),
      ]);

      const [mainParsed, grantedParsed] = await Promise.all([
        parseOvertimeRequisitionApiResponse(mainResp),
        parseOvertimeRequisitionApiResponse(grantedResp),
      ]);

      if (
        (shouldFallbackToDirectSupabaseRequisition(mainResp, mainParsed.isJsonApi) ||
          shouldFallbackToDirectSupabaseRequisition(grantedResp, grantedParsed.isJsonApi)) &&
        sb
      ) {
        const direct = await refreshOvertimeRequisitionsDirect(sb, currentUser);
        if (direct.success) {
          setOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.requisitions));
          setGrantedOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.grantedRequisitions));
          return { success: true };
        }
        setOvertimeRequisitions([]);
        setGrantedOvertimeRequisitions([]);
        return { success: false, error: direct.error };
      }

      let mainError: string | undefined;

      if (mainResp.ok && mainParsed.isJsonApi) {
        if (Array.isArray(mainParsed.data?.requisitions)) {
          setOvertimeRequisitions(deduplicateOvertimeRequisitions(mainParsed.data.requisitions));
        } else {
          setOvertimeRequisitions([]);
        }
      } else {
        setOvertimeRequisitions([]);
        if (mainResp.status !== 403) {
          mainError =
            mainParsed.data?.error || `Failed to load overtime requisitions (HTTP ${mainResp.status}).`;
        }
      }

      if (grantedResp.ok && grantedParsed.isJsonApi) {
        if (Array.isArray(grantedParsed.data?.requisitions)) {
          setGrantedOvertimeRequisitions(deduplicateOvertimeRequisitions(grantedParsed.data.requisitions));
        } else {
          setGrantedOvertimeRequisitions([]);
        }
      } else {
        setGrantedOvertimeRequisitions([]);
      }

      if (mainError) {
        return { success: false, error: mainError };
      }
      return { success: true };
    } catch (err: any) {
      if (sb) {
        const direct = await refreshOvertimeRequisitionsDirect(sb, currentUser);
        if (direct.success) {
          setOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.requisitions));
          setGrantedOvertimeRequisitions(deduplicateOvertimeRequisitions(direct.grantedRequisitions));
          return { success: true };
        }
      }
      const msg = err?.message || 'Network error while fetching overtime requisitions from Supabase.';
      console.warn('Unable to refresh overtime requisitions:', err);
      return { success: false, error: msg };
    }
  };

  const clearOvertimeRequisitionsLocalData = async (): Promise<{ success: boolean; error?: string }> => {
    purgeOvertimeRequisitionLocalSessionMemory();
    setOvertimeRequisitions([]);
    setGrantedOvertimeRequisitions([]);
    return refreshOvertimeRequisitions();
  };

  const createOvertimeRequisition = async (payload: {
    overtimeDate: string;
    requiredWorkers: number;
    requestedHours: number;
    purposes: Array<Partial<OvertimeRequisitionPurposeItem> | string>;
    remarks?: string;
  }) => {
    const sb = getSupabase();
    const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;

    const finalizeCreated = async (created: OvertimeRequisition) => {
      setOvertimeRequisitions((prev) =>
        deduplicateOvertimeRequisitions([created, ...prev.filter((r) => r.id !== created.id)])
      );
      addOvertimeAuditLog({
        recordId: created.id,
        recordType: 'REQUEST',
        action: 'REQUISITION_SUBMITTED',
        actorName: currentUser.name,
        actorRole: currentUser.role,
        details: `Submitted Overtime Requisition ${created.requisitionNumber} for ${created.overtimeDate}: ${created.requiredWorkers} workers × ${created.requestedHours}h (${created.purpose})`,
        newState: created.status,
      });
      addAuditLog('OVERTIME_REQUISITION_SUBMITTED', 'Overtime Requisition', `Submitted ${created.requisitionNumber}`);
      await refreshOvertimeRequisitions();
      return {
        success: true,
        requisition: created,
        dbSynced: true,
      };
    };

    if (usingCustomSupabase && sb) {
      const directRes = await createOvertimeRequisitionDirect(sb, payload, currentUser);
      if (directRes.success && directRes.dbSynced && directRes.requisition) {
        return finalizeCreated(directRes.requisition);
      }
      return {
        success: false,
        dbSynced: false,
        error: directRes.error || 'Failed to save overtime requisition in Supabase.',
      };
    }

    try {
      const resp = await fetchOvertimeRequisitionApi('/api/overtime/requisitions', {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      const { isJsonApi, data } = await parseOvertimeRequisitionApiResponse(resp);

      if (shouldFallbackToDirectSupabaseRequisition(resp, isJsonApi) && sb) {
        const directRes = await createOvertimeRequisitionDirect(sb, payload, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeCreated(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || 'Failed to save overtime requisition in Supabase.',
        };
      }

      if (!resp.ok || data?.success !== true || data?.dbSynced !== true || !data?.requisition) {
        return {
          success: false,
          dbSynced: false,
          error:
            data?.error ||
            data?.dbError ||
            'Failed to save overtime requisition in Supabase. Please try again.',
        };
      }
      return finalizeCreated(data.requisition as OvertimeRequisition);
    } catch (err: any) {
      if (sb) {
        const directRes = await createOvertimeRequisitionDirect(sb, payload, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeCreated(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || err?.message || 'Failed to save overtime requisition in Supabase.',
        };
      }
      return {
        success: false,
        dbSynced: false,
        error: err?.message || 'Network error while submitting overtime requisition.',
      };
    }
  };

  const updateOvertimeRequisition = async (
    id: string,
    payload: {
      overtimeDate: string;
      requiredWorkers: number;
      requestedHours: number;
      purposes: Array<Partial<OvertimeRequisitionPurposeItem> | string>;
      remarks?: string;
    }
  ) => {
    const sb = getSupabase();
    const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;

    const finalizeUpdated = async (updated: OvertimeRequisition) => {
      setOvertimeRequisitions((prev) =>
        deduplicateOvertimeRequisitions(prev.map((r) => (r.id === updated.id ? updated : r)))
      );
      addOvertimeAuditLog({
        recordId: updated.id,
        recordType: 'REQUEST',
        action: 'REQUISITION_RESUBMITTED',
        actorName: currentUser.name,
        actorRole: currentUser.role,
        details: `Corrected & resubmitted ${updated.requisitionNumber} for ${updated.overtimeDate}: ${updated.requiredWorkers} workers × ${updated.requestedHours}h`,
        previousState: 'Returned for Correction',
        newState: updated.status,
      });
      addAuditLog('OVERTIME_REQUISITION_RESUBMITTED', 'Overtime Requisition', `Resubmitted ${updated.requisitionNumber}`);
      await refreshOvertimeRequisitions();
      return {
        success: true,
        requisition: updated,
        dbSynced: true,
      };
    };

    if (usingCustomSupabase && sb) {
      const directRes = await updateOvertimeRequisitionDirect(sb, id, payload, currentUser);
      if (directRes.success && directRes.dbSynced && directRes.requisition) {
        return finalizeUpdated(directRes.requisition);
      }
      return {
        success: false,
        dbSynced: false,
        error: directRes.error || 'Failed to save updated overtime requisition in Supabase.',
      };
    }

    try {
      const resp = await fetchOvertimeRequisitionApi(`/api/overtime/requisitions/${encodeURIComponent(id)}`, {
        method: 'PUT',
        body: JSON.stringify(payload),
      });
      const { isJsonApi, data } = await parseOvertimeRequisitionApiResponse(resp);

      if (shouldFallbackToDirectSupabaseRequisition(resp, isJsonApi) && sb) {
        const directRes = await updateOvertimeRequisitionDirect(sb, id, payload, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeUpdated(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || 'Failed to save updated overtime requisition in Supabase.',
        };
      }

      if (!resp.ok || data?.success !== true || data?.dbSynced !== true || !data?.requisition) {
        return {
          success: false,
          dbSynced: false,
          error:
            data?.error ||
            data?.dbError ||
            'Failed to save updated overtime requisition in Supabase. Please try again.',
        };
      }
      return finalizeUpdated(data.requisition as OvertimeRequisition);
    } catch (err: any) {
      if (sb) {
        const directRes = await updateOvertimeRequisitionDirect(sb, id, payload, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeUpdated(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || err?.message || 'Failed to save updated overtime requisition in Supabase.',
        };
      }
      return {
        success: false,
        dbSynced: false,
        error: err?.message || 'Network error while updating overtime requisition.',
      };
    }
  };

  const decideOvertimeRequisition = async (
    id: string,
    decision: RequisitionDecisionAction,
    remarks?: string
  ) => {
    const sb = getSupabase();
    const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;

    const finalizeDecided = async (updated: OvertimeRequisition) => {
      setOvertimeRequisitions((prev) =>
        deduplicateOvertimeRequisitions(prev.map((r) => (r.id === updated.id ? updated : r)))
      );
      if (updated.status === 'Approved' && updated.overtimeGranted) {
        setGrantedOvertimeRequisitions((prev) =>
          deduplicateOvertimeRequisitions([updated, ...prev.filter((r) => r.id !== updated.id)])
        );
      }
      addOvertimeAuditLog({
        recordId: updated.id,
        recordType: 'REQUEST',
        action: `REQUISITION_${decision}`,
        actorName: currentUser.name,
        actorRole: currentUser.role,
        details: `Head Office ${decision} on ${updated.requisitionNumber}. Remarks: ${remarks || 'None'}`,
        previousState: 'Pending Approval',
        newState: updated.status,
      });
      addAuditLog('OVERTIME_REQUISITION_DECISION', 'Overtime Requisition', `${decision} ${updated.requisitionNumber}`);
      await refreshOvertimeRequisitions();
      return {
        success: true,
        requisition: updated,
        dbSynced: true,
      };
    };

    if (usingCustomSupabase && sb) {
      const directRes = await decideOvertimeRequisitionDirect(sb, id, decision, remarks, currentUser);
      if (directRes.success && directRes.dbSynced && directRes.requisition) {
        return finalizeDecided(directRes.requisition);
      }
      return {
        success: false,
        dbSynced: false,
        error: directRes.error || 'Failed to save Head Office decision in Supabase.',
      };
    }

    try {
      const resp = await fetchOvertimeRequisitionApi(
        `/api/overtime/requisitions/${encodeURIComponent(id)}/decision`,
        {
          method: 'POST',
          body: JSON.stringify({ decision, remarks }),
        }
      );
      const { isJsonApi, data } = await parseOvertimeRequisitionApiResponse(resp);

      if (shouldFallbackToDirectSupabaseRequisition(resp, isJsonApi) && sb) {
        const directRes = await decideOvertimeRequisitionDirect(sb, id, decision, remarks, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeDecided(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || 'Failed to save Head Office decision in Supabase.',
        };
      }

      if (!resp.ok || data?.success !== true || data?.dbSynced !== true || !data?.requisition) {
        return {
          success: false,
          dbSynced: false,
          error:
            data?.error ||
            data?.dbError ||
            'Failed to save Head Office decision in Supabase. Please try again.',
        };
      }
      return finalizeDecided(data.requisition as OvertimeRequisition);
    } catch (err: any) {
      if (sb) {
        const directRes = await decideOvertimeRequisitionDirect(sb, id, decision, remarks, currentUser);
        if (directRes.success && directRes.dbSynced && directRes.requisition) {
          return finalizeDecided(directRes.requisition);
        }
        return {
          success: false,
          dbSynced: false,
          error: directRes.error || err?.message || 'Failed to save Head Office decision in Supabase.',
        };
      }
      return {
        success: false,
        dbSynced: false,
        error: err?.message || 'Network error while processing Head Office decision.',
      };
    }
  };

  const advanceOvertimeWorkflow = (
    id: string,
    step: 'SUPERVISOR' | 'PRODUCTION' | 'HR' | 'FINAL',
    remarks?: string,
    skipIntermediateSteps?: boolean,
    purposeSelection?: { projectPurpose?: string; purposeId?: string }
  ) => {
    const requiredAction =
      step === 'SUPERVISOR'
        ? 'approve_supervisor'
        : step === 'PRODUCTION'
        ? 'approve_production'
        : step === 'HR'
        ? 'verify_hr_accounts'
        : 'approve_final';
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_requests') ||
      !hasPageAction(currentUser, 'overtime-management', requiredAction)
    ) {
      console.warn(`Permission denied: view_requests & ${requiredAction} required to execute step ${step}.`);
      return;
    }
    const target = overtimeRequests.find((r) => r.id === id);
    if (!target) return;
    const prevStatus = target.status;
    const now = new Date().toISOString();
    let nextStatus = target.status;
    let actionDesc = '';
    const dbPatch: any = { updated_at: now };
    let updatedReq: OvertimeRequest = { ...target, updatedAt: now };

    const selectedPurposeText = String(purposeSelection?.projectPurpose || '').trim();
    if (selectedPurposeText) {
      updatedReq.projectPurpose = selectedPurposeText;
      updatedReq.purposeId = purposeSelection?.purposeId || updatedReq.purposeId;
      updatedReq.purposeSelectedBy = currentUser.name;
      updatedReq.purposeSelectedAt = now;
      dbPatch.project_purpose = selectedPurposeText;
      if (purposeSelection?.purposeId) {
        dbPatch.purpose_id = purposeSelection.purposeId;
      }
      dbPatch.purpose_selected_by = currentUser.name;
      dbPatch.purpose_selected_at = now;
    }

    if (step === 'SUPERVISOR') {
      nextStatus = 'Supervisor Approved';
      actionDesc = 'Supervisor Approval (Step 1)';
      updatedReq = {
        ...updatedReq,
        status: nextStatus,
        supervisorId: currentUser.id,
        supervisorName: currentUser.name,
        supervisorApprovedAt: now,
        supervisorRemarks: remarks || 'Supervisor reviewed and approved',
      };
      dbPatch.status = nextStatus;
      dbPatch.supervisor_id = currentUser.id;
      dbPatch.supervisor_name = currentUser.name;
      dbPatch.supervisor_approved_at = now;
      dbPatch.supervisor_remarks = updatedReq.supervisorRemarks;
    } else if (step === 'PRODUCTION') {
      nextStatus = 'Production Approved';
      actionDesc = 'Production Manager Approval (Step 2)';
      updatedReq = {
        ...updatedReq,
        status: nextStatus,
        productionManagerId: currentUser.id,
        productionManagerName: currentUser.name,
        productionApprovedAt: now,
        productionRemarks: remarks || 'Production schedule confirmed',
      };
      dbPatch.status = nextStatus;
      dbPatch.production_manager_id = currentUser.id;
      dbPatch.production_manager_name = currentUser.name;
      dbPatch.production_approved_at = now;
      dbPatch.production_remarks = updatedReq.productionRemarks;
    } else if (step === 'HR') {
      nextStatus = 'HR Verified';
      actionDesc = 'HR/Accounts Wage Verification (Step 3)';
      updatedReq = {
        ...updatedReq,
        status: nextStatus,
        hrVerifierId: currentUser.id,
        hrVerifierName: currentUser.name,
        hrVerifiedAt: now,
        hrRemarks: remarks || 'Wage calculation and labor policy verified',
      };
      dbPatch.status = nextStatus;
      dbPatch.hr_verifier_id = currentUser.id;
      dbPatch.hr_verifier_name = currentUser.name;
      dbPatch.hr_verified_at = now;
      dbPatch.hr_remarks = updatedReq.hrRemarks;
    } else if (step === 'FINAL') {
      const jumped = Boolean(skipIntermediateSteps) || prevStatus !== 'HR Verified';
      nextStatus = 'Final Approved';
      actionDesc = jumped
        ? 'Direct Final Approval (Skipped Steps 1–3)'
        : 'Executive Final Approval (Step 4)';
      updatedReq = {
        ...updatedReq,
        status: nextStatus,
        finalApproverId: currentUser.id,
        finalApproverName: currentUser.name,
        finalApprovedAt: now,
        finalRemarks:
          remarks ||
          (jumped
            ? 'Direct final approval granted (intermediate approval steps skipped)'
            : 'Final executive approval granted'),
      };
      dbPatch.status = nextStatus;
      dbPatch.final_approver_id = currentUser.id;
      dbPatch.final_approver_name = currentUser.name;
      dbPatch.final_approved_at = now;
      dbPatch.final_remarks = updatedReq.finalRemarks;
    }

    setOvertimeRequests((prev) => prev.map((r) => (r.id === id ? updatedReq : r)));

    const sb = getSupabase();
    if (sb) {
      (async () => {
        const workingPatch = { ...dbPatch };
        for (let attempt = 0; attempt < 6; attempt++) {
          const { error } = await sb.from('overtime_requests').update(workingPatch).eq('id', id);
          if (!error) return;
          const msg = String(error.message || '');
          const missingCol =
            error.code === 'PGRST204' || msg.includes('schema cache')
              ? msg.match(/Could not find the '([^']+)' column/i)?.[1]
              : error.code === '42703' || msg.toLowerCase().includes('does not exist')
              ? msg.match(/column\s+"([^"]+)"/i)?.[1] ||
                msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1]
              : null;
          if (missingCol && Object.prototype.hasOwnProperty.call(workingPatch, missingCol)) {
            delete workingPatch[missingCol];
            continue;
          }
          console.warn('Supabase advanceOvertimeWorkflow failed:', error.message);
          return;
        }
      })();
    }

    addOvertimeAuditLog({
      recordId: id,
      recordType: 'REQUEST',
      action: actionDesc,
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `${actionDesc} on ${target.requestNumber}.${selectedPurposeText ? ` Purpose: ${selectedPurposeText}.` : ''} Remarks: ${remarks || 'None'}`,
      previousState: prevStatus,
      newState: nextStatus,
    });
    addAuditLog('OVERTIME_APPROVED_STEP', 'Overtime Hub', `${actionDesc} for ${target.requestNumber}`);
  };

  const rejectOvertimeRequest = (id: string, reason: string) => {
    const target = overtimeRequests.find((r) => r.id === id);
    if (!target) return;
    const stepAction =
      target.status === 'Pending Supervisor'
        ? 'approve_supervisor'
        : target.status === 'Supervisor Approved'
        ? 'approve_production'
        : target.status === 'Production Approved'
        ? 'verify_hr_accounts'
        : 'approve_final';
    const hasRejectClearance =
      hasPageAction(currentUser, 'overtime-management', 'view_requests') &&
      (hasPageAction(currentUser, 'overtime-management', stepAction) ||
        hasPageAction(currentUser, 'overtime-management', 'approve_final'));
    if (!hasRejectClearance) {
      console.warn('Permission denied: approval clearance required to reject overtime request.');
      return;
    }
    const prevStatus = target.status;
    const now = new Date().toISOString();

    setOvertimeRequests((prev) =>
      prev.map((r) =>
        r.id === id
          ? {
              ...r,
              status: 'Rejected',
              rejectionReason: reason,
              rejectedBy: currentUser.name,
              rejectedAt: now,
              updatedAt: now,
            }
          : r
      )
    );

    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_requests')
        .update({
          status: 'Rejected',
          rejection_reason: reason,
          rejected_by: currentUser.name,
          rejected_at: now,
          updated_at: now,
        })
        .eq('id', id)
        .then(({ error }) => {
          if (error) console.warn('Supabase rejectOvertimeRequest failed:', error.message);
        });
    }

    addOvertimeAuditLog({
      recordId: id,
      recordType: 'REQUEST',
      action: 'REJECTED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Rejected overtime request ${target.requestNumber}. Reason: ${reason}`,
      previousState: prevStatus,
      newState: 'Rejected',
    });
    addAuditLog('OVERTIME_REJECTED', 'Overtime Hub', `Rejected OT request ${target.requestNumber}: ${reason}`);
  };

  const recordOvertimeAttendance = (att: Partial<OvertimeAttendance>): OvertimeAttendance => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_attendance') ||
      !hasPageAction(currentUser, 'overtime-management', 'record_attendance')
    ) {
      console.warn('Permission denied: view_attendance & record_attendance required to log overtime attendance.');
      return {
        id: '',
        employeeId: att.employeeId || '',
        employeeCode: att.employeeCode || '',
        employeeName: att.employeeName || '',
        department: att.department || '',
        designation: att.designation || '',
        date: att.date || '',
        normalCheckInTime: att.normalCheckInTime || '',
        normalCheckOutTime: att.normalCheckOutTime || '',
        overtimeCheckInTime: att.overtimeCheckInTime || '',
        overtimeCheckOutTime: att.overtimeCheckOutTime || '',
        isOvernight: false,
        breakDurationMinutes: 0,
        rawCalculatedHours: 0,
        actualOvertimeHours: 0,
        isVerified: false,
        syncSource: 'Manual',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
    }
    const id = att.id || `ot-att-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`;
    const emp = fieldForceReps.find((r) => r.id === att.employeeId);

    // Check duplicate punch prevention
    const isDup = overtimeAttendances.some(
      (a) => a.id !== id && a.employeeId === att.employeeId && a.date === att.date && a.overtimeCheckInTime === att.overtimeCheckInTime
    );

    const checkIn = att.overtimeCheckInTime || '18:30';
    const checkOut = att.overtimeCheckOutTime || '22:30';
    const breakMin = Number(att.breakDurationMinutes) || 0;
    const isOvernight = Boolean(att.isOvernight || (checkOut < checkIn));
    const hours = calculateNetOvertimeHours(checkIn, checkOut, breakMin, isOvernight);

    const missingOut = !att.overtimeCheckOutTime || att.overtimeCheckOutTime.trim() === '';
    const lateOutAlert = hours > 4.5;
    const nowIso = new Date().toISOString();

    const newAttendance: OvertimeAttendance = {
      id,
      requestId: att.requestId,
      requestNumber: att.requestNumber,
      employeeId: att.employeeId || emp?.id || '',
      employeeCode: att.employeeCode || emp?.code || 'EMP-000',
      employeeName: att.employeeName || emp?.name || 'Staff Member',
      department: att.department || emp?.department || 'Manufacturing & Assembly',
      designation: att.designation || emp?.designation || 'Technician',
      date: att.date || nowIso.substring(0, 10),
      normalCheckInTime: att.normalCheckInTime || '09:00',
      normalCheckOutTime: att.normalCheckOutTime || '18:00',
      overtimeCheckInTime: checkIn,
      overtimeCheckOutTime: checkOut,
      isOvernight,
      breakDurationMinutes: breakMin,
      rawCalculatedHours: hours,
      actualOvertimeHours: hours,
      verifiedBy: hasPageAction(currentUser, 'overtime-management', 'verify_attendance') ? att.verifiedBy : undefined,
      verificationDate: hasPageAction(currentUser, 'overtime-management', 'verify_attendance') ? att.verificationDate : undefined,
      isVerified: Boolean(att.isVerified && hasPageAction(currentUser, 'overtime-management', 'verify_attendance')),
      verificationRemarks: att.verificationRemarks,
      isLateCheckOutAlert: lateOutAlert,
      isMissingCheckOutAlert: missingOut,
      isDuplicateEntryAlert: isDup,
      biometricDeviceId: att.biometricDeviceId || 'BIO-KUSHTIA-PLANT-01',
      rawBiometricPunchId: att.rawBiometricPunchId,
      syncSource: att.syncSource || 'Manual',
      notes: att.notes,
      createdAt: nowIso,
      updatedAt: nowIso,
    };

    setOvertimeAttendances((prev) => [newAttendance, ...prev.filter((a) => a.id !== id)]);

    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_attendances')
        .upsert({
          id: newAttendance.id,
          request_id: newAttendance.requestId || null,
          request_number: newAttendance.requestNumber || null,
          employee_id: newAttendance.employeeId,
          employee_code: newAttendance.employeeCode,
          employee_name: newAttendance.employeeName,
          department: newAttendance.department,
          designation: newAttendance.designation,
          date: newAttendance.date,
          normal_check_in_time: newAttendance.normalCheckInTime,
          normal_check_out_time: newAttendance.normalCheckOutTime,
          overtime_check_in_time: newAttendance.overtimeCheckInTime,
          overtime_check_out_time: newAttendance.overtimeCheckOutTime,
          is_overnight: newAttendance.isOvernight,
          break_duration_minutes: newAttendance.breakDurationMinutes,
          raw_calculated_hours: newAttendance.rawCalculatedHours,
          actual_overtime_hours: newAttendance.actualOvertimeHours,
          verified_by: newAttendance.verifiedBy || null,
          verification_date: newAttendance.verificationDate || null,
          is_verified: newAttendance.isVerified,
          verification_remarks: newAttendance.verificationRemarks || null,
          is_late_check_out_alert: Boolean(newAttendance.isLateCheckOutAlert),
          is_missing_check_out_alert: Boolean(newAttendance.isMissingCheckOutAlert),
          is_duplicate_entry_alert: Boolean(newAttendance.isDuplicateEntryAlert),
          biometric_device_id: newAttendance.biometricDeviceId || null,
          raw_biometric_punch_id: newAttendance.rawBiometricPunchId || null,
          sync_source: newAttendance.syncSource,
          notes: newAttendance.notes || null,
          created_at: newAttendance.createdAt,
          updated_at: newAttendance.updatedAt,
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase overtime_attendances upsert failed:', error.message);
        });
    }

    // If linked to an OvertimeRequest, update the request with verified actual hours and amount
    if (att.requestId) {
      const linkedReq = overtimeRequests.find((r) => r.id === att.requestId);
      if (linkedReq) {
        const hRate = linkedReq.hourlyRateBDT || 135;
        const mult = linkedReq.overtimeMultiplier ?? 2.0;
        const tot = calculateOvertimeTotalBDT(hRate, mult, hours);
        setOvertimeRequests((prev) =>
          prev.map((r) =>
            r.id === att.requestId
              ? {
                  ...r,
                  attendanceId: id,
                  actualOvertimeHours: hours,
                  calculatedOvertimeAmountBDT: tot,
                  updatedAt: nowIso,
                }
              : r
          )
        );
        if (sb) {
          sb.from('overtime_requests')
            .update({
              attendance_id: id,
              actual_overtime_hours: hours,
              calculated_overtime_amount_bdt: tot,
              updated_at: nowIso,
            })
            .eq('id', att.requestId)
            .then(({ error }) => {
              if (error) console.warn('Supabase linked request update failed:', error.message);
            });
        }
      }
    }

    addOvertimeAuditLog({
      recordId: id,
      recordType: 'ATTENDANCE',
      action: 'LOGGED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Recorded OT Attendance for ${newAttendance.employeeName}: ${hours} hrs (${checkIn} - ${checkOut}${isOvernight ? ' Overnight' : ''})`,
    });
    return newAttendance;
  };

  const verifyOvertimeAttendance = (id: string, verifiedActualHours?: number, remarks?: string) => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_attendance') ||
      !hasPageAction(currentUser, 'overtime-management', 'verify_attendance')
    ) {
      console.warn('Permission denied: view_attendance & verify_attendance required to verify OT attendance.');
      return;
    }
    const targetAtt = overtimeAttendances.find((a) => a.id === id);
    if (!targetAtt) return;
    const now = new Date().toISOString();
    const finalHours = verifiedActualHours !== undefined ? verifiedActualHours : targetAtt.rawCalculatedHours;
    const verificationRemarks = remarks || 'Verified by supervisor';

    setOvertimeAttendances((prev) =>
      prev.map((a) =>
        a.id === id
          ? {
              ...a,
              actualOvertimeHours: finalHours,
              isVerified: true,
              verifiedBy: currentUser.name,
              verificationDate: now,
              verificationRemarks,
              updatedAt: now,
            }
          : a
      )
    );

    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_attendances')
        .update({
          actual_overtime_hours: finalHours,
          is_verified: true,
          verified_by: currentUser.name,
          verification_date: now,
          verification_remarks: verificationRemarks,
          updated_at: now,
        })
        .eq('id', id)
        .then(({ error }) => {
          if (error) console.warn('Supabase verifyOvertimeAttendance failed:', error.message);
        });
    }

    if (targetAtt.requestId) {
      const linkedReq = overtimeRequests.find((r) => r.id === targetAtt.requestId);
      if (linkedReq) {
        const hRate = linkedReq.hourlyRateBDT || 135;
        const mult = linkedReq.overtimeMultiplier ?? 2.0;
        const tot = calculateOvertimeTotalBDT(hRate, mult, finalHours);
        setOvertimeRequests((reqs) =>
          reqs.map((r) =>
            r.id === targetAtt.requestId
              ? {
                  ...r,
                  attendanceId: id,
                  actualOvertimeHours: finalHours,
                  calculatedOvertimeAmountBDT: tot,
                  updatedAt: now,
                }
              : r
          )
        );
        if (sb) {
          sb.from('overtime_requests')
            .update({
              attendance_id: id,
              actual_overtime_hours: finalHours,
              calculated_overtime_amount_bdt: tot,
              updated_at: now,
            })
            .eq('id', targetAtt.requestId)
            .then(({ error }) => {
              if (error) console.warn('Supabase linked overtime_requests verify sync failed:', error.message);
            });
        }
      }
    }

    addOvertimeAuditLog({
      recordId: id,
      recordType: 'ATTENDANCE',
      action: 'VERIFIED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Supervisor verified OT hours: ${finalHours} hrs for ${targetAtt.employeeName}. Remarks: ${remarks || 'None'}`,
    });
  };

  const saveOvertimeBatchAllocations = (requestId: string, allocations: OvertimeBatchAllocation[]) => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_batch_allocation') ||
      !hasPageAction(currentUser, 'overtime-management', 'allocate_batch')
    ) {
      console.warn('Permission denied: view_batch_allocation & allocate_batch required to save batch allocations.');
      return;
    }
    const target = overtimeRequests.find((r) => r.id === requestId);
    if (!target) return;
    const maxHours = target.actualOvertimeHours || target.expectedHours || 0;
    const totalAllocated = allocations.reduce((sum, a) => sum + (Number(a.allocatedHours) || 0), 0);
    if (totalAllocated > maxHours) {
      console.warn(`Total allocated hours (${totalAllocated}) exceeds available overtime hours (${maxHours})`);
    }
    const nowIso = new Date().toISOString();

    setOvertimeRequests((prev) =>
      prev.map((r) =>
        r.id === requestId
          ? {
              ...r,
              batchAllocations: allocations,
              isCostingAllocated: allocations.length > 0,
              updatedAt: nowIso,
            }
          : r
      )
    );

    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_batch_allocations')
        .delete()
        .eq('request_id', requestId)
        .then(async ({ error: delErr }) => {
          if (delErr) {
            console.warn('Supabase overtime_batch_allocations delete failed:', delErr.message);
            return;
          }
          if (allocations.length > 0) {
            const { error: insErr } = await sb.from('overtime_batch_allocations').insert(
              allocations.map((a) => ({
                id: a.id,
                request_id: requestId,
                production_order_id: a.productionOrderId || null,
                production_order_number: a.productionOrderNumber,
                production_batch_number: a.productionBatchNumber,
                product_id: a.productId || null,
                product_name: a.productName,
                process_type: a.processType,
                allocated_hours: Number(a.allocatedHours) || 0,
                hourly_rate_bdt: Number(a.hourlyRateBDT) || 0,
                allocated_cost_bdt: Number(a.allocatedCostBDT) || 0,
                is_overhead: Boolean(a.isOverhead),
                notes: a.notes || null,
              }))
            );
            if (insErr) console.warn('Supabase overtime_batch_allocations insert failed:', insErr.message);
          }
          await sb
            .from('overtime_requests')
            .update({ is_costing_allocated: allocations.length > 0, updated_at: nowIso })
            .eq('id', requestId);
        });
    }

    addOvertimeAuditLog({
      recordId: requestId,
      recordType: 'ALLOCATION',
      action: 'BATCH_ALLOCATION_UPDATED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Updated batch split for ${target.requestNumber} across ${allocations.length} batches (${totalAllocated} hrs)`,
    });
  };

  const updateOvertimePolicy = (policy: OvertimePolicyConfig) => {
    if (
      !hasPageAction(currentUser, 'overtime-management', 'view_policies') ||
      !hasPageAction(currentUser, 'overtime-management', 'configure_policy')
    ) {
      console.warn('Permission denied: view_policies & configure_policy required to update overtime policy.');
      return;
    }
    const nowIso = new Date().toISOString();
    const updatedPolicy = { ...policy, updatedAt: nowIso, updatedBy: currentUser.name };
    setOvertimePolicies((prev) =>
      prev.map((p) => (p.id === policy.id ? updatedPolicy : p))
    );
    const sb = getSupabase();
    if (sb) {
      sb.from('overtime_policies')
        .upsert({
          id: updatedPolicy.id,
          policy_name: updatedPolicy.policyName,
          is_default: updatedPolicy.isDefault,
          department: updatedPolicy.department || 'All Departments',
          standard_working_days_per_month: updatedPolicy.standardWorkingDaysPerMonth,
          standard_daily_working_hours: updatedPolicy.standardDailyWorkingHours,
          standard_monthly_working_hours: updatedPolicy.standardMonthlyWorkingHours,
          wage_basis: updatedPolicy.wageBasis,
          overtime_multiplier_regular: updatedPolicy.overtimeMultiplierRegular,
          overtime_multiplier_weekend: updatedPolicy.overtimeMultiplierWeekend,
          overtime_multiplier_holiday: updatedPolicy.overtimeMultiplierHoliday,
          overtime_multiplier_night_shift: updatedPolicy.overtimeMultiplierNightShift,
          minimum_ot_minutes_threshold: updatedPolicy.minimumOtMinutesThreshold,
          max_ot_hours_per_day: updatedPolicy.maxOtHoursPerDay,
          max_ot_hours_per_month: updatedPolicy.maxOtHoursPerMonth,
          allow_overnight_overtime: updatedPolicy.allowOvernightOvertime,
          require_supervisor_pre_approval: updatedPolicy.requireSupervisorPreApproval,
          updated_by: updatedPolicy.updatedBy || null,
          updated_at: nowIso,
        })
        .then(({ error }) => {
          if (error) console.warn('Supabase overtime_policies upsert failed:', error.message);
        });
    }
    addOvertimeAuditLog({
      recordId: policy.id,
      recordType: 'POLICY',
      action: 'POLICY_UPDATED',
      actorName: currentUser.name,
      actorRole: currentUser.role,
      details: `Updated overtime policy: ${policy.policyName} (Multiplier: ${policy.overtimeMultiplierRegular}x, Standard Hours: ${policy.standardMonthlyWorkingHours}h)`,
    });
    addAuditLog('OVERTIME_POLICY_UPDATED', 'Overtime Hub', `Updated policy: ${policy.policyName}`);
  };

  const clearOvertimeData = () => {
    if (currentUser.role !== 'Super Admin') {
      console.warn('Permission denied: only Super Admin can clear overtime data.');
      return;
    }
    const reqIds = overtimeRequests.map((r) => r.id);
    const attIds = overtimeAttendances.map((a) => a.id);
    const audIds = overtimeAuditLogs.map((l) => l.id);
    const recIds = overtimeRecords.map((r) => r.id);

    setOvertimeRecords([]);
    setOvertimeRequests([]);
    setOvertimeRequisitions([]);
    setGrantedOvertimeRequisitions([]);
    setOvertimeAttendances([]);
    setOvertimeAuditLogs([]);

    if (typeof window !== 'undefined') {
      try {
        localStorage.removeItem('ensec_overtime_records');
        localStorage.removeItem('ensec_overtime_requests');
        localStorage.removeItem('ensec_overtime_attendances');
        localStorage.removeItem('ensec_overtime_audit_logs');
        try {
          sessionStorage.removeItem('ensec_overtime_records');
          sessionStorage.removeItem('ensec_overtime_requests');
          sessionStorage.removeItem('ensec_overtime_attendances');
          sessionStorage.removeItem('ensec_overtime_audit_logs');
        } catch {}
        purgeOvertimeRequisitionLocalSessionMemory();
        localStorage.setItem('ensec_overtime_test_purged_v1', 'true');
      } catch (e) {
        console.warn('Error clearing overtime storage:', e);
      }
    }

    const sb = getSupabase();
    if (sb) {
      Promise.allSettled([
        reqIds.length > 0 ? sb.from('overtime_batch_allocations').delete().in('request_id', reqIds) : Promise.resolve(),
        attIds.length > 0 ? sb.from('overtime_attendances').delete().in('id', attIds) : Promise.resolve(),
        audIds.length > 0 ? sb.from('overtime_audit_logs').delete().in('id', audIds) : Promise.resolve(),
        reqIds.length > 0 ? sb.from('overtime_requests').delete().in('id', reqIds) : Promise.resolve(),
        recIds.length > 0 ? sb.from('employee_overtimes').delete().in('id', recIds) : Promise.resolve(),
      ]).catch(() => {});
    }

    addAuditLog(
      'OVERTIME_DATA_CLEARED',
      'Overtime Management',
      'Cleared Overtime Management data from local storage and Supabase'
    );
  };

  const addBonusRecord = (bonus: Omit<BonusRecord, 'id' | 'status'>): string => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to add bonus/incentive.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to add bonus record without create_payroll permission`);
      return '';
    }
    const id = `bns-${Date.now().toString().slice(-6)}`;
    const newBonus: BonusRecord = { ...bonus, id, status: 'Pending' };
    setBonusRecords((prev) => [newBonus, ...prev]);
    addAuditLog('BONUS_LOGGED', 'HR & Payroll', `Added ${bonus.bonusType} for ${bonus.employeeName}: ৳${bonus.amountBDT.toLocaleString()}`);
    return id;
  };

  const approveBonusRecord = (id: string, approvedBy: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'approve_payroll')) {
      console.warn('Permission denied: approve_payroll required to approve bonus/incentive.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to approve bonus (${id}) without approve_payroll permission`);
      return;
    }
    setBonusRecords((prev) =>
      prev.map((b) => (b.id === id ? { ...b, status: 'Approved', approvedBy } : b))
    );
    addAuditLog('BONUS_APPROVED', 'HR & Payroll', `Approved bonus ${id} by ${approvedBy}`);
  };

  const generateMonthlySalaryRun = (monthYear: string, department?: string, employeeCategory?: EmployeeCategory): string => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to process monthly payroll run.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to process monthly salary run (${monthYear}) without create_payroll permission`);
      return '';
    }
    const [year, month] = monthYear.split('-').map(Number);
    const totalDaysInMonth = new Date(year, month, 0).getDate();
    const workingDaysStandard = payrollSettings.standardWorkingDaysPerMonth || 26;

    // Filter target active employees
    let eligibleStaff = fieldForceReps.filter((r) => r.isActive !== false);
    if (department && department !== 'All') {
      eligibleStaff = eligibleStaff.filter((r) => r.department === department);
    }
    if (employeeCategory && (employeeCategory as any) !== 'All') {
      eligibleStaff = eligibleStaff.filter((r) => r.employeeCategory === employeeCategory);
    }

    const runId = `run-${monthYear}-${Date.now().toString().slice(-4)}`;

    const items: MonthlySalarySheetItem[] = eligibleStaff.map((emp) => {
      // 1. Get or synthesize salary structure
      const str = salaryStructures.find((s) => s.employeeId === emp.id || s.fieldForceId === emp.id);
      const basic = str ? str.basicSalaryBDT : emp.basicSalaryBDT || 0;
      const houseRent = str ? str.houseRentBDT : basic * 0.5;
      const medical = str ? str.medicalAllowanceBDT : basic * 0.1;
      const conveyance = str ? str.conveyanceAllowanceBDT : emp.conveyanceBDT || 0;
      const mobile = str ? str.mobileAllowanceBDT : emp.mobileAllowanceBDT || 0;
      const special = str ? str.specialAllowanceBDT : 0;
      const otherAllow = str ? str.otherAllowancesBDT : 0;
      const grossBase = basic + houseRent + medical + conveyance + mobile + special + otherAllow;

      // 2. Attendance summary
      const att = getEmployeeAttendanceSummary(emp.id, monthYear);
      const daysWorked = att.presentDays > 0 ? att.presentDays : workingDaysStandard;
      const daysAbsent = att.absentDays;

      // Unexcused absence deduction: (Basic / 30) * absentDays
      const perDayRate = Math.round(basic / totalDaysInMonth);
      const attendanceDeduction = daysAbsent > 0 ? perDayRate * daysAbsent : 0;

      // 3. Overtime: Pull from Overtime Management Module (Final Approved requests) as well as legacy records
      const empOvertimeRequests = (overtimeRequests || []).filter(
        (req) =>
          req.employeeId === emp.id &&
          req.status === 'Final Approved' &&
          (req.overtimeDate.startsWith(monthYear) || req.payrollMonth === monthYear) &&
          (!req.isPayrollProcessed || req.payrollRunId === runId)
      );
      const reqOtHours = empOvertimeRequests.reduce(
        (sum, r) => sum + (r.actualOvertimeHours || r.expectedHours || 0),
        0
      );
      const reqOtAmount = empOvertimeRequests.reduce(
        (sum, r) => sum + (r.calculatedOvertimeAmountBDT || 0),
        0
      );

      const empLegacyOvertimes = (overtimeRecords || []).filter(
        (o) => o.employeeId === emp.id && o.monthYear === monthYear && o.status === 'Approved'
      );
      const legacyOtHours = empLegacyOvertimes.reduce((s, o) => s + o.hours, 0);
      const legacyOtAmount = empLegacyOvertimes.reduce((s, o) => s + o.totalAmountBDT, 0);

      const otHours = Math.round((reqOtHours + legacyOtHours) * 100) / 100;
      const otAmount = reqOtAmount + legacyOtAmount;

      // 4. Bonuses & Incentives
      const empBonuses = bonusRecords.filter(
        (b) => b.employeeId === emp.id && b.monthYear === monthYear && b.status === 'Approved'
      );
      const bonusAmount = empBonuses.reduce((s, b) => s + b.amountBDT, 0);

      // Sales commission incentive tied to sales achievement if field force
      let performanceIncentive = 0;
      if (emp.monthlyTargetBDT && emp.monthlyTargetBDT > 0 && emp.monthlyAchievedBDT) {
        const achPct = (emp.monthlyAchievedBDT / emp.monthlyTargetBDT) * 100;
        if (achPct >= 100) performanceIncentive = Math.round(basic * 0.35);
        else if (achPct >= 80) performanceIncentive = Math.round(basic * 0.2);
      }

      // 5. Active Loans / Advance deduction scheduled for this month
      const activeLoans = advanceLoans.filter(
        (l) => l.employeeId === emp.id && (l.status === 'Approved' || l.status === 'Active') && (l.remainingAmountBDT || l.remainingBalanceBDT || 0) > 0
      );
      let loanDeduction = 0;
      activeLoans.forEach((l) => {
        const sched = l.schedule.find((s) => s.monthYear === monthYear && (s.status === 'Scheduled' || s.status === 'Pending'));
        if (sched) {
          loanDeduction += (sched.amountBDT || sched.installmentAmountBDT || 0);
        } else {
          // If no explicit monthly schedule matches, deduct default installment capped at remaining
          const monDed = l.monthlyDeductionBDT || l.monthlyInstallmentBDT || 0;
          const rem = l.remainingAmountBDT || l.remainingBalanceBDT || 0;
          loanDeduction += Math.min(monDed, rem);
        }
      });

      // 6. Tax & PF
      const totalEarningsGross = grossBase + otAmount + bonusAmount + performanceIncentive;
      let taxDeduction = 0;
      if (payrollSettings?.deductionRules?.incomeTaxEnabled && totalEarningsGross > 40000) {
        taxDeduction = Math.round(totalEarningsGross * 0.05);
      }
      let pfDeduction = 0;
      if (payrollSettings?.deductionRules?.providentFundEnabled) {
        const pfRate =
          payrollSettings?.pfEmployeeContributionPercent ??
          payrollSettings?.deductionRules?.pfEmployeeContributionPercent ??
          10;
        pfDeduction = Math.round((basic * pfRate) / 100);
      }

      const totalDeductions = attendanceDeduction + loanDeduction + taxDeduction + pfDeduction;
      const netSalary = Math.max(0, totalEarningsGross - totalDeductions);

      return {
        id: `item-${monthYear}-${emp.id}`,
        payrollRunId: runId,
        fieldForceId: emp.id,
        employeeId: emp.id,
        employeeCode: emp.code,
        employeeName: emp.name,
        department: emp.department || 'Operations',
        designation: emp.designation,
        employeeCategory: (emp.employeeCategory || 'Office Employee') as EmployeeCategory,
        monthYear,
        bankAccountNo: emp.bankAccountNumber,
        bankName: emp.bankName,
        totalWorkingDays: totalDaysInMonth,
        presentDays: daysWorked,
        absentDays: daysAbsent,
        leaveDays: att.leaveDays,
        holidays: att.holidays,
        basicSalaryBDT: basic,
        houseRentBDT: houseRent,
        medicalAllowanceBDT: medical,
        conveyanceAllowanceBDT: conveyance,
        mobileAllowanceBDT: mobile,
        specialAllowanceBDT: special,
        otherAllowancesBDT: otherAllow,
        grossSalaryBDT: grossBase,
        overtimeHours: otHours,
        overtimeAmountBDT: otAmount,
        festivalBonusBDT: empBonuses.filter((b) => b.bonusType === 'Festival Bonus').reduce((s, b) => s + b.amountBDT, 0),
        performanceBonusBDT:
          empBonuses.filter((b) => b.bonusType === 'Performance Bonus').reduce((s, b) => s + b.amountBDT, 0) +
          performanceIncentive,
        salesIncentiveBDT: empBonuses.filter((b) => b.bonusType === 'Sales Incentive').reduce((s, b) => s + b.amountBDT, 0),
        totalGrossEarningsBDT: totalEarningsGross,
        attendanceDeductionBDT: attendanceDeduction,
        advanceLoanDeductionBDT: loanDeduction,
        providentFundDeductionBDT: pfDeduction,
        taxDeductionBDT: taxDeduction,
        otherDeductionsBDT: 0,
        totalDeductionsBDT: totalDeductions,
        netSalaryBDT: netSalary,
        paymentStatus: 'Unpaid',
      };
    });

    const newRun: MonthlyPayrollRun = {
      id: runId,
      monthYear,
      status: 'Draft',
      processedAt: new Date().toISOString(),
      processedBy: currentUser?.name || 'HR Executive',
      totalEmployees: items.length,
      totalGrossBDT: items.reduce((s, i) => s + (i.totalGrossEarningsBDT || 0), 0),
      totalNetBDT: items.reduce((s, i) => s + (i.netSalaryBDT || 0), 0),
      totalDeductionsBDT: items.reduce((s, i) => s + (i.totalDeductionsBDT || 0), 0),
      totalOvertimeBDT: items.reduce((s, i) => s + (i.overtimeAmountBDT || 0), 0),
      totalBonusBDT: items.reduce((s, i) => s + ((i.festivalBonusBDT || 0) + (i.performanceBonusBDT || 0) + (i.salesIncentiveBDT || 0)), 0),
      totalLoanDeductionsBDT: items.reduce((s, i) => s + (i.advanceLoanDeductionBDT || 0), 0),
      totalPFDeductionsBDT: items.reduce((s, i) => s + (i.providentFundDeductionBDT || 0), 0),
      totalTaxDeductionsBDT: items.reduce((s, i) => s + (i.taxDeductionBDT || 0), 0),
      items,
    };

    setMonthlyPayrollRuns((prev) => [newRun, ...prev.filter((r) => r.monthYear !== monthYear)]);
    
    // Mark approved overtime requests as processed in this payroll run
    const processedReqIds: string[] = [];
    const nowIso = new Date().toISOString();
    setOvertimeRequests((prev) =>
      prev.map((r) => {
        if (
          r.status === 'Final Approved' &&
          (r.overtimeDate.startsWith(monthYear) || r.payrollMonth === monthYear) &&
          !r.isPayrollProcessed
        ) {
          processedReqIds.push(r.id);
          return {
            ...r,
            isPayrollProcessed: true,
            payrollRunId: runId,
            payrollMonth: monthYear,
            updatedAt: nowIso,
          };
        }
        return r;
      })
    );

    const sbPayroll = getSupabase();
    if (sbPayroll && processedReqIds.length > 0) {
      sbPayroll
        .from('overtime_requests')
        .update({
          is_payroll_processed: true,
          payroll_run_id: runId,
          payroll_month: monthYear,
          updated_at: nowIso,
        })
        .in('id', processedReqIds)
        .then(({ error }) => {
          if (error) console.warn('Supabase payroll OT lock failed:', error.message);
        });
    }

    addAuditLog(
      'PAYROLL_GENERATED',
      'HR & Payroll',
      `Processed monthly salary calculations for ${monthYear} (${items.length} employees) - Gross: ৳${newRun.totalGrossBDT.toLocaleString()}, Net: ৳${newRun.totalNetBDT.toLocaleString()}`
    );
    return runId;
  };

  const finalizeMonthlyPayrollRun = (runId: string, finalizedBy: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'approve_payroll')) {
      console.warn('Permission denied: approve_payroll required to finalize monthly payroll run.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to finalize payroll run (${runId}) without approve_payroll permission`);
      return;
    }
    let targetRun: MonthlyPayrollRun | undefined;

    setMonthlyPayrollRuns((prev) =>
      prev.map((r) => {
        if (r.id === runId) {
          targetRun = {
            ...r,
            status: 'Finalized',
            finalizedAt: new Date().toISOString(),
            finalizedBy,
          };
          return targetRun;
        }
        return r;
      })
    );

    if (targetRun) {
      const run = targetRun;

      // Update loans installments that were deducted in this run
      const deductedEmpIds = new Set(
        run.items.filter((i) => i.advanceLoanDeductionBDT > 0).map((i) => i.employeeId)
      );
      if (deductedEmpIds.size > 0) {
        const updatedLoansList: AdvanceLoanRecord[] = [];
        const touchedLoans: AdvanceLoanRecord[] = [];
        advanceLoans.forEach((loan) => {
          const matchedItem = run.items.find(
            (item) =>
              item.advanceLoanDeductionBDT > 0 &&
              loan.employeeId === item.employeeId &&
              (loan.status === 'Approved' || loan.status === 'Active') &&
              (loan.remainingAmountBDT ?? 0) > 0
          );
          if (matchedItem) {
            const schedIndex = loan.schedule.findIndex(
              (s) => s.monthYear === run.monthYear && s.status === 'Scheduled'
            );
            const deductedAmt =
              schedIndex !== -1
                ? loan.schedule[schedIndex].amountBDT || loan.schedule[schedIndex].installmentAmountBDT || 0
                : matchedItem.advanceLoanDeductionBDT;
            const newRepaid = (loan.repaidAmountBDT || 0) + deductedAmt;
            const newRemaining = Math.max(0, (loan.principalAmountBDT || 0) - newRepaid);
            const newSched = loan.schedule.map((s, idx) =>
              idx === schedIndex || (schedIndex === -1 && idx === 0 && s.status === 'Scheduled')
                ? {
                    ...s,
                    status: 'Deducted' as const,
                    deductedInPayrollId: runId,
                    paidDate: new Date().toISOString().slice(0, 10),
                  }
                : s
            );
            const updatedLoan: AdvanceLoanRecord = {
              ...loan,
              repaidAmountBDT: newRepaid,
              remainingAmountBDT: newRemaining,
              status: newRemaining === 0 ? ('Closed' as const) : ('Active' as const),
              schedule: newSched,
            };
            updatedLoansList.push(updatedLoan);
            touchedLoans.push(updatedLoan);
          } else {
            updatedLoansList.push(loan);
          }
        });
        if (touchedLoans.length > 0) {
          setAdvanceLoans(updatedLoansList);
          void persistAdvanceLoansToSupabase(touchedLoans, updatedLoansList);
        }
      }

      // Post double-entry journal entry record in audit logs
      addAuditLog(
        'PAYROLL_FINALIZED',
        'Finance & Accounts',
        `Finalized Payroll for ${run.monthYear} by ${finalizedBy}. Double-Entry Journal: Dr. Salaries Expense ৳${run.totalGrossBDT.toLocaleString()} | Cr. Salaries Payable ৳${run.totalNetBDT.toLocaleString()} | Cr. Loan Deductions ৳${run.totalLoanDeductionsBDT.toLocaleString()} | Cr. Tax/PF Withholding ৳${(run.totalTaxDeductionsBDT + run.totalPFDeductionsBDT).toLocaleString()}`
      );
    }
  };

  const deleteMonthlyPayrollRun = (runId: string) => {
    if (!hasPageAction(currentUser, 'payroll', 'create_payroll')) {
      console.warn('Permission denied: create_payroll required to delete payroll run.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to delete payroll run (${runId}) without create_payroll permission`);
      return;
    }
    setMonthlyPayrollRuns((prev) => prev.filter((r) => r.id !== runId));
    const unlockedIds = overtimeRequests.filter((r) => r.payrollRunId === runId).map((r) => r.id);
    if (unlockedIds.length > 0) {
      const nowIso = new Date().toISOString();
      setOvertimeRequests((prev) =>
        prev.map((r) =>
          r.payrollRunId === runId
            ? { ...r, isPayrollProcessed: false, payrollRunId: undefined, payrollMonth: undefined, updatedAt: nowIso }
            : r
        )
      );
      const sb = getSupabase();
      if (sb) {
        sb.from('overtime_requests')
          .update({
            is_payroll_processed: false,
            payroll_run_id: null,
            payroll_month: null,
            updated_at: nowIso,
          })
          .eq('payroll_run_id', runId)
          .then(({ error }) => {
            if (error) console.warn('Supabase payroll OT unlock failed:', error.message);
          });
      }
    }
    addAuditLog('PAYROLL_DELETED', 'HR & Payroll', `Deleted payroll run ID ${runId}`);
  };

  const recordSalaryPayment = (
    runId: string,
    employeeId: string,
    paymentDetails: {
      paymentDate: string;
      paymentMethod: 'Bank Transfer' | 'Cash' | 'bKash' | 'Nagad';
      bankAccountName?: string;
      transactionReference?: string;
      amountBDT: number;
      disbursedBy: string;
      notes?: string;
    }
  ) => {
    if (!hasPageAction(currentUser, 'payroll', 'disburse')) {
      console.warn('Permission denied: disburse required to disburse salary payments.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to disburse salary (${employeeId} / ${runId}) without disburse permission`);
      return;
    }
    let paidItem: MonthlySalarySheetItem | undefined;
    let targetMonth = '';

    setMonthlyPayrollRuns((prev) =>
      prev.map((r) => {
        if (r.id === runId) {
          targetMonth = r.monthYear;
          const updatedItems = r.items.map((it) => {
            if (it.employeeId === employeeId) {
              paidItem = {
                ...it,
                paymentStatus: 'Paid' as const,
                paymentMethod: paymentDetails.paymentMethod,
                paymentDate: paymentDetails.paymentDate,
                transactionRef: paymentDetails.transactionReference,
              };
              return paidItem;
            }
            return it;
          });

          const allPaid = updatedItems.every((i) => i.paymentStatus === 'Paid');
          return {
            ...r,
            status: allPaid ? ('Paid' as const) : r.status,
            items: updatedItems,
          };
        }
        return r;
      })
    );

    if (paidItem) {
      const it = paidItem;
      const paymentRecord: SalaryPaymentRecord = {
        id: `pmt-${Date.now().toString().slice(-6)}`,
        payrollRunId: runId,
        monthYear: targetMonth,
        employeeId: it.employeeId,
        employeeCode: it.employeeCode,
        employeeName: it.employeeName,
        paymentDate: paymentDetails.paymentDate,
        amountBDT: paymentDetails.amountBDT,
        paymentMethod: paymentDetails.paymentMethod,
        bankAccountName: paymentDetails.bankAccountName || (paymentDetails.paymentMethod === 'Cash' ? 'Cash in Hand' : 'City Bank PLC'),
        transactionReference: paymentDetails.transactionReference || `SAL-${targetMonth}-${it.employeeCode}`,
        disbursedBy: paymentDetails.disbursedBy,
        remarks: paymentDetails.notes,
        status: 'Completed',
      };
      setSalaryPaymentRecords((prev) => [paymentRecord, ...prev]);

      // Deduct from Cash Book
      const lastCash = cashBook[cashBook.length - 1];
      const prevBal = lastCash ? lastCash.runningBalanceBDT : 10000000;
      const cashEntry: CashBookEntry = {
        id: `cb-${Date.now()}`,
        date: paymentDetails.paymentDate,
        voucherNo: `CB-SAL-${Date.now().toString().slice(-4)}`,
        accountType: (paymentDetails.paymentMethod === 'Cash' ? 'Cash in Hand' : 'City Bank PLC') as any,
        transactionCategory: 'Salary Payment',
        description: `Disbursed Salary for ${it.employeeName} (${it.employeeCode}) - Month: ${targetMonth} (${paymentDetails.paymentMethod})`,
        reference: paymentRecord.transactionReference,
        cashInBDT: 0,
        cashOutBDT: paymentDetails.amountBDT,
        runningBalanceBDT: prevBal - paymentDetails.amountBDT,
      };
      setCashBook((cb) => [...cb, cashEntry]);

      addAuditLog(
        'SALARY_DISBURSED',
        'HR & Payroll',
        `Disbursed net salary ৳${paymentDetails.amountBDT.toLocaleString()} to ${it.employeeName} via ${paymentDetails.paymentMethod}`
      );
    }
  };

  const persistPayrollSettingsToSupabase = async (
    settings: PayrollSettings
  ): Promise<{
    dbSynced: boolean;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
    dbStatus: PayrollSettingsDbStatus;
  }> => {
    const sb = getSupabase();
    if (!sb) {
      const notCfgStatus: PayrollSettingsDbStatus = {
        synced: false,
        status: 'not_configured',
        error: 'Supabase client is not configured.',
        sqlFix: null,
      };
      setPayrollSettingsDbStatus(notCfgStatus);
      return { dbSynced: false, error: notCfgStatus.error || undefined, dbStatus: notCfgStatus };
    }

    const actorName = settings.updatedBy || currentUser?.name || 'Admin';
    const updatedAt = settings.updatedAt || new Date().toISOString();
    const rawPf =
      settings.pfEmployeeContributionPercent ??
      settings.deductionRules?.pfEmployeeContributionPercent;
    const pfPercent =
      rawPf !== undefined && rawPf !== null && Number.isFinite(Number(rawPf))
        ? Math.min(100, Math.max(0, Number(rawPf)))
        : 10;

    const upsertPayload: Record<string, any> = {
      id: 'default',
      standard_working_days_per_month: Math.max(1, Number(settings.standardWorkingDaysPerMonth) || 26),
      standard_daily_hours: Math.max(1, Number(settings.standardDailyHours) || 8),
      overtime_config: settings.overtimeConfig || { hourlyRateMultiplier: 1.5 },
      overtime_purposes: settings.overtimePurposes || DEFAULT_OVERTIME_PURPOSES,
      leave_quotas: settings.leaveQuotas || {
        annualLeave: 14,
        casualLeave: 10,
        sickLeave: 14,
        maternityLeave: 112,
      },
      deduction_rules: {
        ...(settings.deductionRules || {}),
        pfEmployeeContributionPercent: pfPercent,
        overtimeConfig: settings.overtimeConfig || { hourlyRateMultiplier: 1.5 },
        overtimePurposes: settings.overtimePurposes || DEFAULT_OVERTIME_PURPOSES,
        shiftStartTime: settings.shiftStartTime || DEFAULT_SHIFT_START_TIME,
        shiftEndTime: settings.shiftEndTime || DEFAULT_SHIFT_END_TIME,
        lateGracePeriodMinutes: Math.max(0, Number(settings.lateGracePeriodMinutes ?? DEFAULT_GRACE_PERIOD_MINUTES)),
        maxGpsAccuracyMeters: Math.max(15, Number(settings.maxGpsAccuracyMeters ?? DEFAULT_MAX_GPS_ACCURACY_METERS)),
        lateDaysForOneDayAbsent: Number(settings.lateDaysForOneDayAbsent ?? 3),
        companyName: settings.companyName ?? '',
        companyAddress: settings.companyAddress ?? '',
        defaultBankAccountId: settings.defaultBankAccountId ?? '',
        autoPostAccountingJournal: settings.autoPostAccountingJournal ?? true,
        updatedBy: actorName,
      },
      salary_components: settings.salaryComponents || {
        houseRentPercent: 50,
        medicalAllowancePercent: 10,
      },
      pf_employee_contribution_percent: pfPercent,
      shift_start_time: settings.shiftStartTime || DEFAULT_SHIFT_START_TIME,
      shift_end_time: settings.shiftEndTime || DEFAULT_SHIFT_END_TIME,
      late_grace_period_minutes: Math.max(
        0,
        Number(settings.lateGracePeriodMinutes ?? DEFAULT_GRACE_PERIOD_MINUTES)
      ),
      max_gps_accuracy_meters: Math.max(
        15,
        Number(settings.maxGpsAccuracyMeters ?? DEFAULT_MAX_GPS_ACCURACY_METERS)
      ),
      updated_by: actorName,
      updated_at: updatedAt,
    };

    try {
      let lastError: any = null;
      const workingPayload: Record<string, any> = { ...upsertPayload };
      const strippedMissingColumns: string[] = [];

      for (let attempt = 0; attempt < 10; attempt++) {
        const { error } = await sb
          .from('payroll_settings')
          .upsert(workingPayload, { onConflict: 'id' });

        if (!error) {
          if (strippedMissingColumns.length > 0) {
            const missingColsLabel = strippedMissingColumns.join(', ');
            const colMissingStatus: PayrollSettingsDbStatus = {
              synced: false,
              status: 'column_missing',
              error: `Saved via JSON fallback, but Supabase table "public.payroll_settings" is missing column(s): ${missingColsLabel}. Run the SQL fix below once in Supabase SQL Editor, then click Sync to Supabase.`,
              sqlFix: PAYROLL_SETTINGS_TABLE_SQL,
            };
            setPayrollSettingsDbStatus(colMissingStatus);
            return {
              dbSynced: false,
              backedUp: true,
              error: colMissingStatus.error || undefined,
              sqlFix: PAYROLL_SETTINGS_TABLE_SQL,
              dbStatus: colMissingStatus,
            };
          }
          const okStatus: PayrollSettingsDbStatus = {
            synced: true,
            status: 'synced',
            error: null,
            sqlFix: null,
          };
          setPayrollSettingsDbStatus(okStatus);
          return { dbSynced: true, backedUp: false, dbStatus: okStatus };
        }

        lastError = error;
        const msg = String(error.message || '');
        let missingCol: string | null = null;
        if (error.code === 'PGRST204' || msg.includes('schema cache')) {
          missingCol = msg.match(/Could not find the '([^']+)' column/i)?.[1] || null;
        } else if (error.code === '42703' || msg.toLowerCase().includes('does not exist')) {
          missingCol =
            msg.match(/column\s+"([^"]+)"/i)?.[1] ||
            msg.match(/column\s+(?:[a-zA-Z0-9_]+\.)?([a-zA-Z0-9_]+)/i)?.[1] ||
            null;
        }
        if (missingCol && Object.prototype.hasOwnProperty.call(workingPayload, missingCol)) {
          strippedMissingColumns.push(missingCol);
          delete workingPayload[missingCol];
          continue;
        }
        break;
      }

      const primaryStatus = classifyPayrollSettingsSupabaseError(lastError);
      let backedUp = false;
      if (
        primaryStatus.status === 'rls_blocked' ||
        primaryStatus.status === 'table_missing' ||
        primaryStatus.status === 'error'
      ) {
        const { error: fallbackError } = await sb.from('system_settings').upsert(
          {
            id: 'payroll_settings',
            software_name: 'Payroll Settings',
            logo_data_url: null,
            branding_json: { type: 'payroll_settings' },
            settings_json: { payrollSettings: settings },
            updated_by: actorName,
            updated_at: updatedAt,
          },
          { onConflict: 'id' }
        );
        backedUp = !fallbackError;
      }

      setPayrollSettingsDbStatus(primaryStatus);
      console.warn('[PayrollSettings] public.payroll_settings write blocked; SQL policy required:', lastError);
      return {
        dbSynced: false,
        backedUp,
        error: backedUp
          ? `Backed up in system_settings, but Supabase Row-Level Security blocked writing directly to "public.payroll_settings". Run the SQL fix below once in Supabase SQL Editor, then click Sync to Supabase.`
          : primaryStatus.error || lastError?.message || 'Failed to save payroll settings to Supabase.',
        sqlFix: primaryStatus.sqlFix || PAYROLL_SETTINGS_TABLE_SQL,
        dbStatus: primaryStatus,
      };
    } catch (err: any) {
      const failStatus = classifyPayrollSettingsSupabaseError(err);
      setPayrollSettingsDbStatus(failStatus);
      console.warn('[PayrollSettings] Supabase save exception:', err);
      return {
        dbSynced: false,
        backedUp: false,
        error: failStatus.error || err?.message || 'Network error while saving payroll settings.',
        sqlFix: failStatus.sqlFix || PAYROLL_SETTINGS_TABLE_SQL,
        dbStatus: failStatus,
      };
    }
  };

  const updatePayrollSettings = async (
    newSettings: Partial<PayrollSettings>
  ): Promise<{
    success: boolean;
    dbSynced: boolean;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
    dbStatus?: PayrollSettingsDbStatus;
  }> => {
    const canUpdatePurposesOnly =
      Object.keys(newSettings).every((k) => k === 'overtimePurposes') &&
      hasPageAction(currentUser, 'overtime-management', 'configure_policy');

    if (
      !hasPageAction(currentUser, 'payroll', 'create_payroll') &&
      !hasPageAction(currentUser, 'payroll', 'approve_payroll') &&
      !canUpdatePurposesOnly
    ) {
      console.warn('Permission denied: create_payroll or approve_payroll required to update payroll settings.');
      addAuditLog('PERMISSION_DENIED', 'HR & Payroll', `${currentUser?.name || 'User'} attempted to modify payroll settings without permission`);
      return {
        success: false,
        dbSynced: false,
        error: 'Permission denied: Process Monthly Payroll or Approve Salary Sheet permission required.',
      };
    }

    const nowIso = new Date().toISOString();
    const actorName = currentUser?.name || 'Admin';
    const nextSettings = mergePayrollSettings(payrollSettings, {
      ...newSettings,
      updatedAt: nowIso,
      updatedBy: actorName,
    });

    setPayrollSettings(nextSettings);
    const persistResult = await persistPayrollSettingsToSupabase(nextSettings);
    addAuditLog('PAYROLL_SETTINGS_UPDATED', 'HR & Payroll', 'Updated corporate payroll configuration & rules');

    return {
      success: true,
      dbSynced: persistResult.dbSynced,
      backedUp: persistResult.backedUp,
      error: persistResult.error,
      sqlFix: persistResult.sqlFix,
      dbStatus: persistResult.dbStatus,
    };
  };

  const syncPayrollSettingsToSupabase = async (): Promise<{
    success: boolean;
    dbSynced: boolean;
    backedUp?: boolean;
    error?: string;
    sqlFix?: string;
    dbStatus?: PayrollSettingsDbStatus;
  }> => {
    if (
      !hasPageAction(currentUser, 'payroll', 'create_payroll') &&
      !hasPageAction(currentUser, 'payroll', 'approve_payroll')
    ) {
      return {
        success: false,
        dbSynced: false,
        error: 'Permission denied: Process Monthly Payroll or Approve Salary Sheet permission required.',
      };
    }
    const persistResult = await persistPayrollSettingsToSupabase({
      ...payrollSettings,
      updatedAt: payrollSettings.updatedAt || new Date().toISOString(),
      updatedBy: payrollSettings.updatedBy || currentUser?.name || 'Admin',
    });
    return {
      success: persistResult.dbSynced,
      dbSynced: persistResult.dbSynced,
      backedUp: persistResult.backedUp,
      error: persistResult.error,
      sqlFix: persistResult.sqlFix,
      dbStatus: persistResult.dbStatus,
    };
  };

  const updateSystemBranding = useCallback(
    async (payload: {
      softwareName: string;
      logoDataUrl: string | null;
      logoFileName?: string | null;
      logoMimeType?: string | null;
    }): Promise<{
      success: boolean;
      error?: string;
      branding?: SystemBrandingConfig;
      dbSynced?: boolean;
      dbStatus?: SystemSettingsDbStatus;
    }> => {
      const sendRequest = async () => {
        return fetch('/api/system-settings/branding', {
          method: 'PUT',
          headers: getErpAuthHeaders(),
          body: JSON.stringify(payload),
        });
      };

      try {
        let resp = await sendRequest();
        // If server restarted and local-only session hasn't re-registered yet, re-establish session once and retry
        if (resp.status === 401 && isAuthenticated && currentUser?.id && currentUser.id !== 'guest') {
          await establishServerSession(currentUser);
          resp = await sendRequest();
        }

        const data = await resp.json().catch(() => ({}));
        if (!resp.ok) {
          return {
            success: false,
            error: data?.error || `Failed to save system branding (HTTP ${resp.status}).`,
          };
        }

        const nextSettings = normalizeSystemSettings(
          data?.settings || {
            id: 'default',
            branding: data?.branding || payload,
          }
        );
        setSystemSettings(nextSettings);
        try {
          localStorage.setItem(SYSTEM_SETTINGS_CACHE_KEY, JSON.stringify(nextSettings));
        } catch {}

        let finalDbStatus: SystemSettingsDbStatus = data?.dbStatus || {
          synced: Boolean(data?.dbSynced),
          status: data?.dbSynced ? 'synced' : 'unknown',
          error: null,
          sqlFix: null,
        };

        // If browser uses a custom Supabase URL, also upsert directly from browser client
        const client = getSupabase();
        const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;
        if (client && usingCustomSupabase) {
          const { error: clientErr } = await client.from('system_settings').upsert(
            {
              id: 'default',
              software_name: nextSettings.branding.softwareName,
              logo_data_url: nextSettings.branding.logoDataUrl,
              branding_json: nextSettings.branding,
              settings_json: { branding: nextSettings.branding },
              updated_by: nextSettings.updatedBy || nextSettings.branding.updatedBy || currentUser?.name || 'Admin',
              updated_at: nextSettings.updatedAt || nextSettings.branding.updatedAt || new Date().toISOString(),
            },
            { onConflict: 'id' }
          );
          finalDbStatus = clientErr
            ? classifyClientSupabaseSettingsError(clientErr)
            : { synced: true, status: 'synced', error: null, sqlFix: null };
        }

        setSystemSettingsDbStatus(finalDbStatus);

        addAuditLog(
          'SYSTEM_BRANDING_UPDATED',
          'System Settings',
          `Updated global Software Name to "${nextSettings.branding.softwareName}"${
            nextSettings.branding.logoDataUrl ? ' with custom logo' : ' (default icon)'
          }`
        );

        return {
          success: true,
          branding: nextSettings.branding,
          dbSynced: Boolean(finalDbStatus.synced),
          dbStatus: finalDbStatus,
        };
      } catch (err: any) {
        return {
          success: false,
          error: err?.message || 'Network error while updating system branding.',
        };
      }
    },
    [getErpAuthHeaders, isAuthenticated, currentUser, establishServerSession, classifyClientSupabaseSettingsError]
  );

  const syncSystemSettingsToDatabase = useCallback(async (): Promise<{
    success: boolean;
    dbSynced: boolean;
    dbStatus?: SystemSettingsDbStatus;
    error?: string;
  }> => {
    const sendSync = async () => {
      return fetch('/api/system-settings/sync', {
        method: 'POST',
        headers: getErpAuthHeaders(),
        body: JSON.stringify({}),
      });
    };

    try {
      let resp = await sendSync();
      if (resp.status === 401 && isAuthenticated && currentUser?.id && currentUser.id !== 'guest') {
        await establishServerSession(currentUser);
        resp = await sendSync();
      }

      const data = await resp.json().catch(() => ({}));
      if (!resp.ok) {
        return {
          success: false,
          dbSynced: false,
          error: data?.error || `Failed to sync system settings (HTTP ${resp.status}).`,
        };
      }

      let finalDbStatus: SystemSettingsDbStatus = data?.dbStatus || {
        synced: Boolean(data?.dbSynced),
        status: data?.dbSynced ? 'synced' : 'error',
        error: null,
        sqlFix: SYSTEM_SETTINGS_TABLE_SQL,
      };

      const settingsToPersist = data?.settings
        ? normalizeSystemSettings(data.settings)
        : systemSettings;

      const client = getSupabase();
      const usingCustomSupabase = getSupabaseUrl() !== DEFAULT_SUPABASE_URL;
      if (client && usingCustomSupabase) {
        const { error: clientErr } = await client.from('system_settings').upsert(
          {
            id: 'default',
            software_name: settingsToPersist.branding.softwareName,
            logo_data_url: settingsToPersist.branding.logoDataUrl,
            branding_json: settingsToPersist.branding,
            settings_json: { branding: settingsToPersist.branding },
            updated_by: settingsToPersist.updatedBy || settingsToPersist.branding.updatedBy || currentUser?.name || 'Admin',
            updated_at: settingsToPersist.updatedAt || settingsToPersist.branding.updatedAt || new Date().toISOString(),
          },
          { onConflict: 'id' }
        );
        finalDbStatus = clientErr
          ? classifyClientSupabaseSettingsError(clientErr)
          : { synced: true, status: 'synced', error: null, sqlFix: null };
      }

      setSystemSettings(settingsToPersist);
      setSystemSettingsDbStatus(finalDbStatus);
      try {
        localStorage.setItem(SYSTEM_SETTINGS_CACHE_KEY, JSON.stringify(settingsToPersist));
      } catch {}

      return {
        success: Boolean(finalDbStatus.synced),
        dbSynced: Boolean(finalDbStatus.synced),
        dbStatus: finalDbStatus,
        error: finalDbStatus.error || undefined,
      };
    } catch (err: any) {
      return {
        success: false,
        dbSynced: false,
        error: err?.message || 'Network error while syncing system settings to database.',
      };
    }
  }, [getErpAuthHeaders, isAuthenticated, currentUser, establishServerSession, systemSettings, classifyClientSupabaseSettingsError]);

